const App: React.FC = () => {
  const [userData, setUserData] = useState<UserProfile | null>(null);
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.FEED);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  // Load user data from local storage or initialize new
  useEffect(() => {
    const savedData = localStorage.getItem('studygram_user');
    if (savedData) {
      setUserData(JSON.parse(savedData));
    }
    setIsLoading(false);
  }, []);

  // Persist user data
  useEffect(() => {
    if (userData) {
      localStorage.setItem('studygram_user', JSON.stringify(userData));
    }
  }, [userData]);

  const showToast = useCallback((message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  }, []);

  const handleAddExp = useCallback((amount: number) => {
    setUserData(prev => {
      if (!prev) return null;
      return { ...prev, exp: prev.exp + amount };
    });
    showToast(`+${amount} EXP!`, 'success');
  }, [showToast]);

  const handleOnboarding = (name: string) => {
    const newUser: UserProfile = {
      uid: Math.random().toString(36).substr(2, 9),
      name: name,
      avatar: `https://api.dicebear.com/7.x/notionists/svg?seed=${name}`,
      exp: 0,
      bio: 'Người học việc mới gia nhập',
      joinedAt: Date.now(),
      streak: 1,
      completedQuizzes: 0
    };
    setUserData(newUser);
  };

  if (isLoading) return <LoadingScreen />;
  if (!userData) return <Onboarding onComplete={handleOnboarding} />;

  return (
    <div className="min-h-screen bg-[#FDFCF8] text-slate-800 font-sans selection:bg-indigo-100 flex flex-col">
      {toast && <Toast toast={toast} />}

      <Sidebar 
        isOpen={sidebarOpen} 
        onClose={() => setSidebarOpen(false)} 
        userData={userData}
        setActiveTab={(tab) => { setActiveTab(tab); setSidebarOpen(false); }}
        activeTab={activeTab}
      />

      <Header 
        onOpenMenu={() => setSidebarOpen(true)} 
        userData={userData} 
        activeTab={activeTab}
      />

      <main className={`flex-1 flex flex-col w-full max-w-3xl mx-auto transition-all duration-300 ${activeTab === AppTab.TUTOR ? 'h-[calc(100vh-64px-80px)] overflow-hidden' : 'p-4 md:p-6 pb-24 mt-16'}`}>
        {activeTab === AppTab.FEED && (
          <Feed userData={userData} onExp={handleAddExp} />
        )}
        {activeTab === AppTab.TUTOR && (
          <AITutor userData={userData} onExp={handleAddExp} />
        )}
        {activeTab === AppTab.FOCUS && (
          <FocusZone onExp={handleAddExp} showToast={showToast} />
        )}
        {activeTab === AppTab.QUIZ && (
          <QuizArena onExp={handleAddExp} showToast={showToast} />
        )}
        {activeTab === AppTab.RANK && (
          <Leaderboard currentUid={userData.uid} />
        )}
        {activeTab === AppTab.PROFILE && (
          <Profile userData={userData} />
        )}
      </main>

      <BottomNav activeTab={activeTab} setActiveTab={setActiveTab} />
    </div>
  );
};

