            <div className="flex items-center gap-2 mt-0.5">
              <span className="text-[10px] bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded-full font-bold">
                {post.category}
              </span>
              <span className="text-[10px] text-slate-400 font-medium">
                {new Date(post.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </span>
            </div>
          </div>
        </div>
      </div>

      <p className="text-slate-700 text-sm leading-relaxed mb-4 whitespace-pre-wrap">
        {post.content}
      </p>

      {post.aiAnalysis && (
        <div className="p-4 bg-gradient-to-br from-indigo-50 to-white border border-indigo-100 rounded-2xl mb-4 text-xs italic text-indigo-800 shadow-inner">
          <div className="flex items-center gap-2 mb-1.5 not-italic font-bold text-indigo-600 uppercase tracking-wider text-[9px]">
            <Sparkles size={12} /> AI Insight
          </div>
          {post.aiAnalysis}
