      )}

      <div className="flex items-center gap-6 pt-3 border-t border-slate-50">
        <button 
          onClick={onLike}
          className={`flex items-center gap-1.5 text-xs font-bold transition-all active:scale-90 ${
            isLiked ? 'text-pink-500' : 'text-slate-400 hover:text-slate-600'
          }`}
        >
          <Heart size={18} className={isLiked ? 'fill-pink-500' : ''} />
