import React, { useState, useEffect, useCallback } from 'react';
import { Clock, Play, Pause, RotateCcw, Award } from 'lucide-react';

interface FocusZoneProps {
  onExp: (amount: number) => void;
  showToast: (message: string) => void;
}

const FocusZone: React.FC<FocusZoneProps> = ({ onExp, showToast }) => {
  const [seconds, setSeconds] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);
  const [mode, setMode] = useState<'study' | 'break'>('study');

  useEffect(() => {
    let interval: any = null;
    if (isActive && seconds > 0) {
      interval = setInterval(() => {
        setSeconds(s => s - 1);
      }, 1000);
    } else if (seconds === 0) {
      setIsActive(false);
      if (mode === 'study') {
        onExp(50);
        showToast("Tập trung hoàn thành! +50 EXP 🌟");
        setMode('break');
        setSeconds(5 * 60);
      } else {
        showToast("Hết giờ nghỉ! Sẵn sàng học tiếp chưa?");
        setMode('study');
        setSeconds(25 * 60);
      }
    }
    return () => clearInterval(interval);
  }, [isActive, seconds, mode, onExp, showToast]);

  const toggleTimer = () => setIsActive(!isActive);

  const resetTimer = () => {
    setIsActive(false);
    setSeconds(mode === 'study' ? 25 * 60 : 5 * 60);
  };

  const setTimerMode = (newMode: 'study' | 'break') => {
    setIsActive(false);
    setMode(newMode);
    setSeconds(newMode === 'study' ? 25 * 60 : 5 * 60);
  };

  const formatTime = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const progress = ((mode === 'study' ? 25 * 60 : 5 * 60) - seconds) / (mode === 'study' ? 25 * 60 : 5 * 60) * 100;

  return (
    <div className="flex flex-col items-center justify-center h-full gap-8 py-10 animate-slide-in">
      <div className="flex bg-white p-1.5 rounded-2xl shadow-sm border border-slate-100">
        <button 
          onClick={() => setTimerMode('study')}
          className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${mode === 'study' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400'}`}
        >
          HỌC TẬP
        </button>
        <button 
          onClick={() => setTimerMode('break')}
          className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${mode === 'break' ? 'bg-teal-500 text-white shadow-md' : 'text-slate-400'}`}
        >
          NGHỈ NGƠI
        </button>
      </div>

      <div className="relative flex items-center justify-center w-72 h-72">
        {/* Progress Ring */}
        <svg className="absolute w-full h-full -rotate-90">
          <circle 
            cx="144" cy="144" r="130" 
            className="fill-none stroke-slate-100 stroke-[10]"
          />
          <circle 
            cx="144" cy="144" r="130" 
            className={`fill-none stroke-[10] transition-all duration-1000 ease-linear ${mode === 'study' ? 'stroke-indigo-600' : 'stroke-teal-500'}`}
            strokeDasharray={816}
            strokeDashoffset={816 - (816 * progress) / 100}
            strokeLinecap="round"
          />
        </svg>

        <div className="text-center z-10">
          <div className="text-6xl font-black text-slate-800 font-mono tracking-tighter mb-2">
            {formatTime(seconds)}
          </div>
          <div className={`text-[10px] font-black uppercase tracking-[0.2em] ${mode === 'study' ? 'text-indigo-400' : 'text-teal-400'}`}>
            {isActive ? 'Đang đếm ngược...' : 'Đã tạm dừng'}
          </div>
        </div>
      </div>

      <div className="flex items-center gap-4">
        <button 
          onClick={resetTimer}
          className="p-4 bg-white text-slate-400 rounded-3xl border border-slate-100 shadow-sm hover:text-slate-600 transition-all"
        >
          <RotateCcw size={24} />
        </button>

        <button 
          onClick={toggleTimer} 
          className={`px-12 py-5 rounded-[2rem] font-black text-white shadow-2xl transition-all active:scale-95 flex items-center gap-3 ${
            isActive ? 'bg-slate-800 shadow-slate-200' : 'bg-indigo-600 shadow-indigo-100'
          }`}
        >
          {isActive ? <><Pause size={24} fill="currentColor" /> TẠM DỪNG</> : <><Play size={24} fill="currentColor" /> BẮT ĐẦU</>}
        </button>

        <div className="p-4 opacity-0 pointer-events-none">
          <RotateCcw size={24} />
        </div>
      </div>

      <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm max-w-xs text-center">
        <div className="flex items-center justify-center gap-2 text-indigo-600 font-black text-sm mb-1 uppercase tracking-wider">
          <Award size={18} /> Phần thưởng
        </div>
        <p className="text-slate-400 text-xs font-medium">Hoàn thành 25 phút tập trung để nhận 50 EXP và duy trì Streak của bạn!</p>
      </div>
    </div>
  );
};

