import React, { useState, useEffect } from 'react';
import { Plus, Heart, Sparkles, MessageCircle, X, ChevronDown, Send } from 'lucide-react';
import { Post, UserProfile, Comment } from '../types';
import { STUDY_CATEGORIES } from '../constants';
import { analyzeStudyPost } from '../services/geminiService';

interface FeedProps {
  userData: UserProfile;
  onExp: (amount: number) => void;
}

const Feed: React.FC<FeedProps> = ({ userData, onExp }) => {
  const [posts, setPosts] = useState<Post[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    const savedPosts = localStorage.getItem('studygram_posts');
    if (savedPosts) {
      setPosts(JSON.parse(savedPosts));
    } else {
      const initialPosts: Post[] = [
        {
          id: '1',
          uid: 'system',
          userName: 'Admin Study',
          avatar: 'https://api.dicebear.com/7.x/notionists/svg?seed=Admin',
          content: 'Hôm nay các bạn học được điều gì mới không? Hãy chia sẻ để cùng nhau tiến bộ nhé! 📚✨',
          category: 'Toán học',
          createdAt: Date.now() - 1000 * 60 * 60,
          likes: [],
          comments: []
        }
      ];
      setPosts(initialPosts);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('studygram_posts', JSON.stringify(posts));
  }, [posts]);

  const handleCreatePost = (content: string, category: string) => {
    const newPost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      uid: userData.uid,
      userName: userData.name,
      avatar: userData.avatar,
      content,
      category,
      createdAt: Date.now(),
      likes: [],
      comments: []
    };
    setPosts([newPost, ...posts]);
    onExp(20);
    setIsModalOpen(false);
  };

  const toggleLike = (postId: string) => {
    setPosts(prev => prev.map(p => {
      if (p.id !== postId) return p;
      const alreadyLiked = p.likes.includes(userData.uid);
      return {
        ...p,
        likes: alreadyLiked 
          ? p.likes.filter(id => id !== userData.uid) 
          : [...p.likes, userData.uid]
      };
    }));
  };

  const handleAddComment = (postId: string, content: string) => {
    const newComment: Comment = {
      id: Math.random().toString(36).substr(2, 9),
      userName: userData.name,
      avatar: userData.avatar,
      content,
      createdAt: Date.now()
    };

    setPosts(prev => prev.map(p => {
      if (p.id !== postId) return p;
      return {
        ...p,
        comments: [...(p.comments || []), newComment]
      };
    }));
    onExp(2);
  };

  const handleAIAnalysis = async (postId: string) => {
    const post = posts.find(p => p.id === postId);
    if (!post || post.aiAnalysis) return;

    setPosts(prev => prev.map(p => p.id === postId ? { ...p, aiAnalysis: 'Đang suy nghĩ...' } : p));
    const analysis = await analyzeStudyPost(post.content);
    setPosts(prev => prev.map(p => p.id === postId ? { ...p, aiAnalysis: analysis } : p));
  };

  return (
    <div className="space-y-6">
      <div 
        onClick={() => setIsModalOpen(true)} 
        className="bg-white p-4 rounded-3xl border border-slate-100 shadow-sm flex items-center gap-4 cursor-pointer hover:border-indigo-200 transition-all group"
      >
        <img src={userData.avatar} className="w-10 h-10 rounded-full bg-slate-100" />
        <div className="flex-1 text-slate-400 text-sm font-medium">Hôm nay bạn đã học gì rồi? Chia sẻ nào...</div>
        <div className="p-2 bg-indigo-50 text-indigo-600 rounded-xl group-hover:scale-110 transition-transform">
          <Plus size={20} />
        </div>
      </div>

      <div className="space-y-4">
        {posts.map(post => (
          <PostCard 
            key={post.id} 
            post={post} 
            currentUserId={userData.uid}
            onLike={() => toggleLike(post.id)} 
            onAnalyze={() => handleAIAnalysis(post.id)}
            onComment={(content) => handleAddComment(post.id, content)}
          />
        ))}
      </div>

      {isModalOpen && (
        <CreatePostModal 
          userData={userData}
          onClose={() => setIsModalOpen(false)} 
          onSubmit={handleCreatePost} 
        />
      )}
    </div>
  );
};

const PostCard: React.FC<{ 
