interface FeedProps {
  userData: UserProfile;
  onExp: (amount: number) => void;
}

const Feed: React.FC<FeedProps> = ({ userData, onExp }) => {
  const [posts, setPosts] = useState<Post[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    const savedPosts = localStorage.getItem('studygram_posts');
    if (savedPosts) {
      setPosts(JSON.parse(savedPosts));
    } else {
      const initialPosts: Post[] = [
        {
          id: '1',
          uid: 'system',
          userName: 'Hệ thống StudyGram',
          avatar: 'https://api.dicebear.com/7.x/notionists/svg?seed=Admin',
          content: 'Chào mừng bạn đến với phiên bản StudyGram Perfect! 🚀\n\nBạn có biết: Khi giải thích kiến thức cho người khác, bạn sẽ ghi nhớ được tới 90% thông tin đó? Hãy bắt đầu chia sẻ ngay nhé!',
          category: 'Tin học',
          createdAt: Date.now() - 3600000,
          likes: ['user-1'],
          comments: []
        }
      ];
      setPosts(initialPosts);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('studygram_posts', JSON.stringify(posts));
  }, [posts]);

  const handleCreatePost = (content: string, category: string) => {
    const newPost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      uid: userData.uid,
      userName: userData.name,
      avatar: userData.avatar,
      content,
      category,
      createdAt: Date.now(),
      likes: [],
      comments: []
    };
    setPosts([newPost, ...posts]);
    // @ts-ignore
    window.confetti({ particleCount: 100, spread: 70, origin: { y: 0.6 }, colors: ['#6366f1', '#a855f7'] });
    onExp(25);
    setIsModalOpen(false);
  };

  const toggleLike = (postId: string) => {
    setPosts(prev => prev.map(p => {
      if (p.id !== postId) return p;
      const alreadyLiked = p.likes.includes(userData.uid);
      return {
        ...p,
        likes: alreadyLiked ? p.likes.filter(id => id !== userData.uid) : [...p.likes, userData.uid]
      };
    }));
  };

  const handleAddComment = (postId: string, content: string) => {
    const newComment: Comment = {
      id: Math.random().toString(36).substr(2, 9),
      userName: userData.name,
      avatar: userData.avatar,
      content,
      createdAt: Date.now()
    };
    setPosts(prev => prev.map(p => {
      if (p.id !== postId) return p;
      return { ...p, comments: [...(p.comments || []), newComment] };
    }));
    onExp(5);
  };

  const handleAIAnalysis = async (postId: string) => {
    const post = posts.find(p => p.id === postId);
    if (!post || post.aiAnalysis) return;

    setPosts(prev => prev.map(p => p.id === postId ? { ...p, aiAnalysis: 'Đang suy nghĩ...' } : p));
    const analysis = await analyzeStudyPost(post.content);
    setPosts(prev => prev.map(p => p.id === postId ? { ...p, aiAnalysis: analysis } : p));
  };

  return (
    <div className="space-y-6 max-w-2xl mx-auto">
      {/* Create Post Header */}
      <div 
        onClick={() => setIsModalOpen(true)} 
        className="glass p-5 rounded-[2rem] shadow-sm flex items-center gap-4 cursor-pointer hover:shadow-md transition-all group border-white"
      >
        <div className="relative">
          <img src={userData.avatar} className="w-12 h-12 rounded-2xl bg-white p-0.5 border" />
          <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 border-2 border-white rounded-full"></div>
        </div>
        <div className="flex-1 text-slate-400 text-sm font-semibold">Ghi lại một bài học tâm đắc hôm nay...</div>
        <div className="flex gap-2">
            <div className="p-2.5 bg-slate-100 text-slate-500 rounded-xl group-hover:bg-indigo-50 group-hover:text-indigo-600 transition-colors">
              <ImageIcon size={18} />
            </div>
            <div className="p-2.5 bg-indigo-600 text-white rounded-xl shadow-lg shadow-indigo-100 group-hover:scale-105 transition-transform">
              <Plus size={18} />
            </div>
        </div>
      </div>

      {/* Feed List */}
      <div className="space-y-6">
        {posts.map(post => (
          <PostCard 
            key={post.id} 
            post={post} 
            currentUserId={userData.uid}
            onLike={() => toggleLike(post.id)} 
            onAnalyze={() => handleAIAnalysis(post.id)}
            onComment={(content) => handleAddComment(post.id, content)}
          />
        ))}
      </div>

      {isModalOpen && (
        <CreatePostModal 
          userData={userData}
          onClose={() => setIsModalOpen(false)} 
          onSubmit={handleCreatePost} 
        />
      )}
    </div>
  );
};

