const FocusZone: React.FC<FocusZoneProps> = ({ onExp, showToast }) => {
  const [seconds, setSeconds] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);
  const [mode, setMode] = useState<'study' | 'break'>('study');
  const [activeRadio, setActiveRadio] = useState<StudyRadio | null>(null);
  const [showPlayer, setShowPlayer] = useState(false);

  useEffect(() => {
    let interval: any = null;
    if (isActive && seconds > 0) {
      interval = setInterval(() => {
        setSeconds(s => s - 1);
      }, 1000);
    } else if (seconds === 0) {
      setIsActive(false);
      // @ts-ignore
      window.confetti({ particleCount: 150, spread: 100, origin: { y: 0.7 } });

      if (mode === 'study') {
        onExp(60);
        showToast("Tập trung xuất sắc! +60 EXP 🌟");
        setMode('break');
        setSeconds(5 * 60);
      } else {
        showToast("Thời gian nghỉ đã hết. Trở lại bàn học thôi!");
        setMode('study');
        setSeconds(25 * 60);
      }
    }
    return () => clearInterval(interval);
  }, [isActive, seconds, mode, onExp, showToast]);

  const toggleTimer = () => setIsActive(!isActive);

  const resetTimer = () => {
    setIsActive(false);
    setSeconds(mode === 'study' ? 25 * 60 : 5 * 60);
  };

  const setTimerMode = (newMode: 'study' | 'break') => {
    setIsActive(false);
    setMode(newMode);
    setSeconds(newMode === 'study' ? 25 * 60 : 5 * 60);
  };

  const formatTime = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const total = mode === 'study' ? 25 * 60 : 5 * 60;
  const progress = ((total - seconds) / total) * 100;

  return (
    <div className="flex flex-col items-center justify-center h-full gap-8 py-4 animate-slide-in max-w-2xl mx-auto pb-20">
      {/* Timer Controls */}
      <div className="glass p-2 rounded-[2rem] shadow-sm border-white flex gap-1 z-10">
        <button 
          onClick={() => setTimerMode('study')}
          className={`px-8 py-3 rounded-[1.5rem] text-xs font-black transition-all ${mode === 'study' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'text-slate-400 hover:bg-slate-50'}`}
        >
          HỌC TẬP
        </button>
        <button 
          onClick={() => setTimerMode('break')}
          className={`px-8 py-3 rounded-[1.5rem] text-xs font-black transition-all ${mode === 'break' ? 'bg-teal-500 text-white shadow-xl shadow-teal-100' : 'text-slate-400 hover:bg-slate-50'}`}
        >
          NGHỈ NGƠI
        </button>
      </div>

      {/* Main Focus Clock */}
      <div className="relative flex items-center justify-center w-72 h-72 group">
        <div className={`absolute inset-0 rounded-full blur-3xl opacity-20 transition-all duration-1000 ${isActive ? (mode === 'study' ? 'bg-indigo-500' : 'bg-teal-500 animate-pulse') : 'bg-slate-300'}`}></div>

        <svg className="absolute w-full h-full -rotate-90">
          <circle cx="144" cy="144" r="130" className="fill-none stroke-slate-100 stroke-[12]" />
          <circle 
            cx="144" cy="144" r="130" 
            className={`fill-none stroke-[12] transition-all duration-1000 ease-linear ${mode === 'study' ? 'stroke-indigo-600' : 'stroke-teal-500'}`}
            strokeDasharray={816}
            strokeDashoffset={816 - (816 * progress) / 100}
            strokeLinecap="round"
          />
        </svg>

        <div className="text-center z-10">
          <div className="text-6xl font-black text-slate-800 font-mono tracking-tighter mb-2 transition-all group-hover:scale-110">
            {formatTime(seconds)}
          </div>
          <div className={`text-[10px] font-black uppercase tracking-[0.3em] ${mode === 'study' ? 'text-indigo-400' : 'text-teal-400'}`}>
            {isActive ? <span className="flex items-center gap-1 justify-center"><Waves size={12} className="animate-pulse" /> Focus Flow</span> : 'Deep Work Zone'}
          </div>
        </div>
      </div>

      {/* Play/Reset Actions */}
      <div className="flex items-center gap-6">
        <button 
          onClick={resetTimer}
          className="p-5 bg-white text-slate-400 rounded-3xl border border-slate-100 shadow-sm hover:text-slate-600 hover:shadow-md transition-all active:scale-90"
        >
          <RotateCcw size={28} />
        </button>

        <button 
          onClick={toggleTimer} 
          className={`px-12 py-5 rounded-[2.5rem] font-black text-white shadow-2xl transition-all active:scale-95 flex items-center gap-4 text-lg ${
            isActive ? 'bg-slate-800 shadow-slate-200' : 'bg-indigo-600 shadow-indigo-100 hover:scale-105'
          }`}
        >
          {isActive ? <><Pause size={28} fill="currentColor" /> TẠM DỪNG</> : <><Play size={28} fill="currentColor" /> BẮT ĐẦU</>}
        </button>

        <button 
          onClick={() => setShowPlayer(!showPlayer)}
          className={`p-5 rounded-3xl border transition-all active:scale-90 ${showPlayer ? 'bg-indigo-50 border-indigo-200 text-indigo-600 shadow-inner' : 'bg-white border-slate-100 text-slate-400 shadow-sm'}`}
        >
          <Music size={28} className={activeRadio ? 'animate-bounce' : ''} />
        </button>
      </div>

      {/* Music Hub / Player */}
      {showPlayer && (
        <div className="w-full space-y-4 animate-slide-in">
          {/* Active Player Display */}
          {activeRadio ? (
            <div className="glass rounded-[2rem] border-white shadow-xl overflow-hidden animate-slide-in">
              <div className="aspect-video w-full bg-slate-900 flex items-center justify-center relative group">
                <iframe
                  width="100%"
                  height="100%"
                  src={`https://www.youtube.com/embed/${activeRadio.youtubeId}?autoplay=1&mute=0&controls=1`}
                  title="YouTube video player"
                  frameBorder="0"
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                  allowFullScreen
                ></iframe>
                <button 
                  onClick={() => setActiveRadio(null)}
                  className="absolute top-4 right-4 p-2 bg-black/50 text-white rounded-full hover:bg-black transition-colors"
                >
                  <X size={16} />
                </button>
              </div>
              <div className="p-6 flex items-center justify-between">
                <div>
                  <h4 className="font-black text-slate-800 text-sm">{activeRadio.title}</h4>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Đang phát trực tiếp</p>
                </div>
                <div className="flex gap-1">
                  {[1,2,3,4,5].map(i => (
                    <div key={i} className="w-1 bg-indigo-500 rounded-full h-4 animate-pulse" style={{ animationDelay: `${i * 0.1}s` }}></div>
                  ))}
                </div>
              </div>
            </div>
          ) : (
            <div className="text-center py-4">
              <div className="flex items-center justify-center gap-2 text-indigo-600 mb-6">
                <Youtube size={24} />
                <h3 className="font-black uppercase tracking-[0.2em] text-sm">Chọn nhạc học tập</h3>
              </div>
              <div className="grid grid-cols-2 gap-4">
                {STUDY_RADIOS.map((radio) => (
                  <button
                    key={radio.id}
                    onClick={() => setActiveRadio(radio)}
                    className="glass p-3 rounded-[2rem] border-white shadow-sm hover:shadow-indigo-100 hover:-translate-y-1 transition-all text-left group overflow-hidden"
                  >
                    <div className="relative mb-3 rounded-2xl overflow-hidden aspect-video">
                      <img src={radio.thumbnail} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" alt={radio.title} />
                      <div className="absolute inset-0 bg-indigo-600/20 group-hover:bg-indigo-600/0 transition-colors"></div>
                      <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                        <Play size={24} className="text-white fill-white" />
                      </div>
                    </div>
                    <h5 className="font-black text-slate-800 text-[11px] truncate mb-1">{radio.title}</h5>
                    <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter line-clamp-1">{radio.description}</p>
                  </button>
                ))}
              </div>
            </div>
          )}
