      )}

      {/* Rewards Tip */}
      {!showPlayer && (
        <div className="glass p-6 rounded-[2.5rem] border-white shadow-sm w-full text-center flex items-center justify-between animate-slide-in">
          <div className="flex items-center gap-4 text-left">
            <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600">
              <Award size={24} />
