                    <div className="flex justify-between items-center mb-1">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Kết quả gợi ý</span>
                        <button onClick={() => setSearchResults([])} className="text-[10px] font-black text-indigo-600 hover:underline">Đóng</button>
                    </div>
                    {searchResults.map((video) => (
                        <button 
                            key={video.id}
                            onClick={() => playVideo(video)}
                            className="flex items-center gap-4 p-3 bg-white border border-slate-100 rounded-2xl hover:border-indigo-300 hover:shadow-lg transition-all text-left group overflow-hidden relative"
                        >
                            <div className="relative w-24 h-14 shrink-0 overflow-hidden rounded-lg">
                                <img src={video.thumbnail} className="w-full h-full object-cover shadow-sm group-hover:scale-110 transition-transform" />
                                <div className="absolute inset-0 bg-indigo-600/20 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                                    <PlayCircle size={20} className="text-white" />
                                </div>
                            </div>
                            <div className="flex-1 overflow-hidden">
                                <h5 className="font-black text-slate-700 text-[11px] truncate group-hover:text-indigo-600 leading-snug">{video.title}</h5>
                                <p className="text-[9px] text-slate-400 font-bold uppercase mt-1 flex items-center gap-1">
                                    <Play size={8} fill="currentColor" /> Click để nghe ngay
                                </p>
                            </div>
                        </button>
                    ))}
                </div>
            )}
          </div>

          {/* Quick Selection & History */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
             {/* Presets */}
             <div className="glass p-5 rounded-[2.5rem] border-white shadow-sm flex flex-col">
                <div className="flex items-center gap-2 mb-4 border-b border-slate-50 pb-2">
                    <Stars size={16} className="text-indigo-500" />
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Gợi ý sẵn có</span>
                </div>
                <div className="space-y-3">
                    {PRESET_RADIOS.map(r => (
                        <button 
                            key={r.id} 
                            onClick={() => playVideo(r)} 
                            className={`w-full flex items-center gap-3 p-2 rounded-2xl transition-all group ${activeRadio?.youtubeId === r.youtubeId ? 'bg-indigo-50 border border-indigo-100' : 'hover:bg-slate-50 border border-transparent'}`}
                        >
                            <img src={r.thumbnail} className="w-10 h-10 rounded-xl object-cover shrink-0 shadow-sm" />
                            <div className="text-left overflow-hidden">
                                <span className={`text-[10px] font-black block truncate ${activeRadio?.youtubeId === r.youtubeId ? 'text-indigo-600' : 'text-slate-600'}`}>{r.title}</span>
                                <span className="text-[8px] font-bold text-slate-300 uppercase">Station</span>
                            </div>
                        </button>
                    ))}
                </div>
             </div>

             {/* History */}
             <div className="glass p-5 rounded-[2.5rem] border-white shadow-sm flex flex-col">
                <div className="flex items-center gap-2 mb-4 border-b border-slate-50 pb-2">
                    <History size={16} className="text-slate-400" />
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Vừa nghe gần đây</span>
                </div>
                <div className="space-y-3 max-h-[220px] overflow-y-auto pr-2 custom-scrollbar">
                    {history.length > 0 ? history.map(r => (
                        <button 
                            key={r.id} 
                            onClick={() => playVideo(r)} 
                            className="w-full flex items-center gap-3 p-2 rounded-2xl hover:bg-slate-50 transition-all group"
                        >
                            <img src={r.thumbnail} className="w-10 h-10 rounded-xl object-cover shrink-0 grayscale group-hover:grayscale-0 transition-all" />
                            <div className="text-left overflow-hidden">
                                <span className="text-[10px] font-black text-slate-600 truncate block">{r.title}</span>
                                <span className="text-[8px] font-bold text-slate-300 uppercase">Lịch sử</span>
                            </div>
                        </button>
                    )) : (
                        <div className="h-32 flex flex-col items-center justify-center gap-3 text-center">
                            <div className="w-10 h-10 bg-slate-50 rounded-full flex items-center justify-center text-slate-200">
                                <History size={20} />
                            </div>
                            <span className="text-[9px] text-slate-300 font-black uppercase tracking-widest">Trống trải</span>
                        </div>
                    )}
                </div>
             </div>
          </div>
        </div>
      )}

      {/* Focus Tip Card */}
      {!showPlayer && (
        <div className="glass p-6 rounded-[2.5rem] border-white shadow-sm w-full flex items-center justify-between animate-slide-in shrink-0 hover:shadow-indigo-50 transition-all group">
          <div className="flex items-center gap-4">
            <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600 group-hover:scale-110 transition-transform">
              <Award size={28} />
            </div>
            <div>
              <h4 className="font-black text-slate-800 text-sm uppercase tracking-tight">Focus Mastery</h4>
              <p className="text-[10px] text-slate-400 font-bold uppercase mt-0.5">Mẹo: Nhạc không lời giúp tăng 40% hiệu suất</p>
            </div>
          </div>
          <button 
            onClick={() => setShowPlayer(true)}
            className="p-3 bg-slate-50 text-slate-400 rounded-2xl hover:bg-indigo-600 hover:text-white transition-all shadow-sm"
          >
            <Music size={20} />
          </button>
        </div>
      )}
    </div>
  );
};

export default FocusZone;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Clock, Play, Pause, RotateCcw, Award, Music, Waves, 
  ChevronRight, X, Youtube, Search, Link as LinkIcon, 
  History, Zap, Loader2, PlayCircle, Volume2, Stars,
  Music2, FastForward, Disc
} from 'lucide-react';
import { searchYoutubeVideos } from '../services/geminiService';

interface FocusZoneProps {
  onExp: (amount: number) => void;
  showToast: (message: string) => void;
}

interface StudyRadio {
  id: string;
  title: string;
  youtubeId: string;
  thumbnail: string;
}

const PRESET_RADIOS: StudyRadio[] = [
  { id: 'lofi', title: 'Lofi Girl - Study Beats', youtubeId: 'jfKfPfyJRdk', thumbnail: 'https://img.youtube.com/vi/jfKfPfyJRdk/0.jpg' },
  { id: 'piano', title: 'Classical Piano Masterpieces', youtubeId: '4oZ8I9yS5-M', thumbnail: 'https://img.youtube.com/vi/4oZ8I9yS5-M/0.jpg' },
  { id: 'rain', title: 'Heavy Rain in Coffee Shop', youtubeId: 'v8v1Uv_fE8s', thumbnail: 'https://img.youtube.com/vi/v8v1Uv_fE8s/0.jpg' },
  { id: 'alpha', title: 'Alpha Waves for Focus', youtubeId: 'WPni755-Krg', thumbnail: 'https://img.youtube.com/vi/WPni755-Krg/0.jpg' },
];

const FocusZone: React.FC<FocusZoneProps> = ({ onExp, showToast }) => {
  const [seconds, setSeconds] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);
  const [mode, setMode] = useState<'study' | 'break'>('study');
  const [activeRadio, setActiveRadio] = useState<StudyRadio | null>(null);
  const [showPlayer, setShowPlayer] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [searchResults, setSearchResults] = useState<StudyRadio[]>([]);
  const [history, setHistory] = useState<StudyRadio[]>([]);

  const searchInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedHistory = localStorage.getItem('studygram_music_history');
    if (savedHistory) setHistory(JSON.parse(savedHistory));
  }, []);

  useEffect(() => {
    localStorage.setItem('studygram_music_history', JSON.stringify(history));
  }, [history]);

  useEffect(() => {
    let interval: any = null;
    if (isActive && seconds > 0) {
      interval = setInterval(() => {
        setSeconds(s => s - 1);
      }, 1000);
    } else if (seconds === 0) {
      setIsActive(false);
      // @ts-ignore
      if (window.confetti) {
        // @ts-ignore
        window.confetti({ particleCount: 150, spread: 100, origin: { y: 0.7 } });
      }

      if (mode === 'study') {
        onExp(60);
        showToast("Tập trung xuất sắc! +60 EXP 🌟");
        setMode('break');
        setSeconds(5 * 60);
      } else {
        showToast("Thời gian nghỉ đã hết. Trở lại bàn học thôi!");
        setMode('study');
        setSeconds(25 * 60);
      }
    }
    return () => clearInterval(interval);
  }, [isActive, seconds, mode, onExp, showToast]);

  const toggleTimer = () => setIsActive(!isActive);

  const resetTimer = () => {
    setIsActive(false);
    setSeconds(mode === 'study' ? 25 * 60 : 5 * 60);
  };

  const setTimerMode = (newMode: 'study' | 'break') => {
    setIsActive(false);
    setMode(newMode);
    setSeconds(newMode === 'study' ? 25 * 60 : 5 * 60);
  };

  const formatTime = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const extractYoutubeId = (url: string) => {
    const regex = /(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?\/\s]{11})/i;
    const match = url.match(regex);
    return match ? match[1] : null;
  };

  const handleSearch = async () => {
    if (!searchQuery.trim()) return;

    const urlId = extractYoutubeId(searchQuery);
    if (urlId) {
      const directVideo = {
        id: 'direct-' + Date.now(),
        title: 'Video từ liên kết',
        youtubeId: urlId,
        thumbnail: `https://img.youtube.com/vi/${urlId}/0.jpg`
      };
      playVideo(directVideo);
      setSearchQuery('');
      return;
    }

    setIsSearching(true);
    try {
      const results = await searchYoutubeVideos(searchQuery);
      const mappedResults = results.map(r => ({
        id: r.id,
        title: r.title,
        youtubeId: r.id,
        thumbnail: `https://img.youtube.com/vi/${r.id}/0.jpg`
      }));
      setSearchResults(mappedResults);
    } catch (error) {
      showToast("Gặp lỗi khi tìm kiếm, thử lại sau nhé!", "error");
    } finally {
      setIsSearching(false);
    }
  };

  const playVideo = (video: StudyRadio) => {
    setActiveRadio(video);
    setHistory(prev => {
      const filtered = prev.filter(h => h.youtubeId !== video.youtubeId);
      return [video, ...filtered].slice(0, 10);
    });
    setSearchResults([]);
    setSearchQuery('');
  };

  const progress = (((mode === 'study' ? 25 * 60 : 5 * 60) - seconds) / (mode === 'study' ? 25 * 60 : 5 * 60)) * 100;

  return (
    <div className="flex flex-col items-center h-full gap-6 py-4 animate-slide-in max-w-2xl mx-auto pb-32 overflow-y-auto px-4 custom-scrollbar">
      {/* Timer Mode Selector */}
      <div className="glass p-1.5 rounded-[2rem] shadow-sm border-white flex gap-1 z-10 shrink-0">
        <button 
          onClick={() => setTimerMode('study')}
          className={`px-8 py-3 rounded-[1.5rem] text-xs font-black transition-all ${mode === 'study' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'text-slate-400 hover:bg-slate-50'}`}
        >
          HỌC TẬP
        </button>
        <button 
          onClick={() => setTimerMode('break')}
          className={`px-8 py-3 rounded-[1.5rem] text-xs font-black transition-all ${mode === 'break' ? 'bg-teal-500 text-white shadow-xl shadow-teal-100' : 'text-slate-400 hover:bg-slate-50'}`}
        >
          NGHỈ NGƠI
        </button>
      </div>

      {/* Timer Display */}
      <div className="relative flex items-center justify-center w-64 h-64 group shrink-0 mt-2">
        <div className={`absolute inset-0 rounded-full blur-[40px] opacity-10 transition-all duration-1000 ${isActive ? (mode === 'study' ? 'bg-indigo-500' : 'bg-teal-500 animate-pulse') : 'bg-slate-300'}`}></div>
        <svg className="absolute w-full h-full -rotate-90">
          <circle cx="128" cy="128" r="118" className="fill-none stroke-slate-100/40 stroke-[10]" />
          <circle 
            cx="128" cy="128" r="118" 
            className={`fill-none stroke-[10] transition-all duration-1000 ease-linear ${mode === 'study' ? 'stroke-indigo-600' : 'stroke-teal-500'}`}
            strokeDasharray={741}
            strokeDashoffset={741 - (741 * progress) / 100}
            strokeLinecap="round"
          />
        </svg>
        <div className="text-center z-10">
          <div className="text-5xl font-black text-slate-800 font-mono tracking-tighter mb-1 transition-all group-hover:scale-105">
            {formatTime(seconds)}
          </div>
          <div className={`text-[9px] font-black uppercase tracking-[0.3em] ${mode === 'study' ? 'text-indigo-400' : 'text-teal-400'}`}>
            {isActive ? <span className="flex items-center gap-1 justify-center"><Waves size={10} className="animate-pulse" /> Focus Flow</span> : 'Deep Work'}
          </div>
        </div>
      </div>

      {/* Control Actions */}
      <div className="flex items-center gap-6 shrink-0 mb-2">
        <button 
          onClick={resetTimer}
          className="p-4 bg-white text-slate-400 rounded-3xl border border-slate-100 shadow-sm hover:text-slate-600 hover:shadow-md transition-all active:scale-90"
        >
          <RotateCcw size={24} />
        </button>

        <button 
          onClick={toggleTimer} 
          className={`px-10 py-4 rounded-[2.2rem] font-black text-white shadow-xl transition-all active:scale-95 flex items-center gap-4 text-base ${
            isActive ? 'bg-slate-800 shadow-slate-200' : 'bg-indigo-600 shadow-indigo-100 hover:scale-105'
          }`}
        >
          {isActive ? <><Pause size={24} fill="currentColor" /> DỪNG</> : <><Play size={24} fill="currentColor" /> BẮT ĐẦU</>}
        </button>

        <button 
          onClick={() => setShowPlayer(!showPlayer)}
          className={`p-4 rounded-3xl border transition-all active:scale-90 ${showPlayer ? 'bg-indigo-50 border-indigo-200 text-indigo-600 shadow-inner' : 'bg-white border-slate-100 text-slate-400 shadow-sm'}`}
        >
          <Music size={24} className={activeRadio ? 'animate-bounce' : ''} />
        </button>
      </div>

      {/* YouTube Player (Music Mode) */}
      {showPlayer && (
        <div className="w-full space-y-4 animate-slide-in">
          {/* Audio Player Card - No Video! */}
          {activeRadio && (
            <div className="glass rounded-[2.5rem] border-white shadow-xl p-5 animate-slide-in bg-white/40 overflow-hidden relative group">
              <div className="flex items-center gap-4">
                {/* Vinyl Record Animation */}
                <div className="relative shrink-0">
                  <div className={`w-20 h-20 rounded-full border-4 border-slate-900 shadow-2xl overflow-hidden ${activeRadio ? 'animate-[spin_10s_linear_infinite]' : ''}`}>
                    <img src={activeRadio.thumbnail} className="w-full h-full object-cover" alt="Album Cover" />
                    <div className="absolute inset-0 flex items-center justify-center">
                      <div className="w-5 h-5 bg-white rounded-full border-2 border-slate-900 shadow-inner"></div>
                    </div>
                  </div>
                  <div className="absolute -bottom-1 -right-1 bg-indigo-600 text-white p-1.5 rounded-full shadow-lg">
                    <Music2 size={12} />
                  </div>
                </div>

                <div className="flex-1 min-w-0">
                  <div className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-1 flex items-center gap-1.5">
                    <span className="flex gap-0.5">
                      {[1,2,3,4].map(i => (
                        <div key={i} className="w-0.5 bg-indigo-500 rounded-full animate-bounce" style={{ height: '8px', animationDelay: `${i * 0.1}s` }}></div>
                      ))}
                    </span>
                    Now Playing
                  </div>
                  <h4 className="font-black text-slate-800 text-sm truncate">{activeRadio.title}</h4>
                  <div className="flex items-center gap-3 mt-3">
                    <button className="text-slate-400 hover:text-indigo-600 transition-colors"><Volume2 size={16} /></button>
                    <div className="flex-1 h-1 bg-slate-100 rounded-full overflow-hidden">
                      <div className="h-full bg-indigo-500 w-1/3 animate-[loading_5s_infinite_ease-in-out]"></div>
                    </div>
                    <button onClick={() => setActiveRadio(null)} className="text-slate-300 hover:text-rose-500 transition-colors"><X size={16} /></button>
                  </div>
                </div>
              </div>

              {/* Hidden YouTube Iframe to satisfy ToS while playing audio */}
              <div className="opacity-0 pointer-events-none absolute h-0 w-0 overflow-hidden">
                <iframe
                  width="1"
                  height="1"
                  src={`https://www.youtube.com/embed/${activeRadio.youtubeId}?autoplay=1&mute=0&controls=0&modestbranding=1&rel=0`}
                  title="Audio Core"
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                ></iframe>
              </div>
            </div>
          )}

          {/* Search Box - Youtube Search */}
          <div className="glass p-5 rounded-[2.2rem] border-white shadow-sm space-y-3">
            <div className="flex items-center gap-2 mb-1">
                <Youtube size={18} className="text-rose-500" />
                <h3 className="font-black text-slate-800 text-[10px] uppercase tracking-widest">Tìm kiếm âm nhạc</h3>
            </div>

            <div className="flex gap-2">
              <div className="flex-1 bg-slate-100/50 rounded-2xl border border-slate-200 flex items-center px-4 focus-within:bg-white focus-within:border-indigo-400 transition-all group shadow-inner">
                <Search size={16} className="text-slate-300 group-focus-within:text-indigo-500" />
                <input 
                  ref={searchInputRef}
                  value={searchQuery}
                  onChange={e => setSearchQuery(e.target.value)}
                  onKeyDown={e => e.key === 'Enter' && handleSearch()}
                  placeholder="Nhập tên nhạc học bài..."
                  className="bg-transparent border-none outline-none flex-1 py-3 px-2 text-sm font-bold text-slate-700 placeholder:text-slate-300"
                />
              </div>
              <button 
                onClick={handleSearch}
                disabled={!searchQuery.trim() || isSearching}
                className="p-3.5 bg-indigo-600 text-white rounded-2xl shadow-lg active:scale-95 disabled:opacity-50 transition-all"
              >
                {isSearching ? <Loader2 size={20} className="animate-spin" /> : <Zap size={20} fill="currentColor" />}
              </button>
            </div>

            {/* Search Results */}
            {searchResults.length > 0 && (
                <div className="space-y-2 mt-3 max-h-60 overflow-y-auto pr-1 custom-scrollbar animate-slide-in">
                    {searchResults.map((video) => (
                        <button 
                            key={video.id}
                            onClick={() => playVideo(video)}
                            className="w-full flex items-center gap-3 p-2.5 bg-white/80 border border-slate-50 rounded-2xl hover:border-indigo-300 hover:shadow-sm transition-all text-left group overflow-hidden"
                        >
                            <img src={video.thumbnail} className="w-16 h-10 rounded-lg object-cover shadow-sm group-hover:scale-105 transition-transform" />
                            <div className="flex-1 min-w-0">
                                <h5 className="font-black text-slate-700 text-[10px] truncate group-hover:text-indigo-600 leading-tight">{video.title}</h5>
                                <p className="text-[8px] text-slate-400 font-bold uppercase mt-1 flex items-center gap-1">
                                    <PlayCircle size={10} /> Phát ngay
                                </p>
                            </div>
                        </button>
                    ))}
                </div>
            )}
          </div>

          {/* Tabs for Presets/History */}
          <div className="grid grid-cols-2 gap-3">
             <div className="glass p-4 rounded-[1.8rem] border-white shadow-sm">
                <div className="flex items-center gap-2 mb-3">
                    <Stars size={14} className="text-indigo-400" />
                    <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Gợi ý</span>
                </div>
                <div className="space-y-2.5">
                    {PRESET_RADIOS.map(r => (
                        <button key={r.id} onClick={() => playVideo(r)} className="w-full flex items-center gap-2 group transition-all hover:translate-x-1">
                            <div className="w-7 h-7 bg-indigo-50 rounded-lg flex items-center justify-center group-hover:bg-indigo-600 group-hover:text-white transition-colors">
                                <Disc size={14} className={activeRadio?.id === r.id ? 'animate-spin' : ''} />
                            </div>
                            <span className="text-[9px] font-black text-slate-600 truncate group-hover:text-indigo-600">{r.title}</span>
                        </button>
                    ))}
                </div>
             </div>

             <div className="glass p-4 rounded-[1.8rem] border-white shadow-sm">
                <div className="flex items-center gap-2 mb-3">
                    <History size={14} className="text-slate-300" />
                    <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Gần đây</span>
                </div>
                <div className="space-y-2.5">
                    {history.length > 0 ? history.slice(0, 4).map(r => (
                        <button key={r.id} onClick={() => playVideo(r)} className="w-full flex items-center gap-2 group transition-all hover:translate-x-1">
                            <img src={r.thumbnail} className="w-7 h-7 rounded-lg object-cover grayscale group-hover:grayscale-0 transition-all" />
                            <span className="text-[9px] font-black text-slate-500 truncate group-hover:text-indigo-600">Lịch sử</span>
                        </button>
                    )) : (
                        <div className="h-20 flex items-center justify-center text-[8px] text-slate-200 font-black uppercase text-center">Trống</div>
                    )}
                </div>
             </div>
          </div>
        </div>
      )}

      {/* Focus Tip Card */}
      {!showPlayer && (
        <div 
          onClick={() => setShowPlayer(true)}
          className="glass p-5 rounded-[2.2rem] border-white shadow-sm w-full flex items-center justify-between animate-slide-in cursor-pointer hover:shadow-indigo-50 transition-all group"
        >
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600 group-hover:scale-110 transition-transform">
              <Music size={24} />
            </div>
            <div>
              <h4 className="font-black text-slate-800 text-xs uppercase tracking-tight">Vibe Học Tập</h4>
              <p className="text-[9px] text-slate-400 font-bold uppercase mt-0.5">Tìm kiếm nhạc tập trung ngay tại đây</p>
            </div>
          </div>
          <ChevronRight size={18} className="text-slate-300 group-hover:text-indigo-600 group-hover:translate-x-1 transition-all" />
        </div>
      )}

      {/* Styles for animation */}
      <style>{`
        @keyframes loading {
          0% { left: -100%; }
          100% { left: 100%; }
        }
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: rgba(99, 102, 241, 0.2);
          border-radius: 10px;
        }
      `}</style>
    </div>
  );
};

export default FocusZone;

