import { GoogleGenAI, Type } from "@google/genai";

const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const callGeminiText = async (prompt: string, systemInstruction?: string): Promise<string> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: systemInstruction || "Bạn là một trợ lý học tập thông minh, thân thiện và hài hước cho học sinh Việt Nam.",
        temperature: 0.7,
      },
    });
    return response.text || "Xin lỗi, mình đang gặp chút trục trặc trong lúc suy nghĩ.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Hệ thống AI đang bận, bạn thử lại sau nhé!";
  }
};

/* Các công cụ Study Tools mới */

export const summarizeText = async (text: string): Promise<string> => {
  const prompt = `Hãy tóm tắt đoạn văn bản sau thành các ý chính súc tích, dễ hiểu dưới dạng bullet points: "${text}"`;
  return callGeminiText(prompt, "Bạn là chuyên gia tóm tắt văn bản khoa học và giáo dục.");
};

export const generateFlashcards = async (topic: string): Promise<{front: string, back: string}[]> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Tạo 5 thẻ flashcard (mặt trước là câu hỏi/thuật ngữ, mặt sau là câu trả lời/định nghĩa) về chủ đề: "${topic}". Trả về JSON.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              front: { type: Type.STRING },
              back: { type: Type.STRING }
            },
            required: ["front", "back"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Flashcard Error:", error);
    return [];
  }
};

export const generateStudyPlan = async (goals: string): Promise<string> => {
  const prompt = `Lập một kế hoạch học tập chi tiết trong 24 giờ tới dựa trên mục tiêu sau: "${goals}". Hãy chia nhỏ thời gian và thêm các lời khuyên về nghỉ ngơi.`;
  return callGeminiText(prompt, "Bạn là chuyên gia tư vấn lộ trình học tập hiệu suất cao.");
};

/* Tìm kiếm danh sách video YouTube dựa trên từ khóa */
export const searchYoutubeVideos = async (query: string): Promise<{id: string, title: string}[]> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Tìm cho tôi 4 video YouTube phổ biến nhất về chủ đề: "${query}". Trả về danh sách JSON gồm ID video và tiêu đề rút gọn.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING, description: "YouTube Video ID" },
              title: { type: Type.STRING, description: "Tên video rút gọn" }
            },
            required: ["id", "title"]
          }
        }
      }
    });

    const results = JSON.parse(response.text || "[]");
    return results;
  } catch (error) {
    console.error("Search Error:", error);
    return [];
  }
};

export const analyzeStudyImage = async (base64Image: string, prompt: string): Promise<string> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Image.split(',')[1], mimeType: 'image/jpeg' } },
          { text: prompt || "Hãy giải bài tập trong ảnh này và giải thích chi tiết từng bước cho mình nhé." }
        ]
      },
      config: {
        systemInstruction: "Bạn là một gia sư giỏi đa năng. Hãy phân tích hình ảnh bài tập, đưa ra đáp án chính xác và giải thích cách làm một cách dễ hiểu nhất."
      }
    });
    return response.text || "Mình không đọc được đề bài trong ảnh này, bạn chụp rõ hơn được không?";
  } catch (error) {
    console.error("Gemini Vision Error:", error);
    return "Gặp lỗi khi phân tích ảnh bài tập rồi!";
  }
};

export const analyzeStudyPost = async (content: string): Promise<string> => {
