                    <span className="text-xs font-extrabold text-slate-800">{comment.userName}</span>
                    <span className="text-[9px] text-slate-400 font-bold uppercase">{new Date(comment.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
