                  <p className="text-sm text-slate-600 font-medium">{comment.content}</p>
                </div>
              </div>
            ))}
          </div>

          <div className={`flex items-center gap-3 bg-white p-2 rounded-2xl border border-slate-100 focus-within:ring-2 transition-all ${isStory ? 'focus-within:ring-rose-100' : 'focus-within:ring-indigo-100'}`}>
            <input 
              value={commentInput}
              onChange={(e) => setCommentInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSendComment()}
