import { GoogleGenAI, Type } from "@google/genai";

// Sử dụng model ổn định nhất để tránh lỗi "busy"
const DEFAULT_MODEL = 'gemini-2.5-flash-preview-09-2025';

const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

/**
 * Cơ chế gọi AI với tính năng tự động thử lại (Retry)
 */
export const callGeminiWithRetry = async (
  prompt: string, 
  systemInstruction?: string, 
  retries = 3
): Promise<string> => {
  const ai = getAIInstance();
  let lastError: any;

  for (let i = 0; i < retries; i++) {
    try {
      const response = await ai.models.generateContent({
        model: DEFAULT_MODEL,
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: {
          systemInstruction: systemInstruction || "Bạn là một trợ lý học tập thông minh, thân thiện.",
          temperature: 0.7,
        },
      });
      return response.text || "Hệ thống không trả về kết quả.";
    } catch (error) {
      lastError = error;
      console.warn(`Lần thử ${i + 1} thất bại, đang thử lại...`, error);
      // Chờ một chút trước khi thử lại (exponential backoff)
      await new Promise(resolve => setTimeout(resolve, 1000 * Math.pow(2, i)));
    }
  }

  console.error("Tất cả lần thử gọi AI đều thất bại:", lastError);
  return "AI đang quá tải hoặc gặp lỗi kết nối. Fen vui lòng kiểm tra mạng hoặc thử lại sau vài giây nhé!";
};

export const summarizeText = async (text: string): Promise<string> => {
  const prompt = `Hãy tóm tắt đoạn văn bản sau thành các ý chính súc tích, dễ hiểu dưới dạng bullet points: "${text}"`;
  return callGeminiWithRetry(prompt, "Bạn là chuyên gia tóm tắt văn bản khoa học và giáo dục.");
};

export const generateFlashcards = async (topic: string): Promise<{front: string, back: string}[]> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: DEFAULT_MODEL,
      contents: `Tạo 5 thẻ flashcard về chủ đề: "${topic}". Trả về JSON.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              front: { type: Type.STRING },
              back: { type: Type.STRING }
            },
            required: ["front", "back"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (error) {
    return [];
  }
};

export const generateStudyPlan = async (goals: string): Promise<string> => {
  const prompt = `Lập một kế hoạch học tập chi tiết trong 24 giờ tới dựa trên mục tiêu sau: "${goals}".`;
  return callGeminiWithRetry(prompt, "Bạn là chuyên gia tư vấn lộ trình học tập hiệu suất cao.");
};

