import { GoogleGenAI, Type } from "@google/genai";

// Sử dụng model ổn định nhất để tránh lỗi "busy"
const DEFAULT_MODEL = 'gemini-2.5-flash-preview-09-2025';

const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

/**
 * Cơ chế gọi AI với tính năng tự động thử lại (Retry)
 */
export const callGeminiWithRetry = async (
  prompt: string, 
  systemInstruction?: string, 
  retries = 3
): Promise<string> => {
  const ai = getAIInstance();
  let lastError: any;

  for (let i = 0; i < retries; i++) {
    try {
      const response = await ai.models.generateContent({
        model: DEFAULT_MODEL,
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: {
          systemInstruction: systemInstruction || "Bạn là một trợ lý học tập thông minh, thân thiện.",
          temperature: 0.8, // Tăng nhẹ để câu trả lời sáng tạo hơn
        },
      });
      return response.text || "Hệ thống không trả về kết quả.";
    } catch (error) {
      lastError = error;
      console.warn(`Lần thử ${i + 1} thất bại, đang thử lại...`, error);
      await new Promise(resolve => setTimeout(resolve, 1000 * Math.pow(2, i)));
    }
  }

  console.error("Tất cả lần thử gọi AI đều thất bại:", lastError);
  return "Hơi bận xíu, nhưng vẫn luôn ở đây ủng hộ fen! ❤️";
};

/**
 * Tạo bình luận ngắn, tình cảm, phong cách Gen Z
 */
export const generateSupportiveComment = async (content: string, type: 'knowledge' | 'story'): Promise<string> => {
  const instruction = type === 'knowledge' 
    ? "Bạn là một người bạn học ngưỡng mộ kiến thức. Hãy bình luận cực ngắn (dưới 15 từ), dùng từ ngữ Gen Z (fen, đỉnh, xịn, mlem), khen ngợi và khích lệ bài đăng kiến thức này. Thêm emoji."
    : "Bạn là một người bạn tâm tình ấm áp. Hãy đọc tâm sự này và đưa ra 1 lời an ủi/thấu hiểu cực ngắn (dưới 15 từ), ngọt ngào, chân thành. Dùng từ ngữ như 'thương fen', 'cố lên nhé'. Thêm emoji trái tim.";

