      "Đừng so sánh chương 1 của mình với chương 20 của người khác. ❤️",
      "Nghỉ ngơi cũng là một phần của năng suất. Uống nước thôi nào! 🥤",
      "Học không phải là lấp đầy một cái thùng, mà là thắp sáng một ngọn lửa. 🔥"
    ];
    setAiQuote(quotes[Math.floor(Math.random() * quotes.length)]);
  }, []);

  useEffect(() => {
    localStorage.setItem('studygram_posts', JSON.stringify(posts));
  }, [posts]);

  const handleCreatePost = async (data: Partial<Post>) => {
    const newPost: Post = {
