          </div>
      </div>

      {/* Trending Bar */}
      <div className="overflow-x-auto whitespace-nowrap py-1 no-scrollbar flex gap-3 px-2">
        {hotTags.map(tag => (
          <div key={tag} className="inline-flex items-center gap-1.5 px-4 py-2 bg-white border border-slate-100 rounded-full text-[10px] font-black text-slate-500 shadow-sm hover:text-indigo-600 hover:bg-indigo-50 transition-all cursor-pointer">
            <Hash size={12} className="text-indigo-400" /> {tag.replace('#','')}
          </div>
        ))}
      </div>

      {/* Post Creator Trigger */}
      <div 
        onClick={() => setIsModalOpen(true)} 
        className="glass p-5 rounded-[2.5rem] shadow-sm flex items-center gap-4 cursor-pointer hover:shadow-md transition-all group border-white bg-white/40"
      >
        <img src={userData.avatar} className="w-12 h-12 rounded-2xl bg-white p-0.5 border" />
        <div className="flex-1 text-slate-400 text-sm font-semibold tracking-tight">Fen ơi, hôm nay học gì/tâm sự gì không?</div>
        <div className="p-3 bg-indigo-600 text-white rounded-2xl group-hover:scale-110 transition-all shadow-lg shadow-indigo-100">
          <Plus size={20} />
        </div>
      </div>

      {/* Custom Feed Tabs */}
      <div className="flex gap-2 p-1 bg-slate-200/40 rounded-3xl w-fit mx-auto border border-white">
        <button 
          onClick={() => setActiveFeedTab('knowledge')}
