                      className="w-full bg-white border border-slate-200 rounded-2xl px-5 py-3 text-xs font-black text-slate-700 outline-none focus:ring-2 focus:ring-indigo-100 appearance-none"
                  >
                      {postType === 'knowledge' 
                        ? STUDY_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)
                        : moods.map(m => <option key={m} value={m}>{m}</option>)
                      }
                  </select>
              </div>
          </div>

          <textarea 
            autoFocus
            value={content}
            onChange={e => setContent(e.target.value)}
            placeholder={postType === 'knowledge' ? "Hôm nay fen học được gì đỉnh chóp? Chia sẻ cùng anh em nhé..." : "Hôm nay fen thấy thế nào? Cứ trải lòng ra đây, có StudyGram lắng nghe..."}
            className={`w-full h-48 bg-transparent border-none outline-none text-slate-700 font-bold placeholder:text-slate-200 resize-none text-xl leading-relaxed ${postType === 'story' ? 'italic font-serif' : ''}`}
          />

          <div className="flex items-center justify-between pt-6 border-t border-slate-50">
              <button 
                onClick={() => setIsAnonymous(!isAnonymous)}
                className={`flex items-center gap-2 px-5 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${isAnonymous ? 'bg-slate-900 text-white shadow-lg shadow-slate-200' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}
              >
                  {isAnonymous ? <EyeOff size={16} /> : <Ghost size={16} />} {isAnonymous ? 'Ẩn danh: Bật' : 'Ẩn danh: Tắt'}
              </button>

              <button 
                disabled={!content.trim()}
                onClick={() => onSubmit({ content, category, type: postType, isAnonymous, mood })}
                className={`px-12 py-4 text-white rounded-[1.8rem] font-black text-sm uppercase tracking-widest shadow-xl disabled:opacity-50 transition-all active:scale-95 ${
                  postType === 'knowledge' ? 'bg-indigo-600 shadow-indigo-100' : 'bg-rose-500 shadow-rose-100'
                }`}
              >
                ĐĂNG BÀI
              </button>
          </div>
        </div>
      </div>
    </div>
  );
};

