// Sử dụng Pro cho các tác vụ cần tư duy logic cực cao
const PRO_MODEL = 'gemini-3-pro-preview';
// Sử dụng Flash cho các tác vụ phản hồi nhanh, bình luận
const FLASH_MODEL = 'gemini-3-flash-preview';

const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

/**
 * Cơ chế gọi AI với tính năng tự động thử lại (Retry) và chọn model linh hoạt
 */
export const callGeminiWithRetry = async (
  prompt: string, 
  systemInstruction?: string, 
  usePro = false,
  retries = 3
): Promise<string> => {
  const ai = getAIInstance();
  let lastError: any;

  for (let i = 0; i < retries; i++) {
    try {
      const response = await ai.models.generateContent({
        model: usePro ? PRO_MODEL : FLASH_MODEL,
        contents: prompt,
        config: {
          systemInstruction: systemInstruction || "Bạn là một trợ lý học tập siêu trí tuệ, có khả năng tư duy logic và thấu cảm sâu sắc.",
          temperature: usePro ? 0.9 : 0.7,
          thinkingConfig: usePro ? { thinkingBudget: 4000 } : undefined
        },
      });
      return response.text || "Hệ thống không trả về kết quả.";
    } catch (error) {
      lastError = error;
      console.warn(`Lần thử ${i + 1} thất bại, đang thử lại...`, error);
      await new Promise(resolve => setTimeout(resolve, 1000 * Math.pow(2, i)));
    }
  }

  console.error("Tất cả lần thử gọi AI đều thất bại:", lastError);
  return "Hơi bận xíu vì đang xử lý luồng tri thức khổng lồ, nhưng vẫn luôn ở đây ủng hộ fen! ❤️";
};

/**
 * Chế độ Tranh biện Siêu trí tuệ
 */
export const getDebateResponse = async (history: {role: string, text: string}[], topic: string): Promise<string> => {
  const systemInstruction = `Bạn là một nhà tranh biện lỗi lạc, sắc bén và công tâm. 
  Chủ đề: "${topic}". 
  Nhiệm vụ: 
  1. Phản biện lại ý kiến của người dùng một cách logic, sử dụng dẫn chứng thuyết phục.
  2. Giữ thái độ tôn trọng nhưng thách thức tư duy của họ.
  3. Trả lời dưới 100 chữ, súc tích, đanh thép.
  4. Nếu người dùng muốn kết thúc, hãy đưa ra một bảng điểm đánh giá (Logic, Thuyết phục, Ngôn từ) từ 1-10.`;

  const prompt = history.map(h => `${h.role === 'user' ? 'Người dùng' : 'Bạn'}: ${h.text}`).join('\n');
  return callGeminiWithRetry(prompt, systemInstruction, true);
};

