interface FeedProps {
  userData: UserProfile;
  onExp: (amount: number) => void;
}

const Feed: React.FC<FeedProps> = ({ userData, onExp }) => {
  const [posts, setPosts] = useState<Post[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeFeedTab, setActiveFeedTab] = useState<PostType>('knowledge');
  const [vibeData, setVibeData] = useState<Record<string, any>>({});

  useEffect(() => {
    const savedPosts = localStorage.getItem('studygram_posts');
    if (savedPosts) setPosts(JSON.parse(savedPosts));
    else {
      setPosts([{
        id: 'sys-1', uid: 'system', userName: 'StudyGram Angel', avatar: 'https://api.dicebear.com/7.x/notionists/svg?seed=Angel',
        content: 'Chào mừng các fen đến với StudyGram V4! Học tập là con đường ngắn nhất để thoát ế! 😂',
        category: 'Chung', type: 'knowledge', createdAt: Date.now(), likes: [], comments: []
      }]);
    }
  }, []);

  const handleVibeCheck = async (postId: string, content: string, imageUrl?: string) => {
    if (vibeData[postId]) return;
    setVibeData(prev => ({ ...prev, [postId]: { loading: true } }));
    try {
      const res = await checkVibePost(content, imageUrl);
      setVibeData(prev => ({ ...prev, [postId]: { ...res, loading: false } }));
      onExp(10);
      // @ts-ignore
      window.confetti({ particleCount: 30, spread: 30, origin: { y: 0.8 }, colors: ['#6366F1', '#EC4899'] });
    } catch (e) {
      setVibeData(prev => ({ ...prev, [postId]: null }));
    }
  };

  const handleCreatePost = (data: Partial<Post>) => {
    const newPost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      uid: userData.uid,
      userName: userData.name,
      avatar: userData.avatar,
      content: data.content || '', category: data.category || 'Khác',
      type: data.type || 'knowledge', createdAt: Date.now(), likes: [], comments: [],
      imageUrl: data.imageUrl,
      videoUrl: data.videoUrl
    };
    const updated = [newPost, ...posts];
    setPosts(updated);
    onExp(20);
    setIsModalOpen(false);
    localStorage.setItem('studygram_posts', JSON.stringify(updated));
  };

  return (
    <div className="space-y-6 max-w-2xl mx-auto pb-10">
      <div onClick={() => setIsModalOpen(true)} className="glass p-6 rounded-[2.5rem] shadow-xl flex items-center gap-4 cursor-pointer hover:scale-[1.02] transition-all border-white bg-white/40 group">
