        <div className="p-4 bg-indigo-600 text-white rounded-2xl shadow-lg shadow-indigo-100"><Plus size={24} /></div>
      </div>

      <div className="flex gap-2 p-1 bg-slate-200/50 rounded-full w-fit mx-auto border border-white">
        <button onClick={() => setActiveFeedTab('knowledge')} className={`flex items-center gap-2 px-8 py-3 rounded-full text-xs font-black transition-all ${activeFeedTab === 'knowledge' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}><BookOpen size={16}/> TRI THỨC</button>
        <button onClick={() => setActiveFeedTab('story')} className={`flex items-center gap-2 px-8 py-3 rounded-full text-xs font-black transition-all ${activeFeedTab === 'story' ? 'bg-rose-500 text-white shadow-lg' : 'text-slate-500'}`}><HeartHandshake size={16}/> TÂM SỰ</button>
        <button onClick={() => setActiveFeedTab('meme')} className={`flex items-center gap-2 px-8 py-3 rounded-full text-xs font-black transition-all ${activeFeedTab === 'meme' ? 'bg-amber-500 text-white shadow-lg' : 'text-slate-500'}`}><Smile size={16}/> MEME</button>
      </div>

      <div className="space-y-6">
        {posts.filter(p => p.type === activeFeedTab || activeFeedTab === 'knowledge').map(post => (
          <PostCard 
            key={post.id} post={post} currentUserId={userData.uid} 
            vibe={vibeData[post.id]} onVibeCheck={() => handleVibeCheck(post.id, post.content, post.imageUrl)}
          />
        ))}
      </div>

      {isModalOpen && <CreatePostModal userData={userData} onClose={() => setIsModalOpen(false)} onSubmit={handleCreatePost} initialType={activeFeedTab} />}
    </div>
  );
};

const PostCard: React.FC<{ post: Post; currentUserId: string; vibe: any; onVibeCheck: () => void }> = ({ post, currentUserId, vibe, onVibeCheck }) => {
  const [isLiked, setIsLiked] = useState(post.likes.includes(currentUserId));

  const getYouTubeId = (url: string) => {
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? match[2] : null;
  };

  const videoId = post.videoUrl ? getYouTubeId(post.videoUrl) : null;

  return (
    <div className={`glass rounded-[3rem] p-8 border-white shadow-xl hover:shadow-2xl transition-all animate-slide-in relative overflow-hidden group bg-white/90`}>
      <div className="flex justify-between items-start mb-6">
        <div className="flex gap-4">
          <img src={post.avatar} className="w-14 h-14 rounded-2xl border bg-white shadow-sm" />
          <div>
            <h4 className="font-black text-base text-slate-800">{post.userName}</h4>
            <span className="text-[10px] px-2.5 py-1 bg-slate-100 rounded-full font-black text-slate-400 uppercase tracking-widest mt-1 inline-block">#{post.category}</span>
          </div>
        </div>
      </div>

      <div className="text-slate-700 text-lg leading-relaxed mb-6 font-semibold whitespace-pre-wrap">{post.content}</div>

      {post.imageUrl && (
        <div className="mb-6 rounded-[2rem] overflow-hidden border-4 border-white shadow-lg">
          <img src={post.imageUrl} className="w-full h-auto max-h-[500px] object-cover" alt="StudyGram Post" />
        </div>
      )}

      {videoId && (
        <div className="mb-6 rounded-[2rem] overflow-hidden border-4 border-white shadow-lg aspect-video">
          <iframe 
            width="100%" height="100%" 
            src={`https://www.youtube.com/embed/${videoId}`} 
            title="YouTube video player" frameBorder="0" 
            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" 
            allowFullScreen
          ></iframe>
        </div>
      )}

      {vibe && (
        <div className={`mb-6 p-6 rounded-[2rem] border animate-bounce-short ${vibe.loading ? 'bg-slate-50' : 'bg-indigo-600 text-white border-indigo-400 shadow-lg'}`}>
          {vibe.loading ? (
            <div className="flex items-center gap-3 font-black text-xs text-slate-400"><Bot className="animate-spin" size={16}/> Đang soi vibe đa phương thức...</div>
          ) : (
            <div className="space-y-2">
              <div className="flex justify-between items-center">
                <span className="text-[10px] font-black uppercase tracking-[0.2em] opacity-80">AI Multi-Vibe Check</span>
                <span className="text-xl font-black">Score: {vibe.score}</span>
              </div>
              <div className="text-lg font-black italic">"{vibe.vibe}"</div>
              <p className="text-xs font-bold opacity-90">{vibe.comment}</p>
            </div>
          )}
        </div>
      )}

      <div className="flex items-center gap-6 pt-4 border-t border-slate-100/50">
        <button onClick={() => setIsLiked(!isLiked)} className={`flex items-center gap-2 text-xs font-black transition-all ${isLiked ? 'text-rose-500 scale-110' : 'text-slate-400 hover:text-rose-400'}`}>
          <Heart size={24} fill={isLiked ? 'currentColor' : 'none'} /> {post.likes.length + (isLiked ? 1 : 0)}
        </button>
        <button onClick={onVibeCheck} disabled={!!vibe} className={`ml-auto flex items-center gap-2 px-6 py-3 rounded-2xl text-[10px] font-black uppercase transition-all shadow-lg ${vibe ? 'bg-slate-100 text-slate-300 shadow-none' : 'bg-indigo-600 text-white hover:rotate-2'}`}>
