import { 
  Plus, Heart, Sparkles, MessageCircle, X, Send, 
  Bot, BookOpen, Ghost, EyeOff, LayoutGrid,
  Hash, Zap, Star, HeartHandshake, Smile, Frown, PartyPopper,
  Image as ImageIcon, Youtube, Play, ExternalLink,
  Crown, Calendar, Pin, Filter
} from 'lucide-react';
import { Post, UserProfile, Comment, PostType } from '../types';
import { STUDY_CATEGORIES } from '../constants';
