const PostCard: React.FC<{ post: Post; currentUserId: string; vibe: any; onVibeCheck: () => void; onTagClick: (t: string) => void }> = ({ post, currentUserId, vibe, onVibeCheck, onTagClick }) => {
  const [isLiked, setIsLiked] = useState(post.likes.includes(currentUserId));
  const isEvent = post.type === 'event';

  const getYouTubeId = (url: string) => {
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? match[2] : null;
  };

  const videoId = post.videoUrl ? getYouTubeId(post.videoUrl) : null;

  return (
    <div className={`glass rounded-[3rem] p-8 border-white shadow-xl hover:shadow-2xl transition-all animate-slide-in relative overflow-hidden group ${isEvent ? 'gold-shimmer-bg border-amber-200' : 'bg-white/90'}`}>
      {post.isPinned && <div className="absolute top-4 right-8 text-amber-500 animate-bounce"><Pin size={20} fill="currentColor"/></div>}

      <div className="flex justify-between items-start mb-6">
        <div className="flex gap-4">
          <img src={post.avatar} className={`w-14 h-14 rounded-2xl border bg-white shadow-sm ${isEvent ? 'border-amber-400' : ''}`} />
          <div>
            <h4 className={`font-black text-base flex items-center gap-2 ${isEvent ? 'text-amber-700' : 'text-slate-800'}`}>
                {post.userName} {isEvent && <Crown size={16} className="text-amber-500" fill="currentColor"/>}
            </h4>
            <div className="flex gap-2 mt-1">
                <span className={`text-[9px] px-2 py-0.5 rounded-full font-black uppercase tracking-widest ${isEvent ? 'bg-amber-500 text-white' : 'bg-slate-100 text-slate-400'}`}>#{post.category}</span>
                {isEvent && <span className="text-[9px] px-2 py-0.5 bg-rose-500 text-white rounded-full font-black uppercase">SỰ KIỆN HOT</span>}
            </div>
          </div>
        </div>
      </div>

      <div className={`text-lg leading-relaxed mb-4 font-semibold whitespace-pre-wrap ${isEvent ? 'text-amber-900' : 'text-slate-700'}`}>{post.content}</div>

      {post.hashtags && post.hashtags.length > 0 && (
          <div className="flex flex-wrap gap-2 mb-4">
              {post.hashtags.map(tag => (
                  <button key={tag} onClick={() => onTagClick(tag)} className={`text-xs font-black hover:scale-110 transition-transform ${isEvent ? 'text-amber-600' : 'text-indigo-500'}`}>#{tag}</button>
              ))}
          </div>
      )}

      {post.imageUrl && (
        <div className="mb-6 rounded-[2rem] overflow-hidden border-4 border-white shadow-lg">
          <img src={post.imageUrl} className="w-full h-auto max-h-[500px] object-cover" alt="Post" />
        </div>
      )}

      {videoId && (
        <div className="mb-6 rounded-[2rem] overflow-hidden border-4 border-white shadow-lg aspect-video">
          <iframe width="100%" height="100%" src={`https://www.youtube.com/embed/${videoId}`} frameBorder="0" allowFullScreen></iframe>
        </div>
      )}

      <div className="flex items-center gap-6 pt-4 border-t border-slate-100/50">
        <button onClick={() => setIsLiked(!isLiked)} className={`flex items-center gap-2 text-xs font-black transition-all ${isLiked ? 'text-rose-500 scale-110' : 'text-slate-400 hover:text-rose-400'}`}>
          <Heart size={24} fill={isLiked ? 'currentColor' : 'none'} /> {post.likes.length + (isLiked ? 1 : 0)}
        </button>
        <button onClick={onVibeCheck} disabled={!!vibe} className={`ml-auto flex items-center gap-2 px-6 py-3 rounded-2xl text-[10px] font-black uppercase transition-all shadow-lg ${vibe ? 'bg-slate-100 text-slate-300 shadow-none' : isEvent ? 'bg-amber-500 text-white' : 'bg-indigo-600 text-white'}`}>
          <Sparkles size={16}/> {vibe?.loading ? 'Đang soi...' : 'Soi bài AI'}
        </button>
      </div>

      <style>{`
        .gold-shimmer-bg {
            background: linear-gradient(135deg, #FFFDF5 0%, #FFF8E1 100%);
        }
      `}</style>
    </div>
  );
};

const CreatePostModal: React.FC<{ userData: UserProfile; onClose: () => void; onSubmit: (data: Partial<Post>) => void; initialType: PostType }> = ({ userData, onClose, onSubmit, initialType }) => {
  const [content, setContent] = useState('');
  const [postType, setPostType] = useState<PostType>(initialType);
  const [category, setCategory] = useState(STUDY_CATEGORIES[0]);
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [videoUrl, setVideoUrl] = useState('');
  const [hashtags, setHashtags] = useState<string[]>([]);
  const [tagInput, setTagInput] = useState('');
  const [isSuggesting, setIsSuggesting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSuggestTags = async () => {
    if (!content.trim()) return;
    setIsSuggesting(true);
    try {
        const tags = await suggestHashtags(content);
        setHashtags(prev => Array.from(new Set([...prev, ...tags])));
    } finally {
        setIsSuggesting(false);
    }
  };

  const addTag = () => {
      if (tagInput.trim()) {
          setHashtags(prev => Array.from(new Set([...prev, tagInput.trim().replace('#', '')])));
          setTagInput('');
      }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[100] flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-xl rounded-[3.5rem] shadow-2xl animate-slide-in overflow-hidden max-h-[90vh] overflow-y-auto">
        <div className={`p-8 border-b flex justify-between items-center sticky top-0 z-10 ${userData.isAdmin ? 'bg-amber-50 border-amber-100' : 'bg-indigo-50/50'}`}>
          <h3 className="text-2xl font-black tracking-tighter">{userData.isAdmin ? 'Lệnh Admin 🎖️' : 'Chia sẻ bài học 🧬'}</h3>
          <button onClick={onClose} className="p-3 bg-white rounded-full"><X size={24}/></button>
        </div>
        <div className="p-8 space-y-6">
          <div className="flex gap-2 p-1 bg-slate-100 rounded-full border overflow-x-auto no-scrollbar">
            {userData.isAdmin && <button onClick={() => setPostType('event')} className={`flex-1 py-3.5 rounded-full text-[10px] font-black uppercase transition-all shrink-0 px-6 ${postType === 'event' ? 'bg-amber-500 text-white shadow-lg' : 'text-slate-400'}`}>🎖️ Sự kiện</button>}
            <button onClick={() => setPostType('knowledge')} className={`flex-1 py-3.5 rounded-full text-[10px] font-black uppercase transition-all shrink-0 px-6 ${postType === 'knowledge' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}>📚 Bài học</button>
            <button onClick={() => setPostType('meme')} className={`flex-1 py-3.5 rounded-full text-[10px] font-black uppercase transition-all shrink-0 px-6 ${postType === 'meme' ? 'bg-rose-500 text-white shadow-lg' : 'text-slate-400'}`}>😂 Meme</button>
          </div>

          <div className="space-y-4">
              <select value={category} onChange={e => setCategory(e.target.value)} className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-5 py-4 text-sm font-black text-slate-700 outline-none">
                {STUDY_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
              </select>

              <textarea value={content} onChange={e => setContent(e.target.value)} placeholder="Fen đang nghĩ gì xịn xò không?" className="w-full h-32 bg-transparent outline-none text-slate-700 font-bold placeholder:text-slate-200 resize-none text-xl" />
          </div>

          <div className="space-y-4">
              <div className="flex gap-2 flex-wrap mb-2">
                  {hashtags.map(t => (
                      <span key={t} className="bg-slate-100 text-slate-600 px-3 py-1 rounded-full text-[10px] font-black flex items-center gap-2">
                          #{t} <button onClick={() => setHashtags(h => h.filter(x => x !== t))}><X size={10}/></button>
                      </span>
                  ))}
              </div>
              <div className="flex gap-2">
                  <div className="relative flex-1">
                      <Hash size={14} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                      <input value={tagInput} onChange={e => setTagInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && addTag()} placeholder="Thêm hashtag..." className="w-full pl-10 pr-4 py-3 bg-slate-50 rounded-2xl text-xs font-bold border-none outline-none focus:bg-white focus:ring-2 focus:ring-indigo-100 transition-all" />
                  </div>
                  <button onClick={handleSuggestTags} disabled={isSuggesting} className="px-4 bg-indigo-50 text-indigo-600 rounded-2xl text-[10px] font-black uppercase hover:bg-indigo-600 hover:text-white transition-all">
                      {isSuggesting ? '...' : <Sparkles size={16}/>}
                  </button>
              </div>
          </div>

          <div className="space-y-4">
            <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center justify-center gap-2 py-4 bg-slate-100 rounded-2xl text-xs font-black text-slate-500 hover:bg-indigo-50 hover:text-indigo-600 transition-all">
                <ImageIcon size={18}/> {imageUrl ? "Đổi ảnh" : "Thêm ảnh bài học"}
            </button>
            <input type="file" ref={fileInputRef} onChange={(e) => {
                const file = e.target.files?.[0];
                if (file) {
                    const reader = new FileReader();
                    reader.onloadend = () => setImageUrl(reader.result as string);
                    reader.readAsDataURL(file);
                }
            }} className="hidden" accept="image/*" />

            <div className="relative">
                <Youtube size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-rose-500" />
                <input value={videoUrl} onChange={e => setVideoUrl(e.target.value)} placeholder="Link bài giảng YouTube..." className="w-full pl-10 pr-5 py-4 bg-slate-50 rounded-2xl text-xs font-bold border-none outline-none focus:bg-white focus:ring-2 focus:ring-rose-100 transition-all" />
            </div>
          </div>

          <button onClick={() => onSubmit({ content, category, type: postType, imageUrl: imageUrl || undefined, videoUrl: videoUrl || undefined, hashtags })} disabled={!content.trim()} className={`w-full py-6 text-white rounded-[2rem] font-black text-lg shadow-2xl transition-all active:scale-95 ${userData.isAdmin ? 'bg-amber-500' : 'bg-indigo-600'}`}>
              XÁC NHẬN ĐĂNG 🔥
          </button>
        </div>
      </div>
    </div>
  );
};

