      {isModalOpen && (
        <CreatePostModal 
          userData={userData} 
          onClose={() => setIsModalOpen(false)} 
          onSubmit={handleCreatePost} 
          initialType={activeFeedTab === 'all' ? 'knowledge' : activeFeedTab as PostType} 
        />
      )}
    </div>
  );
};

const PostCard: React.FC<{ post: Post; currentUserId: string; vibe: any; onVibeCheck: () => void; onTagClick: (t: string) => void }> = ({ post, currentUserId, vibe, onVibeCheck, onTagClick }) => {
  const [isLiked, setIsLiked] = useState(post.likes.includes(currentUserId));
  const isEvent = post.type === 'event';

  const getYouTubeId = (url: string) => {
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? match[2] : null;
  };

  const videoId = post.videoUrl ? getYouTubeId(post.videoUrl) : null;

  return (
    <div className={`glass rounded-[3rem] p-8 border-white shadow-xl hover:shadow-2xl transition-all animate-slide-in relative overflow-hidden group ${isEvent ? 'gold-shimmer-bg border-amber-200' : 'bg-white/90'}`}>
      {post.isPinned && (
        <div className="absolute top-6 right-8 text-amber-500 animate-bounce flex items-center gap-1 font-black text-[10px] uppercase tracking-widest">
          <Pin size={16} fill="currentColor"/> Ghim
        </div>
      )}

      <div className="flex justify-between items-start mb-6">
        <div className="flex gap-4">
          <img 
            src={post.avatar} 
            className={`w-14 h-14 rounded-2xl border-2 bg-white shadow-sm transition-transform group-hover:scale-105 ${isEvent ? 'border-amber-400' : 'border-slate-50'}`} 
          />
          <div>
            <h4 className={`font-black text-base flex items-center gap-2 ${isEvent ? 'text-amber-700' : 'text-slate-800'}`}>
              {post.userName} 
              {isEvent && <Crown size={16} className="text-amber-500" fill="currentColor"/>}
            </h4>
            <div className="flex gap-2 mt-1">
              <span className={`text-[9px] px-2.5 py-1 rounded-full font-black uppercase tracking-widest ${isEvent ? 'bg-amber-500 text-white' : 'bg-slate-100 text-slate-400'}`}>#{post.category}</span>
              {isEvent && <span className="text-[9px] px-2.5 py-1 bg-rose-500 text-white rounded-full font-black uppercase animate-pulse">Hot Event</span>}
            </div>
          </div>
        </div>
      </div>

      <div className={`text-lg leading-relaxed mb-6 font-semibold whitespace-pre-wrap ${isEvent ? 'text-amber-900' : 'text-slate-700'}`}>{post.content}</div>

      {/* Hashtags Rendering */}
      {post.hashtags && post.hashtags.length > 0 && (
        <div className="flex flex-wrap gap-2 mb-6">
          {post.hashtags.map(tag => (
            <button 
              key={tag} 
              onClick={() => onTagClick(tag)} 
              className={`text-[10px] font-black px-3 py-1.5 rounded-xl transition-all hover:scale-110 active:scale-95 ${isEvent ? 'bg-amber-100 text-amber-600 hover:bg-amber-200' : 'bg-indigo-50 text-indigo-500 hover:bg-indigo-100'}`}
            >
              #{tag.toUpperCase()}
            </button>
          ))}
        </div>
      )}

      {post.imageUrl && (
        <div className="mb-6 rounded-[2rem] overflow-hidden border-4 border-white shadow-lg bg-slate-100">
          <img src={post.imageUrl} className="w-full h-auto max-h-[600px] object-cover" alt="StudyGram Post" />
        </div>
      )}

      {videoId && (
        <div className="mb-6 rounded-[2rem] overflow-hidden border-4 border-white shadow-lg aspect-video bg-black">
          <iframe 
            width="100%" height="100%" 
            src={`https://www.youtube.com/embed/${videoId}`} 
            frameBorder="0" 
            allowFullScreen
          ></iframe>
        </div>
      )}

      {vibe && (
        <div className={`mb-6 p-6 rounded-[2.5rem] border transition-all ${vibe.loading ? 'bg-slate-50 animate-pulse' : 'bg-indigo-600 text-white border-indigo-400 shadow-xl'}`}>
          {vibe.loading ? (
            <div className="flex items-center gap-3 font-black text-xs text-slate-400 justify-center py-2"><RefreshCw className="animate-spin" size={20}/> Soi vibe đa phương thức...</div>
          ) : (
            <div className="space-y-2">
              <div className="flex justify-between items-center mb-1">
                <span className="text-[9px] font-black uppercase tracking-[0.2em] opacity-80">AI Vision Check</span>
                <span className="text-xl font-black italic gold-text">Score: {vibe.score}/100</span>
              </div>
              <div className="text-lg font-black italic tracking-tight">"{vibe.vibe}"</div>
              <p className="text-xs font-bold opacity-90 leading-relaxed">{vibe.comment}</p>
            </div>
          )}
        </div>
      )}

      <div className="flex items-center gap-6 pt-5 border-t border-slate-100/50">
        <button onClick={() => setIsLiked(!isLiked)} className={`flex items-center gap-2 text-xs font-black transition-all ${isLiked ? 'text-rose-500 scale-110' : 'text-slate-400 hover:text-rose-400'}`}>
          <Heart size={24} fill={isLiked ? 'currentColor' : 'none'} /> {post.likes.length + (isLiked ? 1 : 0)}
        </button>
        <button onClick={onVibeCheck} disabled={!!vibe} className={`ml-auto flex items-center gap-2 px-6 py-3 rounded-2xl text-[10px] font-black uppercase transition-all shadow-lg ${vibe ? 'bg-slate-100 text-slate-300 shadow-none' : isEvent ? 'bg-amber-500 text-white shadow-amber-200' : 'bg-indigo-600 text-white shadow-indigo-200'}`}>
          <Sparkles size={16}/> {vibe?.loading ? 'Đang soi...' : 'Soi bài AI'}
