      </div>

      <style>{`
        .gold-shimmer-bg {
            background: linear-gradient(135deg, #FFFDF5 0%, #FFF8E1 100%);
        }
      `}</style>
    </div>
  );
};

const CreatePostModal: React.FC<{ userData: UserProfile; onClose: () => void; onSubmit: (data: Partial<Post>) => void; initialType: PostType }> = ({ userData, onClose, onSubmit, initialType }) => {
  const [content, setContent] = useState('');
  const [postType, setPostType] = useState<PostType>(initialType);
  const [category, setCategory] = useState(STUDY_CATEGORIES[0]);
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [videoUrl, setVideoUrl] = useState('');
  const [hashtags, setHashtags] = useState<string[]>([]);
  const [tagInput, setTagInput] = useState('');
  const [isSuggesting, setIsSuggesting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSuggestTags = async () => {
    if (!content.trim()) return;
    setIsSuggesting(true);
    try {
        const tags = await suggestHashtags(content);
        setHashtags(prev => Array.from(new Set([...prev, ...tags])));
    } finally {
        setIsSuggesting(false);
    }
  };

  const addTag = () => {
      const cleanTag = tagInput.trim().replace(/^#/, '').toLowerCase();
      if (cleanTag && !hashtags.includes(cleanTag)) {
          setHashtags(prev => [...prev, cleanTag]);
          setTagInput('');
      }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setImageUrl(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[100] flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-xl rounded-[3.5rem] shadow-2xl animate-slide-in overflow-hidden max-h-[90vh] overflow-y-auto">
        <div className={`p-8 border-b flex justify-between items-center sticky top-0 z-10 ${userData.isAdmin ? 'bg-amber-50 border-amber-100' : 'bg-indigo-50/50'}`}>
          <h3 className="text-2xl font-black tracking-tighter">{userData.isAdmin ? 'Lệnh Admin 🎖️' : 'Chia sẻ bài học 🧬'}</h3>
          <button onClick={onClose} className="p-3 bg-white rounded-full shadow-sm hover:rotate-90 transition-transform"><X size={24}/></button>
        </div>
        <div className="p-8 space-y-6">
          <div className="flex gap-2 p-1 bg-slate-100 rounded-full border overflow-x-auto no-scrollbar">
            {userData.isAdmin && (
              <button onClick={() => setPostType('event')} className={`flex-1 py-3.5 rounded-full text-[10px] font-black uppercase transition-all shrink-0 px-8 ${postType === 'event' ? 'bg-amber-500 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}>🎖️ Sự kiện</button>
            )}
            <button onClick={() => setPostType('knowledge')} className={`flex-1 py-3.5 rounded-full text-[10px] font-black uppercase transition-all shrink-0 px-8 ${postType === 'knowledge' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}>📚 Bài học</button>
            <button onClick={() => setPostType('meme')} className={`flex-1 py-3.5 rounded-full text-[10px] font-black uppercase transition-all shrink-0 px-8 ${postType === 'meme' ? 'bg-rose-500 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}>😂 Meme</button>
          </div>

          <div className="space-y-4">
              <select value={category} onChange={e => setCategory(e.target.value)} className="w-full bg-slate-50 border-2 border-slate-100 rounded-[1.5rem] px-5 py-4 text-sm font-black text-slate-700 outline-none focus:border-indigo-200 transition-colors">
                {STUDY_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
              </select>

              <textarea 
                value={content} 
                onChange={e => setContent(e.target.value)} 
                placeholder="Nội dung bài học hoặc mô tả xịn xò..." 
                className="w-full h-32 bg-transparent outline-none text-slate-700 font-bold placeholder:text-slate-200 resize-none text-xl" 
              />
          </div>

          {/* Hashtag Section */}
          <div className="space-y-4">
              <div className="flex gap-2 flex-wrap min-h-[30px]">
                  {hashtags.map(t => (
                      <span key={t} className="bg-slate-100 text-slate-600 px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 border border-slate-200">
                          #{t.toUpperCase()} <button onClick={() => setHashtags(h => h.filter(x => x !== t))} className="hover:text-rose-500"><X size={12}/></button>
                      </span>
                  ))}
              </div>
              <div className="flex gap-3">
                  <div className="relative flex-1">
                      <Hash size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                      <input 
                        value={tagInput} 
                        onChange={e => setTagInput(e.target.value)} 
                        onKeyDown={e => e.key === 'Enter' && (e.preventDefault(), addTag())} 
                        placeholder="Thêm hashtag..." 
                        className="w-full pl-10 pr-4 py-4 bg-slate-100 rounded-[1.5rem] text-xs font-bold border-none outline-none focus:bg-white focus:ring-4 focus:ring-indigo-50 transition-all" 
                      />
                  </div>
                  <button 
                    onClick={handleSuggestTags} 
                    disabled={isSuggesting || !content.trim()} 
                    title="Gợi ý bằng AI"
                    className="px-5 bg-indigo-50 text-indigo-600 rounded-[1.5rem] text-[10px] font-black hover:bg-indigo-600 hover:text-white transition-all disabled:opacity-50"
                  >
                      {isSuggesting ? <RefreshCw className="animate-spin" size={20}/> : <Sparkles size={20}/>}
                  </button>
              </div>
          </div>

          <div className="space-y-4 pt-4">
            <div className="flex gap-4">
              <button onClick={() => fileInputRef.current?.click()} className="flex-1 flex items-center justify-center gap-3 py-4 bg-slate-100 rounded-2xl text-xs font-black text-slate-500 hover:bg-indigo-50 hover:text-indigo-600 transition-all border border-transparent hover:border-indigo-100">
                  <ImageIcon size={20}/> {imageUrl ? "Đổi ảnh" : "Thêm ảnh"}
              </button>
              <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" />

              <div className="relative flex-[2]">
                  <Youtube size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-rose-500" />
                  <input value={videoUrl} onChange={e => setVideoUrl(e.target.value)} placeholder="Link YouTube..." className="w-full pl-10 pr-5 py-4 bg-slate-100 rounded-2xl text-xs font-bold border-none outline-none focus:bg-white focus:ring-4 focus:ring-rose-50 transition-all" />
              </div>
            </div>
          </div>

          {imageUrl && (
            <div className="relative rounded-[2rem] overflow-hidden border-2 border-slate-100 shadow-inner bg-slate-50">
              <img src={imageUrl} className="w-full h-40 object-cover" />
              <button onClick={() => setImageUrl(null)} className="absolute top-3 right-3 bg-rose-500 text-white p-2 rounded-full shadow-lg hover:scale-110 transition-transform"><X size={16}/></button>
            </div>
          )}

          <button 
            onClick={() => onSubmit({ content, category, type: postType, imageUrl: imageUrl || undefined, videoUrl: videoUrl || undefined, hashtags })} 
            disabled={!content.trim()} 
            className={`w-full py-6 text-white rounded-[2rem] font-black text-lg shadow-2xl transition-all active:scale-95 flex items-center justify-center gap-3 ${userData.isAdmin ? 'bg-amber-500 shadow-amber-100' : 'bg-indigo-600 shadow-indigo-100'}`}
          >
              {postType === 'event' ? <Crown size={24}/> : <Send size={24}/>}
              {postType === 'event' ? 'KHỞI TẠO SỰ KIỆN' : 'CHIA SẺ NGAY'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default Feed;

import React, { useState, useEffect } from 'react';
import { UserProfile } from '../types';
