  Sparkles, Ghost, Zap, X, ShieldCheck, Crown, ShieldAlert, Key,
  Lock, CheckCircle2, AlertCircle
} from 'lucide-react';
import { roastOrToast } from '../services/geminiService';

interface ProfileProps {
  userData: UserProfile;
  onUpdate: (u: UserProfile) => void;
  onToast: (m: string, t: 'success' | 'error') => void;
}

const Profile: React.FC<ProfileProps> = ({ userData, onUpdate, onToast }) => {
  const level = getLevelInfo(userData.exp);
  const [aiOpinion, setAiOpinion] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [showAdminModal, setShowAdminModal] = useState(false);
  const [adminCode, setAdminCode] = useState('');

  const handleAIJudge = async (mode: 'roast' | 'toast') => {
    setLoading(true);
    try {
      const res = await roastOrToast(userData, mode);
      setAiOpinion(res);
    } catch (e) {
      setAiOpinion("Lỗi rồi, AI đang bận chê người khác!");
    } finally {
      setLoading(false);
    }
  };

  const verifyAdmin = () => {
    // Mã Admin bí mật dành cho giám khảo/người quản lý demo
    if (adminCode === 'SG_ADMIN_2025' || adminCode === 'STUDYGRAM_WIN') {
      const updated = { ...userData, isAdmin: true };
      onUpdate(updated);
      setShowAdminModal(false);
      onToast("Kích hoạt quyền ADMIN thành công! 👑", "success");
      // @ts-ignore
      window.confetti({ 
        particleCount: 150, 
        spread: 100, 
        origin: { y: 0.6 },
        colors: ['#FFD700', '#FFA500', '#FFFFFF'] 
      });
    } else {
      onToast("Mã bí mật không chính xác!", "error");
    }
  };

  return (
    <div className="animate-slide-in pb-20 max-w-2xl mx-auto w-full">
      {/* Profile Header */}
      <div className="flex flex-col items-center text-center mt-6 mb-12">
        <div className="relative mb-8 group">
          <div className={`absolute -inset-4 rounded-[4rem] blur-2xl opacity-20 transition-opacity ${userData.isAdmin ? 'bg-amber-400 opacity-60' : 'bg-indigo-500'}`}></div>
          <img 
            src={userData.avatar} 
            className={`relative w-44 h-44 rounded-[3.5rem] bg-white border-4 shadow-2xl transition-all duration-500 ${userData.isAdmin ? 'border-amber-400 rotate-0' : 'border-white rotate-3'}`} 
          />
          <button 
            onClick={() => setShowAdminModal(true)}
            className={`absolute -bottom-4 -right-4 text-white p-4 rounded-[1.8rem] shadow-xl border-4 border-white transition-transform active:scale-90 ${userData.isAdmin ? 'bg-amber-500' : 'bg-indigo-600'}`}
          >
              {userData.isAdmin ? <Crown size={28}/> : <ShieldAlert size={28}/>}
          </button>
        </div>

        <div className="flex items-center gap-3 justify-center mb-4">
            <h2 className={`text-4xl font-black tracking-tighter ${userData.isAdmin ? 'text-amber-600' : 'text-slate-800'}`}>{userData.name}</h2>
            {userData.isAdmin && <ShieldCheck className="text-amber-500" size={32} fill="currentColor"/>}
        </div>

        <div className={`inline-flex items-center gap-3 px-10 py-4 bg-white rounded-full border shadow-xl font-black transition-all hover:scale-105 ${userData.isAdmin ? 'text-amber-600 border-amber-200 shadow-amber-50' : 'text-indigo-600 border-slate-100 shadow-indigo-50'}`}>
          <span className="text-3xl">{level.icon}</span> {level.title.toUpperCase()} • {userData.exp.toLocaleString()} EXP
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-2 gap-6 mb-12">
        <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-xl relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-20 transition-opacity rotate-12"><Flame size={100}/></div>
          <h4 className="text-[10px] font-black text-orange-500 uppercase tracking-widest mb-3">Lửa tri thức</h4>
          <div className="text-4xl font-black text-slate-800">{userData.streak} Ngày</div>
          <p className="text-[10px] text-slate-400 font-bold mt-2">Học tập không ngừng nghỉ</p>
        </div>
        <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-xl relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-20 transition-opacity -rotate-12"><Zap size={100}/></div>
          <h4 className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-3">Thắng Quiz</h4>
          <div className="text-4xl font-black text-slate-800">{userData.completedQuizzes} Lần</div>
          <p className="text-[10px] text-slate-400 font-bold mt-2">Đấu trường trí tuệ</p>
        </div>
      </div>

      {/* AI Judge Section */}
      <div className={`glass p-10 rounded-[3.5rem] border-white shadow-2xl mb-12 relative overflow-hidden text-white ${userData.isAdmin ? 'bg-gradient-to-br from-amber-500 to-orange-600' : 'bg-gradient-to-br from-indigo-600 to-purple-700'}`}>
        <div className="absolute top-0 right-0 p-8 opacity-10 rotate-45"><Ghost size={160}/></div>
        <h3 className="text-2xl font-black mb-8 flex items-center gap-3 tracking-tight"><Sparkles className="animate-pulse"/> Thẩm định AI Perfect</h3>

        {aiOpinion ? (
          <div className="p-8 bg-white/10 backdrop-blur-md rounded-[2.5rem] border border-white/20 animate-slide-in relative group/opinion">
            <p className="text-xl font-bold leading-relaxed italic tracking-tight">"{aiOpinion}"</p>
            <button 
              onClick={() => setAiOpinion(null)} 
              className="absolute -top-4 -right-4 bg-white text-indigo-600 p-3 rounded-full shadow-lg hover:rotate-90 transition-all opacity-0 group-hover/opinion:opacity-100"
