            <div className="w-16 h-16 bg-amber-500 text-white rounded-[1.5rem] mb-6 mx-auto flex items-center justify-center shadow-xl">
              <Key size={32} />
            </div>
            <h2 className="text-2xl font-black text-slate-800 mb-2">Nhập mã Admin</h2>
