import React, { useState, useEffect } from 'react';
import { UserProfile } from '../types';
import { getLevelInfo } from '../constants';
// Fix: Added missing Stars import from lucide-react
import { 
  Flame, BookOpen, BrainCircuit, Target, Settings, Share2, Award, 
  Sparkles, Ghost, Zap, X, ShieldCheck, Crown, ShieldAlert, Key,
  Lock, CheckCircle2, AlertCircle, TrendingUp, Briefcase, ChevronRight,
  ListChecks, RefreshCw, Stars
} from 'lucide-react';
import { roastOrToast, predictCareerPath } from '../services/geminiService';

interface ProfileProps {
  userData: UserProfile;
  onUpdate: (u: UserProfile) => void;
  onToast: (m: string, t: 'success' | 'error') => void;
}

const Profile: React.FC<ProfileProps> = ({ userData, onUpdate, onToast }) => {
  const level = getLevelInfo(userData.exp);
  const [aiOpinion, setAiOpinion] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [showAdminModal, setShowAdminModal] = useState(false);
  const [adminCode, setAdminCode] = useState('');
  const [careerResult, setCareerResult] = useState<any>(null);
  const [isPredicting, setIsPredicting] = useState(false);

  const handleAIJudge = async (mode: 'roast' | 'toast') => {
    setLoading(true);
    try {
      const res = await roastOrToast(userData, mode);
      setAiOpinion(res);
    } catch (e) {
      setAiOpinion("Lỗi rồi, AI đang bận chê người khác!");
    } finally {
      setLoading(false);
    }
  };

  const handlePredictCareer = async () => {
    setIsPredicting(true);
    try {
      const res = await predictCareerPath(userData);
      setCareerResult(res);
    } finally {
      setIsPredicting(false);
    }
  };

  const verifyAdmin = () => {
    if (adminCode === 'SG_ADMIN_2025' || adminCode === 'STUDYGRAM_WIN') {
      const updated = { ...userData, isAdmin: true };
      onUpdate(updated);
      setShowAdminModal(false);
      onToast("Kích hoạt quyền ADMIN thành công! 👑", "success");
      // @ts-ignore
      window.confetti({ 
        particleCount: 150, 
        spread: 100, 
        origin: { y: 0.6 },
        colors: ['#FFD700', '#FFA500', '#FFFFFF'] 
      });
    } else {
      onToast("Mã bí mật không chính xác!", "error");
    }
  };

  const updateGoal = () => {
    const goal = prompt("Mục tiêu lớn nhất của fen là gì?", userData.studyGoal || "");
    if (goal !== null) {
      onUpdate({ ...userData, studyGoal: goal });
    }
  };

  return (
    <div className="animate-slide-in pb-24 max-w-2xl mx-auto w-full">
      {/* Profile Header */}
      <div className="flex flex-col items-center text-center mt-6 mb-12">
        <div className="relative mb-8 group">
          <div className={`absolute -inset-4 rounded-[4rem] blur-2xl opacity-20 transition-opacity ${userData.isAdmin ? 'bg-amber-400 opacity-60' : 'bg-indigo-500'}`}></div>
          <img 
            src={userData.avatar} 
            className={`relative w-44 h-44 rounded-[3.5rem] bg-white border-4 shadow-2xl transition-all duration-500 ${userData.isAdmin ? 'border-amber-400 rotate-0' : 'border-white rotate-3'}`} 
          />
          <button 
            onClick={() => setShowAdminModal(true)}
            className={`absolute -bottom-4 -right-4 text-white p-4 rounded-[1.8rem] shadow-xl border-4 border-white transition-transform active:scale-90 ${userData.isAdmin ? 'bg-amber-500' : 'bg-indigo-600'}`}
          >
              {userData.isAdmin ? <Crown size={28}/> : <ShieldAlert size={28}/>}
          </button>
        </div>

        <div className="flex items-center gap-3 justify-center mb-4">
            <h2 className={`text-4xl font-black tracking-tighter ${userData.isAdmin ? 'text-amber-600' : 'text-slate-800'}`}>{userData.name}</h2>
            {userData.isVerified && <CheckCircle2 className="text-indigo-500" size={32} fill="currentColor"/>}
        </div>

        <div className={`inline-flex items-center gap-3 px-10 py-4 bg-white rounded-full border shadow-xl font-black transition-all hover:scale-105 ${userData.isAdmin ? 'text-amber-600 border-amber-200 shadow-amber-50' : 'text-indigo-600 border-slate-100 shadow-indigo-50'}`}>
          <span className="text-3xl">{level.icon}</span> {level.title.toUpperCase()} • {userData.exp.toLocaleString()} EXP
        </div>
      </div>

      {/* Goal Tracking Section */}
      <div className="glass p-8 rounded-[3rem] border-white shadow-xl mb-10 bg-white/60">
        <div className="flex justify-between items-center mb-6">
            <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-indigo-100 text-indigo-600 rounded-xl flex items-center justify-center"><Target size={24}/></div>
                <h3 className="font-black text-slate-800 text-base">Mục tiêu StudyGram</h3>
