    <div className={`glass rounded-[3rem] p-8 border-white shadow-xl animate-slide-in relative overflow-hidden group ${isEvent ? 'gold-shimmer-bg border-amber-200' : 'bg-white/95'}`}>
      {post.isPinned && (
        <div className="absolute top-6 right-8 text-amber-500 animate-bounce flex items-center gap-1 font-black text-[10px] uppercase tracking-widest">
          <Pin size={16} fill="currentColor"/> Ghim
        </div>
      )}

      <div className="flex gap-4 mb-6">
        <img 
          src={post.avatar} 
          className={`w-14 h-14 rounded-2xl border-2 bg-white shadow-sm transition-transform group-hover:rotate-3 ${isEvent ? 'border-amber-400' : 'border-slate-50'}`} 
        />
        <div>
          <h4 className={`font-black text-base flex items-center gap-2 ${isEvent ? 'text-amber-700' : 'text-slate-800'}`}>
            {post.userName} 
            {isEvent && <Crown size={16} className="text-amber-500" fill="currentColor"/>}
          </h4>
          <span className={`text-[9px] px-2.5 py-1 rounded-full font-black uppercase tracking-widest ${isEvent ? 'bg-amber-500 text-white' : 'bg-slate-100 text-slate-400'}`}>#{post.category}</span>
        </div>
      </div>

      <div className={`text-lg leading-relaxed mb-6 font-semibold whitespace-pre-wrap ${isEvent ? 'text-amber-900' : 'text-slate-700'}`}>{post.content}</div>

      {post.hashtags && post.hashtags.length > 0 && (
        <div className="flex flex-wrap gap-2 mb-6">
          {post.hashtags.map(tag => (
            <button 
              key={tag} 
              onClick={() => onTagClick(tag)} 
              className={`text-[10px] font-black px-3 py-1.5 rounded-xl transition-all hover:bg-indigo-600 hover:text-white ${isEvent ? 'bg-amber-100 text-amber-600' : 'bg-indigo-50 text-indigo-500'}`}
            >
              #{tag.toUpperCase()}
            </button>
          ))}
        </div>
      )}

      {post.imageUrl && (
        <div className="mb-6 rounded-[2rem] overflow-hidden border-4 border-white shadow-lg bg-slate-100">
          <img src={post.imageUrl} className="w-full h-auto max-h-[500px] object-cover" alt="Post content" />
