          {vibe.loading ? (
             <div className="flex items-center gap-3 font-black text-xs text-slate-400 justify-center py-2"><RefreshCw className="animate-spin" size={20}/> Phân tích vibe...</div>
          ) : (
            <div className="space-y-2">
              <div className="flex justify-between items-center mb-1">
                <span className="text-[9px] font-black uppercase tracking-[0.2em] opacity-80">AI Insight</span>
                <span className="text-xl font-black italic gold-text">Score: {vibe.score}/100</span>
              </div>
              <p className="text-xs font-bold opacity-90 leading-relaxed italic">"{vibe.comment}"</p>
            </div>
          )}
        </div>
      )}

      <div className="flex items-center gap-6 pt-5 border-t border-slate-100/50">
        <button onClick={() => setIsLiked(!isLiked)} className={`flex items-center gap-2 text-xs font-black transition-all ${isLiked ? 'text-rose-500 scale-110' : 'text-slate-400 hover:text-rose-400'}`}>
          <Heart size={24} fill={isLiked ? 'currentColor' : 'none'} /> {post.likes.length + (isLiked ? 1 : 0)}
        </button>
        <button onClick={() => setShowComments(!showComments)} className={`flex items-center gap-2 text-xs font-black text-slate-400 hover:text-indigo-600 transition-all ${showComments ? 'text-indigo-600' : ''}`}>
           <MessageSquare size={24} /> {post.comments?.length || 0}
        </button>
        <button onClick={onVibeCheck} disabled={!!vibe} className={`ml-auto flex items-center gap-2 px-6 py-3 rounded-2xl text-[10px] font-black uppercase transition-all shadow-lg ${vibe ? 'bg-slate-100 text-slate-300 shadow-none' : 'bg-indigo-600 text-white shadow-indigo-200 hover:-translate-y-1'}`}>
