// Reuse existing CreatePostModal (keeping it to ensure no regression)
const CreatePostModal: React.FC<{ userData: UserProfile; onClose: () => void; onSubmit: (data: Partial<Post>) => void; initialType: PostType }> = ({ userData, onClose, onSubmit, initialType }) => {
  const [content, setContent] = useState('');
  const [postType, setPostType] = useState<PostType>(initialType);
  const [category, setCategory] = useState(STUDY_CATEGORIES[0]);
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [hashtags, setHashtags] = useState<string[]>([]);
  const [tagInput, setTagInput] = useState('');
  const [isSuggesting, setIsSuggesting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSuggestTags = async () => {
    if (!content.trim()) return;
    setIsSuggesting(true);
    try {
        const tags = await suggestHashtags(content);
        setHashtags(prev => Array.from(new Set([...prev, ...tags])));
    } finally {
        setIsSuggesting(false);
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setImageUrl(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[100] flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-xl rounded-[3.5rem] shadow-2xl animate-slide-in overflow-hidden max-h-[90vh] overflow-y-auto">
        <div className={`p-8 border-b flex justify-between items-center sticky top-0 z-10 ${userData.isAdmin ? 'bg-amber-50 border-amber-100' : 'bg-indigo-50/50'}`}>
          <h3 className="text-2xl font-black tracking-tighter">Chia sẻ bài học 🧬</h3>
          <button onClick={onClose} className="p-3 bg-white rounded-full shadow-sm hover:rotate-90 transition-transform"><X size={24}/></button>
        </div>
        <div className="p-8 space-y-6">
          <textarea 
            value={content} 
            onChange={e => setContent(e.target.value)} 
            placeholder="Nội dung bài học hoặc mô tả..." 
            className="w-full h-32 bg-transparent outline-none text-slate-700 font-bold placeholder:text-slate-200 resize-none text-xl" 
          />

          <div className="flex gap-2 flex-wrap">
              {hashtags.map(t => (
                  <span key={t} className="bg-slate-100 text-slate-600 px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 border border-slate-200">
                      #{t.toUpperCase()} <button onClick={() => setHashtags(h => h.filter(x => x !== t))}><X size={12}/></button>
                  </span>
              ))}
          </div>

          <div className="flex gap-2">
            <input 
              value={tagInput} 
              onChange={e => setTagInput(e.target.value)} 
              onKeyDown={e => e.key === 'Enter' && (setHashtags([...hashtags, tagInput.trim()]), setTagInput(''))}
              placeholder="Thêm hashtag..." 
              className="flex-1 px-4 py-3 bg-slate-100 rounded-xl text-xs font-bold outline-none" 
            />
            <button onClick={handleSuggestTags} className="p-3 bg-indigo-50 text-indigo-600 rounded-xl">
               {isSuggesting ? <RefreshCw className="animate-spin" size={20}/> : <Sparkles size={20}/>}
            </button>
          </div>

          <button onClick={() => fileInputRef.current?.click()} className="w-full py-4 border-2 border-dashed border-slate-200 rounded-2xl flex items-center justify-center gap-2 text-slate-400 font-bold text-xs hover:border-indigo-400 hover:text-indigo-400 transition-all">
             <ImageIcon size={20}/> {imageUrl ? "Đã chọn ảnh" : "Tải ảnh lên"}
          </button>
          <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" />

          {imageUrl && <img src={imageUrl} className="w-full h-32 object-cover rounded-2xl" />}

          <button 
            onClick={() => onSubmit({ content, category, type: postType, imageUrl: imageUrl || undefined, hashtags })} 
            disabled={!content.trim()} 
            className="w-full py-6 bg-indigo-600 text-white rounded-[2rem] font-black text-lg shadow-2xl transition-all active:scale-95"
          >
              CHIA SẺ NGAY
          </button>
        </div>
      </div>
    </div>
  );
};

