        </div>
        <div>
          <h4 className="font-black text-lg text-slate-800 flex items-center gap-2 tracking-tight">
            {post.userName}
            {post.type === 'event' && <ShieldCheck size={18} className="text-amber-500" fill="currentColor"/>}
          </h4>
          <div className="flex items-center gap-2 mt-1">
             <span className="text-[10px] px-3 py-1 rounded-full font-black uppercase tracking-widest bg-indigo-50 text-indigo-500 border border-indigo-100">#{post.category}</span>
             <span className="text-[10px] font-bold text-slate-300">{(new Date(post.createdAt)).toLocaleDateString()}</span>
          </div>
        </div>
      </div>

      {/* Post Content */}
      <div className="text-xl leading-relaxed mb-8 font-bold text-slate-700 whitespace-pre-wrap tracking-tight">{post.content}</div>

      {post.imageUrl && (
