const FLASH_MODEL = 'gemini-3-flash-preview';
const PRO_MODEL = 'gemini-3-pro-preview';
const IMAGE_MODEL = 'gemini-2.5-flash-image'; // Dùng bản Flash cho hình ảnh để không cần Personal Key phức tạp

