/**
 * Dự đoán nghề nghiệp tương lai dựa trên sở thích và thành tích
 */
export const predictCareerPath = async (userData: any): Promise<{career: string, reasoning: string, matchScore: number}> => {
  const ai = getAIInstance();
  const prompt = `Dựa trên profile học giả: Tên ${userData.name}, Level ${userData.exp} EXP, Đã giải ${userData.completedQuizzes} Quiz. 
  Hãy dự đoán một nghề nghiệp tương lai sáng lạn và hài hước cho bạn này.`;

  const response = await ai.models.generateContent({
    model: FLASH_MODEL,
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          career: { type: Type.STRING },
          reasoning: { type: Type.STRING },
          matchScore: { type: Type.NUMBER }
        },
        required: ["career", "reasoning", "matchScore"]
      }
    }
  });
  return JSON.parse(response.text || "{}");
};

/**
 * Gợi ý Hashtag dựa trên nội dung bài viết bằng AI
 */
export const suggestHashtags = async (content: string): Promise<string[]> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: `Suggest 3-5 trending and relevant Vietnamese hashtags for this study social media post: "${content}". Return only a JSON array of strings, NO '#' prefix, NO explanation.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (e) {
    console.error("Hashtag Suggest Error:", e);
    return ["study", "tri_thuc", "genz"];
  }
};

export const callGeminiWithRetry = async (
  prompt: string, 
  systemInstruction?: string, 
  usePro = false,
  retries = 2
): Promise<string> => {
  const ai = getAIInstance();
  const config = {
    systemInstruction: systemInstruction || "Bạn là trợ lý học tập Gen Z, hài hước, dùng từ lóng, trả lời ngắn gọn.",
    temperature: 0.9,
    thinkingConfig: usePro ? { thinkingBudget: 2000 } : undefined 
  };

  for (let i = 0; i < retries; i++) {
    try {
      const response = await ai.models.generateContent({
        model: usePro ? PRO_MODEL : FLASH_MODEL,
        contents: prompt,
        config: config,
      });
      return response.text || "Lỗi rồi fen!";
    } catch (error) {
      if (i === retries - 1) throw error;
      await new Promise(resolve => setTimeout(resolve, 500));
    }
  }
  return "AI đang đi uống trà sữa, tí quay lại!";
};

export const generateMemeImage = async (prompt: string): Promise<string> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: {
        parts: [{ text: `A funny high-quality 2D digital art study meme about: ${prompt}. Cinematic lighting, vibrant colors, Gen Z style.` }],
      },
      config: {
        imageConfig: { aspectRatio: "1:1" }
      },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No image generated");
  } catch (error) {
    console.error("Meme Gen Error:", error);
    return "";
  }
};

