export const downloadAsFile = (content: string, filename: string) => {
  const blob = new Blob([content], { type: 'text/plain' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename; a.click();
  URL.revokeObjectURL(url);
};

import React, { useState, useEffect } from 'react';
import { 
  Plus, Heart, Sparkles, MessageSquare, X, Send, 
  Pin, Crown, ShieldCheck, Search, RefreshCw, Star, Users, Flame, Info
} from 'lucide-react';
import { Post, UserProfile, PostType, Comment } from '../types';
import { checkVibePost, suggestHashtags } from '../services/geminiService';

const Feed: React.FC<{ userData: UserProfile; onExp: (n: number) => void }> = ({ userData, onExp }) => {
  const [posts, setPosts] = useState<Post[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<PostType | 'all'>('all');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('studygram_posts');
    if (saved) setPosts(JSON.parse(saved));
    else {
      const initial = [{
        id: 'p1', uid: 'admin', userName: 'Hệ thống 🛡️', avatar: 'https://api.dicebear.com/7.x/notionists/svg?seed=Admin',
        content: 'Chào mừng các học giả tới phiên bản StudyGram V4 Pro! Hãy chia sẻ kiến thức để nhận EXP nhé. 🔥', category: 'Thông báo', type: 'event' as PostType, mood: '🔥', createdAt: Date.now(), likes: [], comments: [], isPinned: true, aiAnalysis: 'Vibe cực cháy cho khởi đầu mới!'
      }];
      setPosts(initial);
      localStorage.setItem('studygram_posts', JSON.stringify(initial));
    }
  }, []);

  const handleAddPost = async (data: Partial<Post>) => {
    setIsAnalyzing(true);
    try {
      const hashtags = await suggestHashtags(data.content!);
      const vibeData = await checkVibePost(data.content!);

      const newPost: Post = {
        id: Date.now().toString(), uid: userData.uid, userName: userData.name, avatar: userData.avatar,
        content: data.content!, category: data.category!, type: data.type || 'knowledge', mood: data.mood || '📚',
        createdAt: Date.now(), likes: [], comments: [], hashtags, aiAnalysis: vibeData.comment
      };

      const updated = [newPost, ...posts];
      setPosts(updated);
      localStorage.setItem('studygram_posts', JSON.stringify(updated));
      onExp(25);
      setIsModalOpen(false);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleLike = (id: string) => {
    const updated = posts.map(p => p.id === id ? { ...p, likes: p.likes.includes(userData.uid) ? p.likes.filter(u => u !== userData.uid) : [...p.likes, userData.uid] } : p);
    setPosts(updated); localStorage.setItem('studygram_posts', JSON.stringify(updated));
  };

  const handleComment = (id: string, text: string) => {
    if (!text.trim()) return;
    const updated = posts.map(p => p.id === id ? { ...p, comments: [...p.comments, { id: Date.now().toString(), userName: userData.name, avatar: userData.avatar, content: text, createdAt: Date.now(), isAuthor: true }] } : p);
    setPosts(updated); localStorage.setItem('studygram_posts', JSON.stringify(updated));
    onExp(5);
  };

  return (
    <div className="space-y-8 max-w-2xl mx-auto pb-24">
      {/* Create Post Trigger */}
      <div className="glass p-6 rounded-[2.8rem] shadow-xl flex items-center gap-5 cursor-pointer hover:shadow-2xl transition-all border-white bg-white/50 group" onClick={() => setIsModalOpen(true)}>
        <div className="relative">
          <img src={userData.avatar} className="w-14 h-14 rounded-2xl border-2 shadow-sm group-hover:rotate-3 transition-transform" />
          <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 border-2 border-white rounded-full"></div>
        </div>
        <div className="flex-1 text-slate-400 font-bold text-lg">Lan tỏa tri thức hôm nay đi fen...</div>
        <div className="w-12 h-12 bg-indigo-600 text-white rounded-2xl flex items-center justify-center shadow-lg group-hover:scale-110 transition-transform"><Plus size={24}/></div>
      </div>

      {/* Tabs */}
      <div className="flex gap-2 p-1.5 bg-slate-200/40 rounded-full w-fit mx-auto border border-white backdrop-blur-md">
        {['all', 'knowledge', 'meme', 'event'].map(t => (
          <button key={t} onClick={() => setActiveTab(t as any)} className={`px-8 py-2.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === t ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-800'}`}>
            {t === 'all' ? 'Tất cả' : t}
          </button>
        ))}
      </div>

      {/* Post List */}
      <div className="space-y-10">
        {posts.filter(p => activeTab === 'all' || p.type === activeTab).map(post => (
          <PostCard key={post.id} post={post} userData={userData} onLike={() => handleLike(post.id)} onComment={(t) => handleComment(post.id, t)} />
        ))}
      </div>

      {isModalOpen && (
        <CreatePostModal 
          onClose={() => setIsModalOpen(false)} 
          onSubmit={handleAddPost} 
          userData={userData} 
          isAnalyzing={isAnalyzing}
        />
      )}
    </div>
  );
};

