  const [students, setStudents] = useState<any[]>([]);

  useEffect(() => {
    // Lấy dữ liệu thực từ localStorage (nếu có người dùng khác đã từng đăng nhập trên máy này)
    // Trong môi trường demo, chúng ta sẽ ưu tiên hiển thị user hiện tại và các user thực tế
    const savedPosts = localStorage.getItem('studygram_posts');
    const posts = savedPosts ? JSON.parse(savedPosts) : [];

    // Thu thập danh sách user thực từ các bài post
    const uniqueUsersMap = new Map();
    // Luôn thêm user hiện tại
    uniqueUsersMap.set(userData.uid, {
      uid: userData.uid,
      name: userData.name,
      avatar: userData.avatar,
      exp: userData.exp,
      streak: userData.streak,
      isVerified: userData.isVerified,
      isStudentOfWeek: userData.exp > 500 // Demo logic: ai trên 500 EXP là Student of week
