                    {student.name} {student.uid === currentUid && '(Bạn)'}
                </h4>
                <div className="flex items-center gap-4 mt-1">
                    <div className="flex items-center gap-1.5 text-[10px] font-black text-slate-400 uppercase tracking-widest bg-slate-100/80 px-3 py-1 rounded-full">
                       <Flame size={12} className="text-orange-500" /> {student.streak} Ngày
                    </div>
                    {student.exp > 1000 && (
