            </div>
          )}
        </div>
      </div>

      {/* Action Buttons */}
      <div className="grid grid-cols-2 gap-4">
        <button className="py-6 glass border-white text-indigo-600 font-black text-xs uppercase tracking-[0.2em] rounded-[2.5rem] shadow-xl flex items-center justify-center gap-4 hover:bg-white transition-all active:scale-95 group">
            <Share2 size={20} className="group-hover:rotate-12 transition-transform"/> CHIA SẺ
        </button>
        <button className="py-6 bg-indigo-600 text-white font-black text-xs uppercase tracking-[0.2em] rounded-[2.5rem] shadow-2xl shadow-indigo-200 flex items-center justify-center gap-4 hover:bg-indigo-700 transition-all active:scale-95">
