               <div className="w-2 h-2 bg-indigo-400 rounded-full animate-pulse [animation-delay:0.2s]"></div>
               <div className="w-2 h-2 bg-indigo-200 rounded-full animate-pulse [animation-delay:0.4s]"></div>
