import { GoogleGenAI, Type } from "@google/genai";

const FLASH_MODEL = 'gemini-3-flash-preview';
const IMAGE_MODEL = 'gemini-2.5-flash-image'; 

const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const suggestHashtags = async (content: string): Promise<string[]> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: `Suggest 3-5 trending and relevant Vietnamese hashtags for this study post: "${content}". Return JSON array only.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (e) {
    return ["study", "tri_thuc", "genz"];
  }
};

export const callGeminiWithRetry = async (prompt: string, systemInstruction?: string): Promise<string> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: prompt,
      config: {
        systemInstruction: systemInstruction || "Bạn là trợ lý học tập Gen Z mặn mòi, sử dụng icon và từ lóng hiện đại.",
        temperature: 0.9,
      },
    });
    return response.text || "AI đang nạp năng lượng, thử lại sau nhé!";
  } catch (error) {
    console.error(error);
    return "Hệ thống đang bận học bài...";
  }
};

export const generateMindMap = async (topic: string): Promise<any> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: `Create a logical mind map for the topic: "${topic}" in Vietnamese. Return JSON object with 'root' and 'children' (array of objects with 'label' and 'subChildren').`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            root: { type: Type.STRING },
            children: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  label: { type: Type.STRING },
                  subChildren: { type: Type.ARRAY, items: { type: Type.STRING } }
                }
              }
            }
          }
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (e) {
    return { root: topic, children: [{ label: "Đang tải dữ liệu...", subChildren: [] }] };
  }
};

export const generateMemeImage = async (prompt: string): Promise<string> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: { parts: [{ text: `A vibrant, high-quality 2D digital art study meme about: ${prompt}. Cinematic lighting, cute characters.` }] },
      config: { imageConfig: { aspectRatio: "1:1" } },
    });
    if (!response.candidates?.[0]?.content?.parts) return "";
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
    }
    throw new Error();
  } catch (error) {
    return "";
  }
};

export const checkVibePost = async (content: string, imageUrl?: string): Promise<{vibe: string, score: number, comment: string}> => {
  const ai = getAIInstance();
  const parts: any[] = [{ text: `Hãy phân tích vibe của bài đăng này. Chấm điểm độ truyền cảm hứng từ 0-100 và nhận xét một câu cực mặn. Nội dung: "${content}"` }];
  if (imageUrl) parts.push({ inlineData: { data: imageUrl.split(',')[1], mimeType: 'image/jpeg' } });

  const response = await ai.models.generateContent({
    model: FLASH_MODEL,
    contents: { parts },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          vibe: { type: Type.STRING },
          score: { type: Type.NUMBER },
          comment: { type: Type.STRING }
        },
        required: ["vibe", "score", "comment"]
      }
    }
  });
  return JSON.parse(response.text || '{"vibe": "Chill", "score": 80, "comment": "Khá ổn áp!"}');
};

export const getChampionTip = async (name: string): Promise<string> => {
