export const getDebateResponse = async (history: any[], topic: string) => {
  const ai = getAIInstance();
  const res = await ai.models.generateContent({
    model: FLASH_MODEL,
    contents: history.map(h => ({ role: h.role === 'ai' ? 'model' : 'user', parts: [{ text: h.text }] })),
    config: { 
      systemInstruction: `Bạn là trọng tài tranh biện AI. Chủ đề: ${topic}. Hãy phân tích luận điểm người dùng, chỉ ra lỗ hổng logic và phản biện lại. Trả lời sắc sảo.` 
    }
  });
  return res.text || "";
};

export const downloadAsFile = (content: string, filename: string) => {
  const blob = new Blob([content], { type: 'text/plain' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename; a.click();
  URL.revokeObjectURL(url);
};

import React, { useState } from 'react';
import { 
  Wand2, BookOpen, ListChecks, CalendarDays, 
  ChevronRight, ArrowLeft, Loader2, Sparkles, 
  Copy, Check, LayoutGrid, RotateCw, Download, FileText,
  Smile, Image as ImageIcon, Network, ChevronDown
} from 'lucide-react';
import { summarizeText, generateFlashcards, downloadAsFile, generateMemeImage, generateMindMap } from '../services/geminiService';

const StudyTools: React.FC<{ onExp: (amount: number) => void }> = ({ onExp }) => {
  const [activeTool, setActiveTool] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [result, setResult] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  const tools = [
    { 
      id: 'mindmap', 
      name: 'Sơ đồ tư duy AI', 
      desc: 'Phân tích chủ đề thành cấu trúc sơ đồ tư duy logic.', 
      icon: Network, 
      color: 'bg-emerald-500',
      placeholder: 'Nhập chủ đề cần sơ đồ hóa (VD: Chiến tranh thế giới thứ 2)...'
    },
    { 
      id: 'summary', 
      name: 'Tóm tắt thông minh', 
      desc: 'Cô đọng văn bản dài thành các ý chính cực nhanh.', 
      icon: ListChecks, 
      color: 'bg-blue-500',
      placeholder: 'Dán đoạn văn bản cần tóm tắt vào đây...'
    },
    { 
      id: 'flashcards', 
      name: 'Flashcard AI', 
      desc: 'Tự động tạo thẻ ghi nhớ từ một chủ đề học tập.', 
      icon: LayoutGrid, 
      color: 'bg-purple-500',
      placeholder: 'Nhập chủ đề (VD: Các thì trong tiếng Anh)...'
    },
    { 
      id: 'meme', 
      name: 'AI Meme Studio', 
      desc: 'Tạo ảnh meme học tập cực mặn bằng trí tuệ nhân tạo.', 
      icon: Smile, 
      color: 'bg-amber-500',
      placeholder: 'Mô tả nội dung meme (VD: Học sinh khi biết tin nghỉ học)...'
    }
  ];

  const handleRunTool = async () => {
    if (!input.trim()) return;
    setLoading(true);
    setResult(null);

    try {
      if (activeTool === 'summary') {
        const res = await summarizeText(input);
        setResult(res);
      } else if (activeTool === 'flashcards') {
        const res = await generateFlashcards(input);
        setResult(res);
      } else if (activeTool === 'meme') {
        const res = await generateMemeImage(input);
        setResult(res);
      } else if (activeTool === 'mindmap') {
        const res = await generateMindMap(input);
        setResult(res);
      }
      onExp(15);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const handleExport = () => {
    if (!result) return;
    if (activeTool === 'meme') {
        const link = document.createElement('a');
        link.href = result;
        link.download = `StudyGram_Meme_${Date.now()}.png`;
        link.click();
        return;
    }
    let exportText = "";
    if (activeTool === 'flashcards' && Array.isArray(result)) {
      exportText = result.map((c, i) => `Q${i+1}: ${c.front}\nA${i+1}: ${c.back}`).join('\n\n');
    } else if (activeTool === 'mindmap') {
      exportText = `ROOT: ${result.root}\n` + result.children.map((c:any) => `- ${c.label}\n  + ${c.subChildren.join('\n  + ')}`).join('\n');
    } else {
      exportText = String(result);
    }
    const toolName = tools.find(t => t.id === activeTool)?.name || "Document";
    downloadAsFile(exportText, `StudyGram_${toolName.replace(/\s+/g, '_')}.txt`);
  };

  if (activeTool) {
    const tool = tools.find(t => t.id === activeTool);
    return (
      <div className="animate-slide-in pb-10 max-w-2xl mx-auto w-full">
        <button 
          onClick={() => { setActiveTool(null); setResult(null); setInput(''); }}
          className="flex items-center gap-2 text-slate-400 hover:text-indigo-600 mb-6 font-black text-[10px] uppercase tracking-widest transition-colors"
        >
          <ArrowLeft size={16} /> Quay lại kho tiện ích
        </button>

        <div className="glass rounded-[2.5rem] border-white shadow-xl overflow-hidden mb-6">
          <div className="p-8 bg-slate-50/50 border-b border-slate-100 flex items-center gap-4">
            <div className={`w-12 h-12 ${tool?.color} text-white rounded-2xl flex items-center justify-center shadow-lg`}>
              {tool && <tool.icon size={24} />}
            </div>
            <div>
              <h3 className="font-black text-slate-800 text-lg">{tool?.name}</h3>
              <p className="text-xs text-slate-400 font-bold uppercase tracking-wider">{tool?.desc}</p>
            </div>
          </div>

          <div className="p-8 space-y-6">
            <textarea 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder={tool?.placeholder}
              className="w-full h-40 bg-slate-100/50 border-none rounded-3xl p-5 text-sm font-semibold text-slate-700 outline-none focus:bg-white focus:ring-2 focus:ring-indigo-100 transition-all resize-none shadow-inner"
            />

            <button 
              onClick={handleRunTool}
              disabled={loading || !input.trim()}
              className={`w-full py-5 text-white rounded-3xl font-black shadow-xl flex items-center justify-center gap-3 disabled:opacity-50 active:scale-95 transition-all ${tool?.color}`}
            >
              {loading ? <Loader2 className="animate-spin" /> : <Sparkles size={20} />}
              {loading ? 'AI đang xử lý...' : 'Bắt đầu ngay'}
            </button>
          </div>
        </div>

        {result && (
          <div className="glass rounded-[2.5rem] border-white shadow-xl p-8 animate-slide-in">
            <div className="flex justify-between items-center mb-6">
              <h4 className="font-black text-indigo-600 text-[10px] uppercase tracking-[0.2em] flex items-center gap-2">
                <Wand2 size={14} /> KẾT QUẢ AI SUPREME
              </h4>
              <button 
                onClick={handleExport}
                className="p-3 bg-indigo-50 text-indigo-600 rounded-2xl hover:bg-indigo-600 hover:text-white transition-all shadow-sm"
              >
                <Download size={20} />
              </button>
            </div>

            <div className="prose prose-slate max-w-none">
              {activeTool === 'mindmap' ? (
                <div className="space-y-6">
                   <div className="p-6 bg-indigo-600 text-white rounded-3xl text-center font-black text-lg shadow-xl animate-float">
                      {result.root}
                   </div>
                   <div className="grid gap-4">
                      {result.children.map((child: any, i: number) => (
                        <div key={i} className="p-5 bg-white border-2 border-slate-50 rounded-[2rem] shadow-sm hover:border-indigo-100 transition-all group">
                           <div className="font-black text-indigo-600 mb-3 flex items-center gap-2">
                              <div className="w-2 h-2 bg-indigo-600 rounded-full"></div>
                              {child.label}
                           </div>
                           <div className="flex flex-wrap gap-2">
                              {child.subChildren.map((sub: string, j: number) => (
                                <span key={j} className="bg-slate-50 px-4 py-2 rounded-xl text-xs font-bold text-slate-500 border border-slate-100">{sub}</span>
                              ))}
                           </div>
                        </div>
                      ))}
                   </div>
                </div>
              ) : activeTool === 'meme' ? (
                <div className="rounded-[2rem] overflow-hidden border-4 border-white shadow-xl">
                  <img src={result} className="w-full h-auto" alt="AI Generated Meme" />
                </div>
              ) : activeTool === 'flashcards' && Array.isArray(result) ? (
                <div className="grid gap-4">
                  {result.map((card, i) => (
                    <div key={i} className="p-5 bg-slate-50 border border-slate-100 rounded-3xl group hover:bg-white hover:shadow-md transition-all">
                      <div className="text-[9px] font-black text-indigo-500 uppercase mb-2">Card #{i+1}</div>
                      <div className="font-bold text-slate-800 mb-2">Q: {card.front}</div>
                      <div className="text-slate-500 text-sm border-t border-slate-100 pt-2 mt-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        A: {card.back}
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-slate-700 whitespace-pre-wrap font-medium leading-relaxed bg-slate-50 p-6 rounded-3xl border border-slate-100 italic">
                  {result}
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
