  Coffee, FlameKindling, Volume2, VolumeX, SkipForward
} from 'lucide-react';
import { searchYoutubeVideos } from '../services/geminiService';

const PET_STAGES = [
  { icon: '🥚', label: 'Mầm Non Tri Thức', color: 'from-slate-200 to-slate-400' },
  { icon: '🐣', label: 'Tân Binh Học Hỏi', color: 'from-yellow-200 to-orange-300' },
  { icon: '🐥', label: 'Chiến Thần Tập Trung', color: 'from-orange-300 to-rose-400' },
  { icon: '🦅', label: 'Học Giả Đại Bàng', color: 'from-blue-400 to-indigo-600' },
  { icon: '🐲', label: 'Rồng Thần StudyGram', color: 'from-indigo-600 via-purple-600 to-amber-500' }
];

const AMBIENT_SOUNDS = [
  { id: 'rain', name: 'Tiếng mưa', icon: CloudRain, url: 'https://www.soundjay.com/nature/rain-01.mp3' },
  { id: 'wind', name: 'Tiếng gió', icon: Wind, url: 'https://www.soundjay.com/nature/wind-01.mp3' },
  { id: 'cafe', name: 'Quán Cafe', icon: Coffee, url: 'https://www.soundjay.com/misc/restaurant-ambience-1.mp3' },
  { id: 'fire', name: 'Lửa trại', icon: FlameKindling, url: 'https://www.soundjay.com/nature/fire-1.mp3' }
];

const FocusZone: React.FC<{ onExp: (amount: number); showToast: (m: string) => void }> = ({ onExp, showToast }) => {
  const [seconds, setSeconds] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);
  const [mode, setMode] = useState<'study' | 'break'>('study');
  const [petStage, setPetStage] = useState(0);
  const [showMusic, setShowMusic] = useState(false);
  const [activeAmbient, setActiveAmbient] = useState<string | null>(null);
  const [volume, setVolume] = useState(0.5);
  const [activeVideo, setActiveVideo] = useState<any>(null);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    let interval: any = null;
    if (isActive && seconds > 0) {
      interval = setInterval(() => setSeconds(s => s - 1), 1000);
      const elapsed = (25 * 60) - seconds;
      const stage = Math.min(Math.floor(elapsed / 300), 4);
      if (mode === 'study') setPetStage(stage);
    } else if (seconds === 0) {
      setIsActive(false);
      onExp(mode === 'study' ? 100 : 20);
      showToast(mode === 'study' ? "Tuyệt đỉnh! Pet đã hóa Rồng Thần! +100 EXP" : "Pin đã đầy, học tiếp thôi!");
      setMode(mode === 'study' ? 'break' : 'study');
      setSeconds(mode === 'study' ? 5 * 60 : 25 * 60);
      // @ts-ignore
      window.confetti({ particleCount: 200, spread: 90, origin: { y: 0.5 } });
    }
    return () => clearInterval(interval);
  }, [isActive, seconds]);

  const toggleAmbient = (sound: any) => {
    if (activeAmbient === sound.id) {
      audioRef.current?.pause();
      setActiveAmbient(null);
    } else {
      if (audioRef.current) {
        audioRef.current.src = sound.url;
        audioRef.current.loop = true;
        audioRef.current.volume = volume;
        audioRef.current.play().catch(e => showToast("Vui lòng tương tác với màn hình để bật tiếng!"));
        setActiveAmbient(sound.id);
      }
    }
  };

  const handleVolumeChange = (v: number) => {
    setVolume(v);
    if (audioRef.current) audioRef.current.volume = v;
  };

  const formatTime = (s: number) => `${Math.floor(s/60).toString().padStart(2,'0')}:${(s%60).toString().padStart(2,'0')}`;

  return (
    <div className="flex flex-col items-center gap-12 py-10 max-w-2xl mx-auto w-full animate-slide-in">
      <audio ref={audioRef} />

      {/* Visual Display Section */}
      <div className="relative group w-full flex flex-col items-center">
        <div className={`absolute -inset-10 blur-[80px] opacity-20 transition-all duration-1000 bg-gradient-to-tr ${PET_STAGES[petStage].color} ${isActive ? 'animate-pulse scale-110' : 'opacity-10'}`}></div>

        <div className="relative glass p-16 rounded-[5rem] border-white shadow-2xl flex flex-col items-center gap-8 bg-white/40 w-full max-w-sm">
          <div className="relative">
            <div className={`text-[10rem] animate-float drop-shadow-2xl transition-all duration-700 ${isActive ? 'scale-110' : 'scale-100 grayscale-[20%]'}`}>
                {PET_STAGES[petStage].icon}
            </div>
          </div>

          <div className="text-center space-y-4">
            <div className={`px-6 py-2 rounded-full text-[11px] font-black uppercase tracking-[0.3em] bg-gradient-to-r text-white shadow-lg ${PET_STAGES[petStage].color}`}>
                {PET_STAGES[petStage].label}
            </div>
            <div className="text-8xl font-black text-slate-800 font-mono tracking-tighter drop-shadow-sm">
                {formatTime(seconds)}
            </div>
            <div className="flex gap-1 justify-center">
                {[0,1,2,3,4].map(s => (
                    <div key={s} className={`h-1.5 w-8 rounded-full transition-all ${s <= petStage ? 'bg-indigo-500 shadow-sm' : 'bg-slate-200'}`}></div>
                ))}
            </div>
          </div>
        </div>
      </div>

      {/* Controls Section */}
      <div className="flex items-center gap-6 z-10">
        <button 
          onClick={() => {setIsActive(false); setSeconds(mode === 'study' ? 25*60 : 5*60); setPetStage(0);}} 
          className="p-6 bg-white rounded-[2rem] border border-slate-100 shadow-xl text-slate-300 hover:text-rose-500 transition-all"
        >
          <RotateCcw size={32} strokeWidth={2.5}/>
        </button>

        <button 
          onClick={() => setIsActive(!isActive)} 
          className={`px-16 py-6 rounded-[3rem] font-black text-white shadow-2xl transition-all active:scale-95 flex items-center gap-4 text-2xl ${
            isActive ? 'bg-slate-800 shadow-slate-200' : 'bg-indigo-600 shadow-indigo-300'
          }`}
        >
          {isActive ? <><Pause size={32} fill="currentColor"/> DỪNG</> : <><Play size={32} fill="currentColor"/> TẬP TRUNG</>}
        </button>

        <button 
          onClick={() => setShowMusic(!showMusic)} 
          className={`p-6 rounded-[2rem] border transition-all ${showMusic ? 'bg-indigo-600 text-white shadow-indigo-200' : 'bg-white text-slate-300 border-slate-100 shadow-xl'}`}
        >
          <Music size={32} strokeWidth={2.5}/>
        </button>
      </div>

      {/* Improved Music & Ambient Widget */}
      {showMusic && (
        <div className="glass w-full p-10 rounded-[4rem] border-white shadow-2xl space-y-8 animate-slide-up bg-white/80 backdrop-blur-3xl">
          <div className="flex items-center justify-between">
            <h3 className="font-black text-2xl text-slate-800 tracking-tighter">Ambient Focus</h3>
            <button onClick={() => setShowMusic(false)} className="text-slate-300 hover:text-slate-800"><X size={24}/></button>
          </div>

          {/* Nature Sounds Grid */}
          <div className="grid grid-cols-2 gap-4">
             {AMBIENT_SOUNDS.map(sound => (
               <button 
                 key={sound.id}
                 onClick={() => toggleAmbient(sound)}
                 className={`p-6 rounded-[2.5rem] border-2 transition-all flex items-center gap-4 ${activeAmbient === sound.id ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl scale-[1.02]' : 'bg-slate-50 border-transparent text-slate-500 hover:bg-white hover:border-indigo-100'}`}
               >
                 <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${activeAmbient === sound.id ? 'bg-white/20' : 'bg-white shadow-sm'}`}>
                    <sound.icon size={24} />
                 </div>
                 <span className="font-black text-xs uppercase tracking-widest">{sound.name}</span>
               </button>
             ))}
          </div>

          {/* Volume Control */}
          <div className="bg-slate-50 p-6 rounded-[2.5rem] flex items-center gap-6">
             {volume === 0 ? <VolumeX size={24} className="text-slate-400" /> : <Volume2 size={24} className="text-indigo-600" />}
             <input 
               type="range" min="0" max="1" step="0.01" value={volume} 
               onChange={(e) => handleVolumeChange(parseFloat(e.target.value))}
               className="flex-1 accent-indigo-600 h-1.5 bg-slate-200 rounded-full appearance-none cursor-pointer"
             />
             <span className="text-[10px] font-black text-slate-400 w-8">{Math.round(volume * 100)}%</span>
          </div>

          <div className="flex items-center gap-4 py-4">
             <div className="h-[1px] flex-1 bg-slate-100"></div>
             <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Hoặc dùng YouTube</span>
             <div className="h-[1px] flex-1 bg-slate-100"></div>
          </div>

          <div className="flex gap-3">
            <input 
              value={activeVideo?.title || ''} 
              readOnly
              placeholder="Chưa có nhạc YouTube..." 
              className="flex-1 bg-white/80 rounded-2xl px-6 py-4 text-xs font-bold border-2 border-slate-50 outline-none text-slate-400" 
            />
            <button 
              onClick={async () => {
                const res = await searchYoutubeVideos("Lofi study music");
                if (res.length > 0) setActiveVideo(res[0]);
              }} 
              className="p-4 bg-rose-500 text-white rounded-2xl shadow-xl active:scale-95"
            >
              <Youtube size={24} strokeWidth={3}/>
            </button>
          </div>
          {activeVideo && <div className="hidden"><iframe src={`https://www.youtube.com/embed/${activeVideo.id}?autoplay=1`}></iframe></div>}
        </div>
      )}

      <div className="flex items-center gap-2 bg-indigo-50 px-6 py-3 rounded-full border border-indigo-100 animate-fade-in shadow-sm">
        <Award size={18} className="text-indigo-600"/>
        <span className="text-[10px] font-black text-indigo-700 uppercase tracking-widest">Hoàn thành để nhận 100 EXP</span>
      </div>

      <style>{`
        @keyframes float { 0% { transform: translateY(0); } 50% { transform: translateY(-10px); } 100% { transform: translateY(0); } }
        .animate-float { animation: float 3s ease-in-out infinite; }
        .no-scrollbar::-webkit-scrollbar { display: none; }
      `}</style>
    </div>
  );
};

