          </div>
        </div>
      )}

      <div className="flex items-center gap-3 bg-indigo-50/80 backdrop-blur-sm px-8 py-3.5 rounded-full border border-indigo-100 shadow-sm">
        <Sparkles size={18} className="text-indigo-600 animate-pulse"/>
        <span className="text-[10px] font-black text-indigo-700 uppercase tracking-[0.2em]">Hoàn thành để nhận {mode === 'study' ? '120' : '30'} EXP</span>
      </div>

      <style>{`
        @keyframes music-bar {
          0%, 100% { height: 4px; }
          50% { height: 100%; }
        }
        .animate-music-bar { animation: music-bar 0.8s ease-in-out infinite; }
      `}</style>
    </div>
  );
};

