import { GoogleGenAI, Type } from "@google/genai";

const FLASH_MODEL = 'gemini-3-flash-preview';
const IMAGE_MODEL = 'gemini-2.5-flash-image'; 

const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const SYSTEM_CONCISE = "Bạn là trợ lý học tập Gen Z. PHẢI TRẢ LỜI CỰC KỲ NGẮN GỌN, TRỰC DIỆN. Không chào hỏi rườm rà. Sử dụng Markdown để định dạng (bold, lists). Dùng icon phù hợp.";

export const suggestHashtags = async (content: string): Promise<string[]> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: `Suggest 3 trending Vietnamese hashtags for: "${content}". Return JSON array only.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (e) {
    return ["study", "genz"];
  }
};

export const callGeminiWithRetry = async (prompt: string, systemInstruction?: string): Promise<string> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: prompt,
      config: {
        systemInstruction: systemInstruction || SYSTEM_CONCISE,
        temperature: 0.7,
      },
    });
    return response.text || "Lỗi rồi fen!";
  } catch (error) {
    return "Đang bận học, thử lại sau...";
  }
};

export const generateMindMap = async (topic: string): Promise<any> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: `Mind map cho: "${topic}". JSON format: {root: string, children: [{label: string, subChildren: string[]}]}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            root: { type: Type.STRING },
            children: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  label: { type: Type.STRING },
                  subChildren: { type: Type.ARRAY, items: { type: Type.STRING } }
                }
              }
            }
          }
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (e) {
    return { root: topic, children: [] };
  }
};

export const checkVibePost = async (content: string, imageUrl?: string): Promise<{vibe: string, score: number, comment: string}> => {
  const ai = getAIInstance();
  const parts: any[] = [{ text: `Vibe check bài đăng (ngắn gọn 1 câu): "${content}"` }];
  if (imageUrl) parts.push({ inlineData: { data: imageUrl.split(',')[1], mimeType: 'image/jpeg' } });

  const response = await ai.models.generateContent({
    model: FLASH_MODEL,
    contents: { parts },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          vibe: { type: Type.STRING },
          score: { type: Type.NUMBER },
          comment: { type: Type.STRING }
        },
        required: ["vibe", "score", "comment"]
      }
    }
  });
  return JSON.parse(response.text || '{"vibe": "Chill", "score": 80, "comment": "Ổn!"}');
};

