const INITIAL_QUESTS: DailyQuest[] = [
  { id: 'q1', text: 'Học tập trung 25 phút', target: 25, current: 0, reward: 100, isClaimed: false },
  { id: 'q2', text: 'Hỏi Gia sư AI 3 câu hỏi', target: 3, current: 0, reward: 50, isClaimed: false },
  { id: 'q3', text: 'Đăng 1 bài kiến thức mới', target: 1, current: 0, reward: 30, isClaimed: false }
];

const App: React.FC = () => {
  const [userData, setUserData] = useState<UserProfile | null>(null);
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.FEED);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [showStreakModal, setShowStreakModal] = useState(false);
  const [showRedemption, setShowRedemption] = useState(false);
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  // Sync with Local Storage
  const syncStorage = useCallback((data: UserProfile) => {
    localStorage.setItem('studygram_user', JSON.stringify(data));
  }, []);

  const showToast = useCallback((message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  }, []);

  useEffect(() => {
    const savedData = localStorage.getItem('studygram_user');
    if (savedData) {
      try {
        const parsedData = JSON.parse(savedData) as UserProfile;
        const now = new Date();
        const today = now.toDateString();
        const lastLoginDate = parsedData.lastLogin ? new Date(parsedData.lastLogin).toDateString() : "";

        if (lastLoginDate && lastLoginDate !== today) {
          const lastDate = new Date(parsedData.lastLogin!);
          // Normalize dates to midnight for accurate day diff
          const d1 = new Date(lastDate.getFullYear(), lastDate.getMonth(), lastDate.getDate());
          const d2 = new Date(now.getFullYear(), now.getMonth(), now.getDate());
          const diffDays = Math.floor((d2.getTime() - d1.getTime()) / (1000 * 3600 * 24));

          if (diffDays > 1) {
            if (parsedData.streakShields > 0) {
              parsedData.streakShields -= 1;
              setTimeout(() => showToast("Đã dùng Khiên bảo vệ Streak! 🛡️", "success"), 1000);
            } else {
              parsedData.lives -= 1;
              if (parsedData.lives <= 0) {
                setShowRedemption(true);
              } else {
                setTimeout(() => showToast(`Mất 1 ❤️! Cẩn thận nha fen!`, "error"), 1000);
              }
            }
          }
          parsedData.dailyQuests = INITIAL_QUESTS;
        }

        setUserData(parsedData);
        if (parsedData.lastLogin && new Date(parsedData.lastLogin).toDateString() !== today) {
          setShowStreakModal(true);
        }
      } catch (e) {
        console.error("Corrupted storage", e);
        localStorage.removeItem('studygram_user');
      }
    }
    setTimeout(() => setIsLoading(false), 1500); 
  }, [showToast]);

  const handleUpdateUser = useCallback((updated: UserProfile) => {
    setUserData(updated);
    syncStorage(updated);
  }, [syncStorage]);

  const handleAddExp = useCallback((amount: number) => {
    setUserData(prev => {
        if (!prev) return null;
        const updated = { ...prev, exp: prev.exp + amount };
        syncStorage(updated);
        return updated;
    });
    showToast(`+${amount} EXP!`, 'success');
  }, [showToast, syncStorage]);

  const updateQuestProgress = (questId: string, amount: number) => {
    if (!userData) return;
    const updatedQuests = userData.dailyQuests.map(q => 
      q.id === questId ? { ...q, current: Math.min(q.target, q.current + amount) } : q
    );
    handleUpdateUser({ ...userData, dailyQuests: updatedQuests });
  };

  const claimQuestReward = (questId: string) => {
    if (!userData) return;
    const quest = userData.dailyQuests.find(q => q.id === questId);
    if (quest && quest.current >= quest.target && !quest.isClaimed) {
      const updatedQuests = userData.dailyQuests.map(q => 
        q.id === questId ? { ...q, isClaimed: true } : q
      );
      handleAddExp(quest.reward);
      handleUpdateUser({ ...userData, dailyQuests: updatedQuests });
      // @ts-ignore
      window.confetti({ particleCount: 50, spread: 60, origin: { y: 0.8 } });
    }
  };

  const handleAuth = (method: LoginMethod, name?: string) => {
    const newUser: UserProfile = {
      uid: 'u-' + Math.random().toString(36).slice(2, 7),
      name: name || 'Học giả Ẩn danh',
      avatar: `https://api.dicebear.com/7.x/notionists/svg?seed=${name || method}-${Math.random()}`,
      exp: 0, bio: 'Sẵn sàng chinh phục tri thức 🚀', joinedAt: Date.now(), streak: 1, lives: 3, streakShields: 0, completedQuizzes: 0, 
      loginMethod: method, isVerified: method !== 'guest', dailyQuests: INITIAL_QUESTS, lastLogin: Date.now(),
      skills: { criticalThinking: 20, focus: 20, creativity: 20, knowledge: 20, discipline: 20 },
      weakPoints: []
    };
    setUserData(newUser);
    syncStorage(newUser);
  };

  if (isLoading) return <LoadingScreen />;
  if (!userData) return <AuthScreen onAuth={handleAuth} />;

  return (
    <div className="min-h-screen text-slate-800 font-sans selection:bg-indigo-100 flex flex-col overflow-x-hidden bg-[#FDFCF8]">
      {toast && <Toast toast={toast} />}

      {showStreakModal && (
        <StreakModal 
          streak={userData.streak + 1} 
          onClaim={() => {
            handleUpdateUser({ ...userData, streak: userData.streak + 1, exp: userData.exp + 50, lastLogin: Date.now() });
            setShowStreakModal(false);
            // @ts-ignore
            window.confetti({ particleCount: 150, spread: 80, origin: { y: 0.6 } });
          }} 
        />
      )}

      {showRedemption && (
        <RedemptionModal 
          userData={userData}
          onSuccess={() => {
            handleUpdateUser({ ...userData, lives: 1, streakShields: 0, lastLogin: Date.now() });
            setShowRedemption(false);
            showToast("Hồi sinh thành công! 😇", "success");
          }}
          onFail={() => {
            handleUpdateUser({ ...userData, streak: 0, lives: 3, streakShields: 0, lastLogin: Date.now() });
            setShowRedemption(false);
            showToast("Streak đã bị dập tắt...", "error");
          }}
        />
      )}

      <Sidebar 
        isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} 
        userData={userData} setActiveTab={setActiveTab} activeTab={activeTab} 
        onLogout={() => { localStorage.removeItem('studygram_user'); setUserData(null); }}
      />

      <Header onOpenMenu={() => setSidebarOpen(true)} userData={userData} activeTab={activeTab} />

      <main className={`flex-1 w-full max-w-4xl mx-auto transition-all duration-500 ${activeTab === AppTab.TUTOR ? 'h-[calc(100vh-80px-100px)] overflow-hidden' : 'p-4 md:p-8 pb-32 mt-20'}`}>
        <div className="animate-fade-in transition-all">
          {activeTab === AppTab.FEED && <ZenDashboard userData={userData} onClaim={claimQuestReward} />}
          {activeTab === AppTab.FEED && <Feed userData={userData} onExp={(n) => { handleAddExp(n); updateQuestProgress('q3', 1); }} />}
          {activeTab === AppTab.MISSION && <MissionControl userData={userData} onUpdate={handleUpdateUser} />}
          {activeTab === AppTab.TUTOR && <AITutor userData={userData} onExp={(n) => { handleAddExp(n); updateQuestProgress('q2', 1); }} />}
          {activeTab === AppTab.FOCUS && <FocusZone onExp={(n) => { handleAddExp(n); updateQuestProgress('q1', 25); }} showToast={showToast} />}
          {activeTab === AppTab.TOOLS && <StudyTools onExp={handleAddExp} />}
          {activeTab === AppTab.QUIZ && <QuizArena onExp={handleAddExp} showToast={showToast} />}
          {activeTab === AppTab.RANK && <Leaderboard currentUid={userData.uid} userData={userData} />}
          {activeTab === AppTab.PROFILE && <Profile userData={userData} onUpdate={handleUpdateUser} onToast={showToast} />}
        </div>
      </main>

      <BottomNav activeTab={activeTab} setActiveTab={setActiveTab} />
    </div>
  );
};

const RedemptionModal: React.FC<{ userData: UserProfile, onSuccess: () => void, onFail: () => void }> = ({ userData, onSuccess, onFail }) => {
  const [step, setStep] = useState<'intro' | 'quiz'>('intro');
  const [quiz, setQuiz] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);

  const loadQuiz = async () => {
    setLoading(true);
    try {
      const data = await getDailyBlitzQuiz("Kiến thức tổng hợp khó");
      setQuiz(data);
      setStep('quiz');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] bg-slate-900/90 backdrop-blur-2xl flex items-center justify-center p-6">
      <div className="glass w-full max-w-md rounded-[4rem] p-12 text-center border-white shadow-2xl animate-slide-up">
        {step === 'intro' ? (
          <div className="space-y-8">
             <div className="w-24 h-24 bg-rose-500 rounded-[2.5rem] flex items-center justify-center text-white mx-auto animate-pulse shadow-2xl shadow-rose-500/30">
                <AlertTriangle size={48} />
             </div>
             <h2 className="text-4xl font-black text-white tracking-tighter">HỒI SINH?</h2>
             <p className="text-slate-300 font-bold text-sm leading-relaxed italic">Streak {userData.streak} ngày của fen đang đứng trước bờ vực thẳm. Giải đúng câu đố khó để giữ lại streak!</p>
             <div className="flex flex-col gap-3">
               <button onClick={loadQuiz} className="w-full py-5 bg-white text-rose-600 rounded-[1.8rem] font-black shadow-xl hover:scale-105 transition-all">
                  {loading ? <RefreshCw className="animate-spin mx-auto" /> : "CHẤP NHẬN THỬ THÁCH"}
               </button>
               <button onClick={onFail} className="text-slate-500 font-black text-[10px] uppercase tracking-widest py-2 hover:text-white transition-colors">CHẤP NHẬN MẤT STREAK</button>
             </div>
          </div>
        ) : (
          <div className="space-y-8 text-white">
             <div className="bg-white/10 p-6 rounded-3xl border border-white/20">
                <p className="text-lg font-black leading-relaxed">{quiz[0]?.question}</p>
             </div>
             <div className="grid grid-cols-1 gap-3">
                {quiz[0]?.options.map((opt: string, i: number) => (
                   <button 
                    key={i} 
                    onClick={() => opt === quiz[0].answer ? onSuccess() : onFail()}
                    className="p-5 bg-white/5 hover:bg-white/20 border border-white/10 rounded-2xl text-left font-bold transition-all"
                  >
                     {opt}
                   </button>
                ))}
             </div>
          </div>
        )}
      </div>
    </div>
  );
}

const ZenDashboard: React.FC<{ userData: UserProfile; onClaim: (id: string) => void }> = ({ userData, onClaim }) => {
  const [goal, setGoal] = useState('');
  const [goals, setGoals] = useState<{id: string, text: string, done: boolean}[]>([]);

  useEffect(() => {
    const savedGoals = localStorage.getItem(`goals_${userData.uid}`);
    if (savedGoals) setGoals(JSON.parse(savedGoals));
  }, [userData.uid]);

  const addGoal = () => {
    if (!goal.trim()) return;
    const newGoals = [...goals, { id: Date.now().toString(), text: goal, done: false }];
    setGoals(newGoals);
    localStorage.setItem(`goals_${userData.uid}`, JSON.stringify(newGoals));
    setGoal('');
  };

  const toggleGoal = (id: string) => {
    const newGoals = goals.map(g => g.id === id ? {...g, done: !g.done} : g);
    setGoals(newGoals);
    localStorage.setItem(`goals_${userData.uid}`, JSON.stringify(newGoals));
  };

  const isLowLives = userData.lives === 1;

  return (
    <div className="mb-12 space-y-8 animate-slide-up">
      <div className={`glass p-10 rounded-[4rem] border-white shadow-2xl transition-all duration-700 overflow-hidden relative group ${isLowLives ? 'bg-gradient-to-br from-rose-900 via-slate-900 to-black ring-8 ring-rose-500/20' : 'bg-gradient-to-br from-[#1a1c2c] to-[#0f172a]'} text-white`}>
         <div className="absolute top-0 right-0 p-10 opacity-10 group-hover:scale-110 transition-transform"><Flame size={200} fill="currentColor" /></div>

         <div className="relative z-10 grid grid-cols-1 md:grid-cols-2 gap-8 items-center">
            <div className="space-y-4">
               <div className="flex items-center gap-3">
                  {[...Array(3)].map((_, i) => (
                    <Heart 
                      key={i} 
                      size={32} 
                      className={`transition-all duration-500 ${i < userData.lives ? 'text-rose-500 fill-current drop-shadow-[0_0_12px_rgba(244,63,94,0.8)]' : 'text-slate-600'} ${isLowLives && i === 0 ? 'animate-heartbeat' : ''}`} 
                    />
                  ))}
               </div>
               <h2 className={`text-4xl font-black tracking-tighter ${isLowLives ? 'text-rose-500' : ''}`}>
                  {isLowLives ? 'NGUY KỊCH!' : 'SINH TỒN'}
               </h2>
               <p className="text-slate-400 font-bold text-sm leading-relaxed max-w-xs">
                  {isLowLives ? 'Chỉ còn 1 cơ hội cuối! Hãy hoàn thành Boss Challenge ngay!' : 'Đừng để dập tắt ngọn lửa tri thức fen ơi!'}
               </p>
            </div>

            <div className="flex flex-col items-center justify-center p-8 bg-white/5 rounded-[3rem] border border-white/10 backdrop-blur-md relative overflow-hidden">
               <div className={`relative ${userData.streak >= 7 ? 'text-indigo-400' : 'text-orange-500'}`}>
                  <Flame size={80} fill="currentColor" className={`${userData.streak >= 7 ? 'animate-phantom-glow' : 'animate-pulse'}`} />
                  <span className="absolute inset-0 flex items-center justify-center text-3xl font-black mt-4">{userData.streak}</span>
               </div>
               <span className="mt-4 text-[10px] font-black uppercase tracking-[0.4em] text-white/40">DAY STREAK</span>
               {userData.streakShields > 0 && (
                 <div className="mt-4 flex items-center gap-2 bg-indigo-600/40 px-4 py-1.5 rounded-full border border-indigo-400/50">
                    <Shield size={14} fill="currentColor" />
                    <span className="text-[10px] font-black uppercase tracking-widest">{userData.streakShields} SHIELD ON</span>
                 </div>
               )}
            </div>
         </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="glass p-8 rounded-[3rem] border-white shadow-xl bg-white/60 group hover:bg-white transition-all">
           <div className="flex items-center gap-3 mb-6">
              <ListTodo size={20} className="text-indigo-600" />
              <h4 className="text-sm font-black text-slate-800 uppercase tracking-widest">Mục tiêu hôm nay</h4>
