           </div>
           <div className="space-y-3 max-h-40 overflow-y-auto no-scrollbar">
              {goals.map(g => (
                <div key={g.id} onClick={() => toggleGoal(g.id)} className={`flex items-center gap-3 p-4 rounded-2xl cursor-pointer transition-all ${g.done ? 'bg-green-50 text-green-600 opacity-60' : 'bg-white shadow-sm border border-slate-50 hover:border-indigo-200'}`}>
                   {g.done ? <CheckCircle size={18} /> : <div className="w-4 h-4 rounded-full border-2 border-slate-200"></div>}
