import React, { useState, useEffect, useCallback } from 'react';
import { 
  Target, Rocket, Map, Activity, Calendar, 
  ChevronRight, Brain, AlertTriangle, CheckCircle,
  Loader2, Sparkles, Trophy, Book, BarChart3, FastForward,
  Shield, Sword, Heart, RefreshCw
} from 'lucide-react';
import { UserProfile, StudyMission, RoadmapNode } from '../types';
import { generateStudyRoadmap, getDailyBlitzQuiz, callGeminiWithRetry } from '../services/geminiService';

const MissionControl: React.FC<{ userData: UserProfile; onUpdate: (u: UserProfile) => void }> = ({ userData, onUpdate }) => {
  const [loading, setLoading] = useState(false);
  const [selectedGoal, setSelectedGoal] = useState<'HK' | 'THPTQG' | null>(null);
  const [subject, setSubject] = useState('Toán học');
  const [blitzQuiz, setBlitzQuiz] = useState<any[]>([]);
  const [quizLoading, setQuizLoading] = useState(false);
  const [bossChallenge, setBossChallenge] = useState<string | null>(null);
  const [bossLoading, setBossLoading] = useState(false);

  const generateBossChallenge = useCallback(async () => {
    setBossLoading(true);
    try {
      const challenge = await callGeminiWithRetry(`Tạo 1 thử thách học tập "Hardcore" duy nhất cho môn ${subject}. VD: "Giải 5 bài tích phân khó". Trả lời cực ngắn 1 câu.`);
      setBossChallenge(challenge);
    } catch (e) {
      setBossChallenge("Giải 3 bài tập khó nhất hôm nay!");
    } finally {
      setBossLoading(false);
    }
  }, [subject]);

  useEffect(() => {
    if (userData.currentMission) {
      generateBossChallenge();
    }
  }, [userData.currentMission, generateBossChallenge]);

  const startMission = async () => {
    if (!selectedGoal) return;
    setLoading(true);
    try {
      const roadmapData = await generateStudyRoadmap(selectedGoal, subject);
      const newMission: StudyMission = {
        goal: selectedGoal,
        subject: subject,
        targetDate: Date.now() + 30 * 24 * 60 * 60 * 1000,
        roadmap: roadmapData.roadmap.map((n: any, i: number) => ({
          ...n,
          status: i === 0 ? 'current' : 'locked'
        }))
      };
      onUpdate({ ...userData, currentMission: newMission });
    } finally {
      setLoading(false);
    }
  };

  const loadBlitz = async () => {
    setQuizLoading(true);
    try {
      const quiz = await getDailyBlitzQuiz(userData.currentMission?.subject || 'Kiến thức chung');
      setBlitzQuiz(quiz);
    } finally {
      setQuizLoading(false);
    }
  };

  const completeBoss = () => {
    const updated = { ...userData, streakShields: Math.min(userData.streakShields + 1, 3), exp: userData.exp + 200 };
    onUpdate(updated);
    setBossChallenge(null);
    // @ts-ignore
    window.confetti({ particleCount: 100, spread: 70, origin: { y: 0.6 } });
    setTimeout(() => generateBossChallenge(), 2000);
  };

  if (!userData.currentMission) {
    return (
      <div className="space-y-10 animate-slide-up max-w-2xl mx-auto py-10">
        <div className="text-center space-y-4">
          <div className="w-24 h-24 bg-indigo-600 rounded-[2.5rem] flex items-center justify-center text-white mx-auto shadow-2xl animate-float">
             <Rocket size={48} strokeWidth={2.5}/>
          </div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tighter leading-none">THIẾT LẬP CHIẾN DỊCH</h2>
          <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px]">AI sẽ cá nhân hóa lộ trình cho fen</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {[
            { id: 'HK', title: 'Thi Học Kỳ', icon: Book, color: 'bg-blue-500', desc: 'Tập trung ôn luyện kiến thức trọng tâm.' },
            { id: 'THPTQG', title: 'Thi THPT QG', icon: Trophy, color: 'bg-rose-500', desc: 'Lộ trình dài hạn chinh phục đỉnh cao.' }
          ].map(goal => (
            <button 
              key={goal.id} 
              onClick={() => setSelectedGoal(goal.id as any)}
              className={`glass p-8 rounded-[3.5rem] text-left border-4 transition-all duration-300 group ${selectedGoal === goal.id ? 'border-indigo-600 bg-white shadow-2xl' : 'border-white bg-white/40 opacity-70 hover:opacity-100 hover:translate-y-[-4px]'}`}
            >
              <div className={`w-14 h-14 ${goal.color} text-white rounded-2xl flex items-center justify-center shadow-lg mb-6 group-hover:rotate-6 transition-transform`}><goal.icon size={28}/></div>
              <h3 className="text-2xl font-black text-slate-800 mb-2 leading-none">{goal.title}</h3>
              <p className="text-[10px] text-slate-400 font-bold leading-relaxed uppercase tracking-wider">{goal.desc}</p>
            </button>
          ))}
        </div>

        <div className="bg-white p-6 rounded-[2.5rem] shadow-xl border-2 border-slate-50 relative">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4 mb-2 block">Môn học trọng tâm</label>
          <select 
            value={subject} 
            onChange={(e) => setSubject(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-2xl p-4 font-black text-slate-800 outline-none focus:ring-4 focus:ring-indigo-50 transition-all appearance-none cursor-pointer"
          >
            {['Toán học', 'Ngữ văn', 'Tiếng Anh', 'Vật lý', 'Hóa học', 'Sinh học', 'Lịch sử', 'Địa lý'].map(s => <option key={s} value={s}>{s}</option>)}
          </select>
          <div className="absolute right-10 bottom-8 pointer-events-none text-slate-300">
             <ChevronRight size={20} className="rotate-90" />
          </div>
        </div>

        <button 
          onClick={startMission} 
          disabled={!selectedGoal || loading}
          className="w-full py-8 bg-indigo-600 text-white rounded-[3.5rem] font-black text-xl shadow-2xl shadow-indigo-200 flex items-center justify-center gap-4 active:scale-95 transition-all disabled:opacity-50"
        >
          {loading ? <RefreshCw className="animate-spin" /> : <Sparkles size={28} fill="currentColor"/>}
          {loading ? 'ĐANG KHỞI TẠO...' : 'BẮT ĐẦU CHIẾN DỊCH 🚀'}
        </button>
      </div>
    );
  }

  const mission = userData.currentMission;

  return (
    <div className="space-y-8 animate-slide-up pb-32">
       {/* Boss Challenge Banner */}
       <div className={`glass p-10 rounded-[4rem] border-white shadow-2xl transition-all duration-500 overflow-hidden relative ${bossChallenge ? 'bg-gradient-to-br from-rose-600 via-rose-500 to-indigo-600 text-white' : 'bg-slate-100 opacity-50'}`}>
          <div className="absolute top-0 right-0 p-10 opacity-10 animate-pulse"><Sword size={200}/></div>
          <div className="relative z-10 space-y-4">
             <div className="flex items-center gap-2 px-4 py-1.5 bg-white/20 backdrop-blur-md rounded-full w-fit text-[10px] font-black uppercase tracking-widest border border-white/20">
                <Sparkles size={14} className="text-amber-300" /> DAILY BOSS FIGHT
             </div>
             <h3 className="text-3xl font-black tracking-tighter leading-none">THỬ THÁCH SINH TỒN</h3>
             {bossLoading ? <Loader2 className="animate-spin" /> : (
               <p className="text-xl font-bold leading-relaxed max-w-lg italic">
                  {bossChallenge ? `"${bossChallenge}"` : "Bạn đã tiêu diệt Boss hôm nay! Chờ hồi chiêu nhé..."}
               </p>
             )}
             {bossChallenge && (
               <div className="flex gap-4 pt-4">
                  <button onClick={completeBoss} className="px-8 py-4 bg-white text-rose-600 rounded-[1.5rem] font-black text-xs uppercase tracking-widest shadow-xl shadow-rose-900/20 active:scale-95 transition-all">HOÀN THÀNH</button>
                  <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-white/60">
                     <Shield size={16} fill="currentColor"/> +1 SHIELD REWARD
                  </div>
               </div>
             )}
          </div>
       </div>

       <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* Roadmap */}
          <div className="space-y-6">
             <div className="flex items-center gap-3 px-4">
                <Map size={20} className="text-indigo-600" />
                <h4 className="font-black text-slate-800 uppercase tracking-widest text-sm">Lộ trình Dynamic</h4>
             </div>
             <div className="space-y-4">
                {mission.roadmap.map((node, i) => (
                   <div key={node.id} className={`glass p-6 rounded-[2.5rem] flex items-center gap-6 border-2 transition-all ${node.status === 'current' ? 'border-indigo-600 bg-white scale-105 shadow-xl ring-8 ring-indigo-50' : 'border-white opacity-60 bg-white/40'}`}>
                      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-white font-black shadow-lg ${node.status === 'completed' ? 'bg-green-500' : node.status === 'current' ? 'bg-indigo-600 animate-pulse' : 'bg-slate-300'}`}>
                         {node.status === 'completed' ? <CheckCircle size={24}/> : i + 1}
                      </div>
                      <div className="flex-1">
                         <h5 className="font-black text-slate-800 text-sm">{node.title}</h5>
                         <p className="text-[10px] text-slate-400 font-bold uppercase truncate max-w-[150px]">{node.topics.join(', ')}</p>
                      </div>
                   </div>
                ))}
             </div>
          </div>

          <div className="space-y-8">
             {/* Stats */}
             <div className="glass p-8 rounded-[3.5rem] border-white shadow-xl bg-white/60">
                <div className="flex items-center justify-between mb-8">
                   <div className="flex items-center gap-3">
                      <Heart size={20} className="text-rose-500" fill="currentColor" />
                      <h4 className="font-black text-slate-800 uppercase tracking-widest text-sm">Vital Stats</h4>
                   </div>
                   <div className="flex gap-2">
                      {[...Array(3)].map((_, i) => (
                        <div key={i} className={`w-3 h-3 rounded-full transition-all duration-500 ${i < userData.lives ? 'bg-rose-500 shadow-[0_0_8px_rgba(244,63,94,0.5)]' : 'bg-slate-200'}`}></div>
                      ))}
                   </div>
                </div>
                <div className="space-y-6">
                   <div className="flex items-center justify-between p-5 bg-white rounded-3xl border border-slate-100 shadow-sm transition-all hover:shadow-md">
                      <div className="flex items-center gap-3">
                         <Shield size={20} className="text-indigo-600" fill="currentColor"/>
                         <span className="text-xs font-black text-slate-600 uppercase tracking-tight">Khiên bảo vệ Streak</span>
                      </div>
                      <span className="text-2xl font-black text-indigo-600">{userData.streakShields}</span>
                   </div>
                   <div className="p-5 bg-indigo-50/50 rounded-3xl text-[11px] font-bold text-indigo-900 italic leading-relaxed border border-indigo-100">
                      "Duy trì thói quen mỗi ngày là vũ khí tối thượng của mọi học giả Gen Z. Chúc fen sống dai!"
                   </div>
                </div>
             </div>

             {/* Blitz Test */}
             <div className="glass p-8 rounded-[3.5rem] border-white shadow-xl bg-white/60 relative overflow-hidden group">
                <div className="flex items-center justify-between mb-8">
                   <div className="flex items-center gap-3">
                      <Brain size={20} className="text-indigo-600" />
                      <h4 className="font-black text-slate-800 uppercase tracking-widest text-sm">Daily Blitz Test</h4>
                   </div>
                   <button onClick={loadBlitz} className="p-3 bg-slate-50 rounded-2xl text-slate-400 hover:text-indigo-600 transition-all hover:bg-white"><FastForward size={18}/></button>
                </div>

                {blitzQuiz.length > 0 ? (
                  <div className="space-y-6 animate-slide-in">
                     <div className="p-6 bg-white rounded-3xl border border-slate-100 shadow-inner">
                        <p className="text-sm font-black text-slate-800 leading-relaxed mb-4">{blitzQuiz[0].question}</p>
                        <div className="grid grid-cols-1 gap-2">
                           {blitzQuiz[0].options.map((opt: any, i: number) => (
                             <button key={i} className="p-4 bg-white rounded-2xl border border-slate-100 text-left text-xs font-bold text-slate-600 hover:border-indigo-400 hover:bg-indigo-50 transition-all">
                               {opt}
                             </button>
                           ))}
                        </div>
                     </div>
                     <button className="w-full py-4 bg-indigo-600 text-white rounded-[1.8rem] font-black text-[10px] uppercase tracking-widest shadow-lg shadow-indigo-100">CÂU TIẾP THEO</button>
                  </div>
                ) : (
                  <div className="text-center py-10 space-y-4">
                     {quizLoading ? <RefreshCw className="animate-spin mx-auto text-indigo-400"/> : <Sparkles size={40} className="mx-auto text-amber-400 animate-float" />}
                     <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sẵn sàng test nhanh 3 câu hôm nay để tăng EXP?</p>
                     {!quizLoading && <button onClick={loadBlitz} className="px-10 py-4 bg-indigo-600 text-white rounded-[1.8rem] font-black text-[10px] uppercase tracking-widest shadow-xl shadow-indigo-100 active:scale-95 transition-all">BẮT ĐẦU BLITZ</button>}
                  </div>
                )}
             </div>
          </div>
       </div>
    </div>
  );
};

