import { GoogleGenAI, Type } from "@google/genai";

const FLASH_MODEL = 'gemini-3-flash-preview';
const IMAGE_MODEL = 'gemini-2.5-flash-image'; 

const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const SYSTEM_CONCISE = "Bạn là trợ lý học tập Gen Z. PHẢI TRẢ LỜI CỰC KỲ NGẮN GỌN, TRỰC DIỆN. Không chào hỏi rườm rà. Sử dụng Markdown. Dùng icon phù hợp.";

export const getOfficialExamLinks = async (subject: string, year: string, province: string): Promise<any[]> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: `Tìm link đề thi chính thức môn ${subject} năm ${year} của Sở GD ${province}. Trích xuất URL và tiêu đề.`,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });
    return response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
  } catch (e) {
    return [];
  }
};

export const generateExamPaper = async (subject: string, level: string): Promise<any[]> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: `Tạo bộ đề thi trắc nghiệm môn ${subject} theo cấu trúc đề thi Sở GD (mức độ ${level}). Gồm 5 câu hỏi khó. Trả về JSON: [{question: string, options: [string], answer: string, explanation: string}]`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING } },
              answer: { type: Type.STRING },
              explanation: { type: Type.STRING }
            }
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (e) {
    return [];
  }
};

export const generateStudyRoadmap = async (goal: string, subject: string): Promise<any> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: `Tạo lộ trình học ôn ${goal} cho môn ${subject}. Trả về JSON: {roadmap: [{id: string, title: string, topics: string[]}]}. Tối đa 5 chặng.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            roadmap: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING },
                  title: { type: Type.STRING },
                  topics: { type: Type.ARRAY, items: { type: Type.STRING } }
                }
              }
            }
          }
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (e) {
    return { roadmap: [] };
  }
};

export const getDailyBlitzQuiz = async (subject: string): Promise<any[]> => {
  const ai = getAIInstance();
  try {
