      parts: [
        { inlineData: { data: base64Image.split(',')[1], mimeType: 'image/jpeg' } },
        { text: prompt || "Giải thích ảnh ngắn gọn." }
      ]
    },
    config: { systemInstruction: SYSTEM_CONCISE }
