  const ai = getAIInstance();
  const res = await ai.models.generateContent({
    model: FLASH_MODEL,
    contents: history.map(h => ({ role: h.role === 'ai' ? 'model' : 'user', parts: [{ text: h.text }] })),
    config: { 
      systemInstruction: `Bạn là trọng tài tranh biện. Chủ đề: ${topic}. Phản biện cực gắt và ngắn gọn.`,
      temperature: 1.0
    }
  });
  return res.text || "";
};

export const downloadAsFile = (content: string, filename: string) => {
  const blob = new Blob([content], { type: 'text/plain' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename; a.click();
  URL.revokeObjectURL(url);
};

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Target, Rocket, Map, Activity, Calendar, 
  ChevronRight, Brain, AlertTriangle, CheckCircle,
  Loader2, Sparkles, Trophy, Book, BarChart3, FastForward,
  Shield, Sword, Heart, RefreshCw, Zap, GraduationCap,
  Filter, BookOpen, Layers, ArrowLeft
} from 'lucide-react';
import { UserProfile, StudyMission, Grade, ExamDifficulty } from '../types';
import { generateExamRoadmap, generateExamPaper, callGeminiWithRetry } from '../services/geminiService';

const MissionControl: React.FC<{ userData: UserProfile; onUpdate: (u: UserProfile) => void }> = ({ userData, onUpdate }) => {
  const [loading, setLoading] = useState(false);
  const [grade, setGrade] = useState<Grade>('12');
  const [subject, setSubject] = useState('Toán học');
  const [activeExam, setActiveExam] = useState<any[] | null>(null);
  const [examLoading, setExamLoading] = useState(false);
  const [bossChallenge, setBossChallenge] = useState<string | null>(null);
  const [bossLoading, setBossLoading] = useState(false);

  const generateBossChallenge = useCallback(async () => {
    setBossLoading(true);
    try {
      const challenge = await callGeminiWithRetry(`Tạo 1 thử thách học tập Vận dụng cao (9+) cực khó lớp ${grade} môn ${subject}. Trả lời cực ngắn 1 câu.`);
      setBossChallenge(challenge);
    } catch (e) {
      setBossChallenge("Giải quyết bài tập khó nhất trong đề thi năm nay!");
    } finally {
      setBossLoading(false);
    }
  }, [subject, grade]);

  useEffect(() => {
    if (userData.currentMission && !bossChallenge) {
      generateBossChallenge();
    }
  }, [userData.currentMission]);

  const startMission = async () => {
    setLoading(true);
    try {
      const roadmapData = await generateExamRoadmap(grade, subject);
      const newMission: StudyMission = {
        goal: 'THPTQG',
        grade: grade,
        targetDate: Date.now() + 60 * 24 * 60 * 60 * 1000,
        subject: subject,
        roadmap: roadmapData.roadmap.map((n: any, i: number) => ({
          ...n,
          status: i === 0 ? 'current' : 'locked'
        }))
      };
      onUpdate({ ...userData, currentMission: newMission });
    } finally {
      setLoading(false);
    }
  };

  const loadExam = async (difficulty: ExamDifficulty) => {
    setExamLoading(true);
    try {
      const exam = await generateExamPaper(subject, grade, difficulty);
      setActiveExam(exam);
    } catch (e) {
      setActiveExam([]);
    } finally {
      setExamLoading(false);
    }
  };

  const completeBoss = () => {
    const updated = { ...userData, streakShields: Math.min(userData.streakShields + 1, 3), exp: userData.exp + 300 };
    onUpdate(updated);
    setBossChallenge(null);
    // @ts-ignore
    window.confetti({ particleCount: 200, spread: 80, origin: { y: 0.6 } });
  };

  if (activeExam) {
    return (
      <div className="space-y-8 animate-slide-in pb-32">
        <button onClick={() => setActiveExam(null)} className="flex items-center gap-2 text-slate-400 hover:text-indigo-600 mb-6 font-black text-[10px] uppercase tracking-widest transition-colors">
          <ArrowLeft size={16} /> QUAY LẠI SẢNH ĐỀ
        </button>
        <div className="glass p-10 rounded-[4rem] border-white shadow-2xl bg-white/60">
           <div className="flex justify-between items-center mb-10">
              <h3 className="text-2xl font-black text-slate-800 tracking-tighter">BỘ ĐỀ THỰC CHIẾN LỚP {grade}</h3>
              <span className="bg-indigo-600 text-white px-5 py-2 rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg">MÔN {subject.toUpperCase()}</span>
           </div>
           <div className="space-y-10">
              {activeExam.map((q, i) => (
                <div key={i} className="p-8 bg-white/50 rounded-[3rem] border border-white shadow-inner animate-slide-up" style={{ animationDelay: `${i * 0.1}s` }}>
                   <p className="font-black text-slate-800 text-lg mb-6 leading-relaxed"><span className="text-indigo-600 mr-2">CÂU {i+1}:</span> {q.question}</p>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                      {q.options.map((opt: string, idx: number) => (
                        <button key={idx} className="p-5 bg-white border border-slate-100 rounded-2xl text-left text-sm font-bold text-slate-600 hover:bg-indigo-50 hover:border-indigo-400 transition-all flex items-center gap-3">
                           <div className="w-8 h-8 rounded-lg bg-slate-50 flex items-center justify-center text-[10px] font-black shrink-0">{String.fromCharCode(65 + idx)}</div>
                           {opt}
                        </button>
                      ))}
                   </div>
                </div>
              ))}
           </div>
           <button onClick={() => { setActiveExam(null); onUpdate({...userData, exp: userData.exp + 100}); }} className="w-full mt-10 py-6 bg-indigo-600 text-white rounded-[2.5rem] font-black text-sm uppercase tracking-[0.2em] shadow-2xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95">HOÀN THÀNH & NHẬN XP</button>
        </div>
      </div>
    );
  }

  if (!userData.currentMission) {
    return (
      <div className="space-y-10 animate-slide-up max-w-2xl mx-auto py-10">
        <div className="text-center space-y-4">
          <div className="w-24 h-24 bg-gradient-to-br from-indigo-600 to-indigo-800 rounded-[2.8rem] flex items-center justify-center text-white mx-auto shadow-2xl animate-float">
             <GraduationCap size={48} strokeWidth={2.5}/>
          </div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tighter leading-none">SIÊU KHO ĐỀ 10-12</h2>
          <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px]">Cá nhân hóa theo khối lớp và mục tiêu của fen</p>
        </div>

        <div className="grid grid-cols-3 gap-4">
          {['10', '11', '12'].map(g => (
            <button 
              key={g} 
              onClick={() => setGrade(g as Grade)}
              className={`p-6 rounded-[2.5rem] border-4 transition-all ${grade === g ? 'bg-indigo-600 text-white border-indigo-200 shadow-xl scale-105' : 'bg-white text-slate-400 border-white hover:border-indigo-100'}`}
            >
               <span className="text-[10px] font-black block uppercase tracking-widest mb-1 opacity-60">KHỐI</span>
               <span className="text-3xl font-black">LỚP {g}</span>
            </button>
          ))}
        </div>

        <div className="bg-white p-7 rounded-[3.5rem] shadow-xl border-2 border-slate-50 relative group">
          <div className="absolute top-0 left-0 p-10 opacity-5 group-hover:rotate-12 transition-transform"><Book size={100}/></div>
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4 mb-3 block">CHỌN MÔN CHIẾN ĐẤU</label>
          <select 
            value={subject} 
            onChange={(e) => setSubject(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-2xl p-6 font-black text-slate-800 outline-none focus:ring-4 focus:ring-indigo-50 transition-all appearance-none cursor-pointer relative z-10"
          >
            {['Toán học', 'Ngữ văn', 'Tiếng Anh', 'Vật lý', 'Hóa học', 'Sinh học', 'Lịch sử', 'Địa lý'].map(s => <option key={s} value={s}>{s}</option>)}
          </select>
          <div className="absolute right-10 bottom-11 pointer-events-none text-slate-300 z-10">
             <ChevronRight size={24} className="rotate-90" />
          </div>
        </div>

        <button 
          onClick={startMission} 
          disabled={loading}
          className="w-full py-8 bg-indigo-600 text-white rounded-[4rem] font-black text-xl shadow-2xl shadow-indigo-200 flex items-center justify-center gap-4 active:scale-95 transition-all disabled:opacity-50"
        >
          {loading ? <RefreshCw className="animate-spin" /> : <Sparkles size={28} fill="currentColor"/>}
          {loading ? 'ĐANG TỔNG HỢP KHO ĐỀ...' : 'KHỞI ĐỘNG HÀNH TRÌNH 🚀'}
        </button>
      </div>
    );
  }

  const mission = userData.currentMission;

  return (
    <div className="space-y-8 animate-slide-up pb-32">
       {/* Boss Banner - Hardcore Mode */}
       <div className={`glass p-10 rounded-[4.5rem] border-white shadow-2xl transition-all duration-700 overflow-hidden relative ${bossChallenge ? 'bg-gradient-to-br from-rose-600 via-indigo-600 to-purple-800 text-white ring-8 ring-white/10' : 'bg-slate-100 opacity-50'}`}>
          <div className="absolute top-0 right-0 p-12 opacity-10 animate-pulse"><Sword size={250}/></div>
          <div className="relative z-10 space-y-6">
             <div className="flex items-center gap-3 px-5 py-2 bg-white/20 backdrop-blur-md rounded-full w-fit text-[11px] font-black uppercase tracking-widest border border-white/20">
                <Sparkles size={16} className="text-amber-300" /> BOSS FIGHT: VẬN DỤNG CAO (9+)
             </div>
             <h3 className="text-4xl font-black tracking-tighter leading-none">THỬ THÁCH TỬ THẦN</h3>
             {bossLoading ? <Loader2 className="animate-spin" /> : (
               <p className="text-xl font-bold leading-relaxed max-w-xl italic text-indigo-50">
                  {bossChallenge ? `"${bossChallenge}"` : "Tuyệt đỉnh! Fen đã hạ gục Boss nâng cao."}
               </p>
