             {bossChallenge && (
               <div className="flex gap-6 pt-4 items-center">
                  <button onClick={completeBoss} className="px-12 py-5 bg-white text-rose-600 rounded-[2.2rem] font-black text-xs uppercase tracking-widest shadow-2xl hover:scale-105 active:scale-95 transition-all">GIẢI QUYẾT BOSS</button>
                  <div className="flex flex-col">
                     <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-white">
                        <Shield size={18} fill="currentColor" className="text-amber-300"/> +1 KHIÊN STREAK
