import { GoogleGenAI, Type } from "@google/genai";

const FLASH_MODEL = 'gemini-3-flash-preview';

const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const SYSTEM_CURRICULUM = `Bạn là trợ lý giáo dục cao cấp tại Việt Nam. 
QUY TẮC BẮT BUỘC:
1. Chỉ sử dụng kiến thức từ Chương trình GDPT 2018 (SGK Kết nối tri thức, Chân trời sáng tạo, Cánh diều).
2. Tuyệt đối không dùng kiến thức chương trình cũ 2006.
3. Cấu trúc câu hỏi trắc nghiệm phải bám sát định hướng thi tốt nghiệp THPT từ năm 2025.
4. Trả lời cực kỳ ngắn gọn, súc tích, chuyên nghiệp.
5. Luôn ưu tiên các ví dụ thực tế trong đời sống Việt Nam.`;

export const generateExamRoadmap = async (grade: string, subject: string): Promise<any> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: `Tạo lộ trình 5 bước ôn tập môn ${subject} lớp ${grade} (SGK mới 2018). 
      Format JSON: {roadmap: [{id: string, title: string, difficulty: 'theory'|'practice'|'hardcore', topics: string[]}]}`,
      config: {
        systemInstruction: SYSTEM_CURRICULUM,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            roadmap: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING },
                  title: { type: Type.STRING },
                  difficulty: { type: Type.STRING },
                  topics: { type: Type.ARRAY, items: { type: Type.STRING } }
                }
              }
            }
          }
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (e) {
    return { roadmap: [] };
  }
};

export const generateExamPaper = async (subject: string, grade: string, difficulty: string): Promise<any[]> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: `Tạo 5 câu hỏi trắc nghiệm lớp ${grade} môn ${subject} bám sát SGK mới, độ khó: ${difficulty}. 
      JSON format: [{question: string, options: [string], answer: string, explanation: string}]`,
      config: {
        systemInstruction: SYSTEM_CURRICULUM,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING } },
              answer: { type: Type.STRING },
              explanation: { type: Type.STRING }
            }
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (e) {
    return [];
  }
};

export const callGeminiWithRetry = async (prompt: string, systemInstruction?: string): Promise<string> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: prompt,
      config: {
        systemInstruction: systemInstruction || SYSTEM_CURRICULUM,
        temperature: 0.7,
      },
    });
    return response.text || "Đã xảy ra lỗi hệ thống.";
  } catch (error) {
    return "Hệ thống đang quá tải, vui lòng thử lại.";
  }
};

export const getTutorResponse = async (msg: string) => callGeminiWithRetry(msg, SYSTEM_CURRICULUM);
