import React, { useState } from 'react';
import { 
  Rocket, ChevronRight, CheckCircle, Loader2, 
  ArrowLeft, GraduationCap, Layers, Zap, Lock
} from 'lucide-react';
import { UserProfile, StudyMission, Grade, ExamDifficulty } from '../types';
import { generateExamRoadmap, generateExamPaper } from '../services/geminiService';

const MissionControl: React.FC<{ userData: UserProfile; onUpdate: (u: UserProfile) => void }> = ({ userData, onUpdate }) => {
  const [loading, setLoading] = useState(false);
  const [loadingNodeId, setLoadingNodeId] = useState<string | null>(null);
  const [grade, setGrade] = useState<Grade>('12');
  const [subject, setSubject] = useState('Toán học');
  const [activeExam, setActiveExam] = useState<any[] | null>(null);

  const startMission = async () => {
    setLoading(true);
    try {
      const roadmapData = await generateExamRoadmap(grade, subject);
      const newMission: StudyMission = {
        goal: 'THPTQG',
        grade: grade,
        targetDate: Date.now() + 60 * 24 * 60 * 60 * 1000,
        subject: subject,
        roadmap: roadmapData.roadmap.map((n: any, i: number) => ({
          ...n,
          status: i === 0 ? 'current' : 'locked'
        }))
      };
      onUpdate({ ...userData, currentMission: newMission });
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const loadExam = async (nodeId: string, difficulty: ExamDifficulty) => {
    setLoadingNodeId(nodeId);
    try {
      const exam = await generateExamPaper(subject, grade, difficulty);
      setActiveExam(exam);
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingNodeId(null);
    }
  };

  const finishExam = () => {
    if (!userData.currentMission) return;

    const currentRoadmap = [...userData.currentMission.roadmap];
    const currentIndex = currentRoadmap.findIndex(n => n.status === 'current');

    if (currentIndex !== -1) {
      currentRoadmap[currentIndex].status = 'completed';
      if (currentIndex + 1 < currentRoadmap.length) {
        currentRoadmap[currentIndex + 1].status = 'current';
      }
    }

    onUpdate({
      ...userData,
      exp: userData.exp + 150,
      currentMission: {
        ...userData.currentMission,
        roadmap: currentRoadmap
      }
    });
    setActiveExam(null);
    // @ts-ignore
    window.confetti({ particleCount: 100, spread: 70, origin: { y: 0.6 } });
  };

  if (activeExam) {
    return (
      <div className="content-container animate-in space-y-4 px-4 pb-40">
        <button onClick={() => setActiveExam(null)} className="flex items-center gap-2 text-slate-500 font-bold text-sm mb-4">
          <ArrowLeft size={16} /> QUAY LẠI
        </button>
        <div className="bg-white rounded-3xl p-6 shadow-xl border border-slate-100 border-b-4 border-b-indigo-200">
          <div className="mb-6">
            <h3 className="text-xl font-black text-slate-800 tracking-tight">Thử Thách Tri Thức</h3>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">Bám sát cấu trúc thi 2025</p>
          </div>
          <div className="space-y-8">
            {activeExam.map((q, i) => (
              <div key={i} className="space-y-4 border-b border-slate-50 pb-6 last:border-0">
                <p className="font-bold text-slate-800 leading-snug text-base">
                  <span className="inline-flex items-center justify-center w-6 h-6 bg-indigo-100 text-indigo-600 rounded-lg text-xs mr-2">{i+1}</span>
                  {q.question}
                </p>
                <div className="grid grid-cols-1 gap-2.5">
                  {q.options.map((opt: string, idx: number) => (
                    <button key={idx} className="group p-4 text-left text-sm bg-slate-50 rounded-2xl border-2 border-transparent hover:border-indigo-100 active:border-indigo-500 active:bg-white transition-all flex items-center gap-3">
                      <span className="w-8 h-8 rounded-xl bg-white border border-slate-200 flex items-center justify-center font-black text-xs text-slate-400 group-active:text-indigo-600 transition-colors">
                        {String.fromCharCode(65 + idx)}
                      </span>
                      <span className="flex-1 font-semibold text-slate-600">{opt}</span>
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>
          <button onClick={finishExam} className="w-full mt-10 py-5 bg-indigo-600 text-white rounded-2xl font-black shadow-xl shadow-indigo-100 active:scale-95 transition-all">
            NỘP BÀI & NHẬN 150 EXP
          </button>
        </div>
      </div>
    );
  }

  if (!userData.currentMission) {
    return (
      <div className="content-container animate-in space-y-8 px-4 py-6">
        <div className="text-center space-y-2">
          <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-lg mb-4">
             <GraduationCap size={32} />
          </div>
          <h2 className="text-2xl font-extrabold text-slate-900">Thiết kế Lộ trình Học</h2>
          <p className="text-slate-500 text-sm italic font-medium">Chọn khối lớp để AI tổng hợp kiến thức SGK mới</p>
        </div>

        <div className="space-y-6">
          <div className="flex gap-2 p-1 bg-slate-100 rounded-[1.5rem]">
            {['10', '11', '12'].map(g => (
              <button 
                key={g} 
                onClick={() => setGrade(g as Grade)}
                className={`flex-1 py-3.5 rounded-2xl font-black text-xs transition-all ${grade === g ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}
              >
                LỚP {g}
              </button>
            ))}
          </div>

          <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm">
            <label className="text-[10px] font-black text-slate-300 uppercase tracking-[0.2em] block mb-4">Môn học trọng tâm</label>
            <div className="grid grid-cols-2 gap-2">
              {['Toán học', 'Ngữ văn', 'Tiếng Anh', 'Vật lý', 'Hóa học', 'Sinh học', 'Lịch sử', 'Địa lý'].map(s => (
                <button 
                  key={s} 
                  onClick={() => setSubject(s)}
                  className={`p-3.5 rounded-xl text-xs font-bold border-2 transition-all ${subject === s ? 'bg-indigo-50 border-indigo-500 text-indigo-700 shadow-sm' : 'bg-slate-50 border-transparent text-slate-500 hover:bg-white hover:border-slate-100'}`}
                >
                  {s}
                </button>
              ))}
            </div>
          </div>

          <button 
            onClick={startMission} 
            disabled={loading}
            className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black shadow-xl flex items-center justify-center gap-3 disabled:opacity-50 active:scale-95 transition-all"
          >
            {loading ? <Loader2 className="animate-spin" /> : <Rocket size={20}/>}
            {loading ? 'ĐANG BIÊN SOẠN...' : 'BẮT ĐẦU CHIẾN DỊCH'}
          </button>
        </div>
      </div>
    );
  }

  const mission = userData.currentMission;

  return (
    <div className="content-container animate-in space-y-6 px-4 py-2 pb-40">
       <div className="bg-gradient-to-br from-indigo-600 to-indigo-800 p-7 rounded-[2.5rem] text-white shadow-xl flex justify-between items-center relative overflow-hidden group">
          <div className="relative z-10">
             <div className="flex gap-2 mb-3">
                <span className="bg-white/20 px-2.5 py-1 rounded-lg text-[10px] font-black uppercase tracking-widest border border-white/10">LỚP {mission.grade}</span>
                <span className="bg-white/20 px-2.5 py-1 rounded-lg text-[10px] font-black uppercase tracking-widest border border-white/10">{mission.subject}</span>
             </div>
             <h3 className="text-2xl font-black tracking-tight">Hành trình Tri thức</h3>
             <p className="text-indigo-100 text-[10px] font-bold uppercase tracking-widest mt-1 opacity-80">Chương trình GDPT 2018</p>
          </div>
          <Layers size={48} className="absolute right-[-10px] bottom-[-10px] text-white/10 group-hover:scale-125 transition-transform duration-700" />
       </div>

       <div className="space-y-4">
          {mission.roadmap.map((node, i) => {
             const isLocked = node.status === 'locked';
             const isCurrent = node.status === 'current';
             const isCompleted = node.status === 'completed';
             const isLoadingThis = loadingNodeId === node.id;

             return (
                <button 
                  key={node.id} 
                  disabled={isLocked || loadingNodeId !== null}
                  onClick={() => !isLocked && loadExam(node.id, node.difficulty)}
