  const [userAnswers, setUserAnswers] = useState<Record<number, string>>({});
  const [isReviewed, setIsReviewed] = useState(false);

  const startMission = async () => {
    setLoading(true);
    try {
      const roadmapData = await generateExamRoadmap(grade, subject);
      const newMission: StudyMission = {
        goal: 'THPTQG',
        grade: grade,
        targetDate: Date.now() + 60 * 24 * 60 * 60 * 1000,
        subject: subject,
        roadmap: roadmapData.roadmap.map((n: any) => ({
          ...n,
          status: 'current'
        }))
      };
      onUpdate({ ...userData, currentMission: newMission });
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const loadExam = async (nodeId: string, difficulty: ExamDifficulty) => {
    setLoadingNodeId(nodeId);
    setUserAnswers({});
    setIsReviewed(false);
    try {
      const exam = await generateExamPaper(subject, grade, difficulty, questionCount);
      setActiveExam(exam);
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingNodeId(null);
    }
  };

  const scoreInfo = useMemo(() => {
    if (!activeExam) return { correct: 0, total: 0, exp: 0 };
    let correct = 0;
    activeExam.forEach((q, i) => {
      if (userAnswers[i] === q.answer) correct++;
    });
    return {
      correct,
      total: activeExam.length,
      exp: correct * 30
    };
  }, [activeExam, userAnswers]);

  const finishExam = () => {
    if (!isReviewed) {
      setIsReviewed(true);
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }

    onUpdate({
      ...userData,
      exp: userData.exp + scoreInfo.exp,
      completedQuizzes: userData.completedQuizzes + 1
    });

    setActiveExam(null);
    // @ts-ignore
    window.confetti({ 
      particleCount: 150, 
      spread: 100, 
      origin: { y: 0.6 },
      colors: scoreInfo.correct / scoreInfo.total > 0.5 ? undefined : ['#94a3b8', '#cbd5e1']
    });
  };

  const handleSelect = (qIdx: number, option: string) => {
    if (isReviewed) return;
    setUserAnswers(prev => ({ ...prev, [qIdx]: option }));
  };

  if (activeExam) {
    return (
      <div className="content-container animate-in space-y-4 px-4 pb-40">
        <div className="bg-white/90 backdrop-blur-md p-4 sticky top-0 z-30 -mx-4 mb-4 border-b border-slate-100 flex items-center justify-between shadow-sm">
          <button onClick={() => setActiveExam(null)} className="flex items-center gap-2 text-slate-500 font-bold text-sm">
            <ArrowLeft size={16} /> THOÁT
          </button>
          <div className="flex gap-2">
            <div className="bg-slate-100 px-3 py-1.5 rounded-full text-[10px] font-black text-slate-500 uppercase">
              {Object.keys(userAnswers).length}/{activeExam.length} CÂU
            </div>
            {isReviewed && (
              <div className="bg-indigo-600 text-white px-3 py-1.5 rounded-full text-[10px] font-black uppercase">
                ĐÚNG {scoreInfo.correct}/{scoreInfo.total}
              </div>
            )}
          </div>
        </div>

        {isReviewed && (
          <div className="bg-gradient-to-br from-indigo-600 to-purple-700 p-8 rounded-[2.5rem] text-white shadow-xl animate-slide-up mb-8">
            <div className="flex justify-between items-center mb-4">
              <Award size={48} className="opacity-50" />
              <div className="text-right">
                <p className="text-[10px] font-black uppercase tracking-widest opacity-70">Kết quả bài thi</p>
                <h4 className="text-4xl font-black">{Math.round((scoreInfo.correct / scoreInfo.total) * 100)}%</h4>
              </div>
            </div>
            <p className="font-bold text-sm leading-relaxed mb-4 opacity-90 italic">
              {scoreInfo.correct === scoreInfo.total ? "Thật xuất sắc! Fen đúng là một chiến thần tri thức thực thụ! 🚀" : 
               scoreInfo.correct > scoreInfo.total / 2 ? "Khá lắm! Cùng xem lại những câu chưa đúng để hoàn thiện nhé. ✨" : 
               "Không sao cả, thất bại là mẹ thành công. Hãy đọc kỹ phần giải thích của AI bên dưới."}
            </p>
            <div className="bg-white/20 p-4 rounded-2xl flex items-center justify-between border border-white/10">
              <span className="text-xs font-black uppercase">Điểm thưởng nhận được:</span>
              <span className="text-xl font-black">+{scoreInfo.exp} EXP</span>
            </div>
          </div>
        )}

        <div className="space-y-12">
          {activeExam.map((q, i) => {
            const isCorrect = userAnswers[i] === q.answer;
            const isWrong = userAnswers[i] && userAnswers[i] !== q.answer;

            return (
              <div key={i} className={`bg-white rounded-[2.5rem] p-8 border-2 shadow-sm transition-all ${
                isReviewed ? (isCorrect ? 'border-green-200 bg-green-50/10' : 'border-rose-100 bg-rose-50/10') : 'border-slate-100'
              }`}>
                <div className="flex items-start gap-4 mb-6">
                  <span className={`shrink-0 w-10 h-10 rounded-2xl flex items-center justify-center font-black text-sm shadow-sm ${
                    isReviewed ? (isCorrect ? 'bg-green-500 text-white' : 'bg-rose-500 text-white') : 'bg-slate-900 text-white'
                  }`}>
                    {i+1}
                  </span>
                  <div className="flex-1">
                    <p className="font-bold text-slate-800 leading-snug text-lg pt-1">
                      {q.question}
                    </p>
                  </div>
                </div>

                <div className="grid grid-cols-1 gap-3">
                  {q.options.map((opt: string, idx: number) => {
                    const optionChar = String.fromCharCode(65 + idx);
                    const isSelected = userAnswers[i] === opt;
                    const isRightAnswer = q.answer === opt;

                    let btnStyle = "bg-slate-50 border-transparent text-slate-600";
                    if (isReviewed) {
                       if (isRightAnswer) btnStyle = "bg-green-500 border-green-500 text-white shadow-green-100 shadow-lg";
                       else if (isSelected) btnStyle = "bg-rose-500 border-rose-500 text-white shadow-rose-100";
                       else btnStyle = "bg-slate-50 border-transparent text-slate-300";
                    } else if (isSelected) {
                       btnStyle = "bg-indigo-50 border-indigo-600 text-indigo-700 shadow-lg shadow-indigo-50 scale-[1.02]";
                    }

                    return (
                      <button 
                        key={idx} 
                        disabled={isReviewed}
                        onClick={() => handleSelect(i, opt)}
                        className={`group p-5 text-left text-sm rounded-2xl border-2 transition-all flex items-center gap-4 ${btnStyle}`}
                      >
                        <span className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-xs transition-colors shrink-0 ${
                          isReviewed ? 'bg-white/20 border-white/10' : (isSelected ? 'bg-indigo-600 text-white' : 'bg-white border-slate-200 text-slate-400')
                        }`}>
                          {optionChar}
                        </span>
                        <span className="flex-1 font-semibold leading-tight">{opt}</span>
                        {isReviewed && isRightAnswer && <CheckCircle size={20} className="shrink-0" />}
                        {isReviewed && isSelected && !isCorrect && <XCircle size={20} className="shrink-0" />}
                      </button>
                    );
                  })}
                </div>

                {isReviewed && (
                  <div className={`mt-8 p-6 rounded-3xl border animate-slide-up ${isCorrect ? 'bg-green-50 border-green-100' : 'bg-slate-50 border-slate-100'}`}>
                    <div className="flex items-center gap-2 mb-3">
                       <HelpCircle size={16} className={isCorrect ? 'text-green-600' : 'text-indigo-600'} />
                       <span className={`text-[10px] font-black uppercase tracking-widest ${isCorrect ? 'text-green-700' : 'text-indigo-700'}`}>Giải thích chi tiết</span>
                    </div>
                    <p className="text-sm font-bold text-slate-600 leading-relaxed italic">
                      {q.explanation || "AI đang cập nhật giải thích cho câu hỏi này..."}
                    </p>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        <div className="mt-12 space-y-4">
           {!isReviewed && (
             <p className="text-center text-[10px] font-black text-slate-400 uppercase tracking-widest">
               Bạn cần hoàn thành {activeExam.length} câu để nộp bài
             </p>
           )}
           <button 
             onClick={finishExam} 
             disabled={!isReviewed && Object.keys(userAnswers).length < activeExam.length}
             className={`w-full py-6 rounded-3xl font-black shadow-2xl transition-all text-lg flex items-center justify-center gap-3 ${
               isReviewed ? 'bg-slate-900 text-white' : 'bg-indigo-600 text-white disabled:opacity-50'
             }`}
           >
              {isReviewed ? <ArrowLeft size={24}/> : <Rocket size={24}/>}
              {isReviewed ? 'KẾT THÚC REVIEW' : 'NỘP BÀI & CHẤM ĐIỂM'}
           </button>
        </div>
      </div>
    );
  }

  if (!userData.currentMission) {
    return (
      <div className="content-container animate-in space-y-8 px-4 py-6">
        <div className="text-center space-y-2">
          <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center text-white mx-auto shadow-2xl mb-6 rotate-3">
             <GraduationCap size={40} />
          </div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Cấu hình Chiến dịch</h2>
          <p className="text-slate-500 text-sm font-bold opacity-70">Luyện đề SGK mới chuẩn Sở GD 2025</p>
        </div>

        <div className="space-y-6">
          <div className="flex gap-2 p-1.5 bg-slate-100 rounded-[2rem]">
            {['10', '11', '12'].map(g => (
              <button 
                key={g} 
                onClick={() => setGrade(g as Grade)}
                className={`flex-1 py-4 rounded-[1.5rem] font-black text-xs transition-all ${grade === g ? 'bg-white text-indigo-600 shadow-md scale-105' : 'text-slate-400'}`}
              >
                LỚP {g}
              </button>
            ))}
          </div>

          <div className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-4">
            <div className="flex items-center gap-2 mb-2">
               <ListOrdered size={16} className="text-indigo-600"/>
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Số lượng câu hỏi</label>
            </div>
            <div className="grid grid-cols-4 gap-2">
              {[20, 30, 40, 50].map(c => (
                <button 
                  key={c} 
                  onClick={() => setQuestionCount(c)}
                  className={`py-3 rounded-xl text-xs font-black transition-all border-2 ${questionCount === c ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg' : 'bg-slate-50 border-transparent text-slate-500'}`}
                >
                  {c} CÂU
                </button>
              ))}
            </div>
          </div>

          <div className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm">
            <div className="flex items-center gap-2 mb-4">
               <BarChart size={16} className="text-indigo-600"/>
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Môn học trọng tâm</label>
            </div>
            <div className="grid grid-cols-2 gap-2">
              {['Toán học', 'Ngữ văn', 'Tiếng Anh', 'Vật lý', 'Hóa học', 'Sinh học', 'Lịch sử', 'Địa lý'].map(s => (
                <button 
                  key={s} 
                  onClick={() => setSubject(s)}
                  className={`p-4 rounded-2xl text-xs font-bold border-2 transition-all ${subject === s ? 'bg-indigo-50 border-indigo-500 text-indigo-700 shadow-sm' : 'bg-slate-50 border-transparent text-slate-500 hover:bg-white hover:border-slate-100'}`}
                >
                  {s}
                </button>
              ))}
            </div>
          </div>

          <button 
            onClick={startMission} 
            disabled={loading}
            className="w-full py-6 bg-slate-900 text-white rounded-3xl font-black shadow-2xl flex items-center justify-center gap-3 disabled:opacity-50 active:scale-95 transition-all text-lg"
          >
            {loading ? <Loader2 className="animate-spin" /> : <Rocket size={24}/>}
            {loading ? 'ĐANG TỔNG HỢP...' : 'KÍCH HOẠT LỘ TRÌNH'}
          </button>
        </div>
      </div>
    );
  }

  const mission = userData.currentMission;

  return (
    <div className="content-container animate-in space-y-8 px-4 py-2 pb-40">
       <div className="bg-gradient-to-br from-indigo-700 via-indigo-600 to-purple-800 p-8 rounded-[3rem] text-white shadow-2xl relative overflow-hidden group">
          <div className="relative z-10">
             <div className="flex gap-2 mb-4">
                <span className="bg-white/20 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest border border-white/10 backdrop-blur-md">LỚP {mission.grade}</span>
                <span className="bg-white/20 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest border border-white/10 backdrop-blur-md">{mission.subject}</span>
             </div>
             <h3 className="text-3xl font-black tracking-tight leading-none mb-2">Lộ trình 2025</h3>
             <p className="text-indigo-100 text-[11px] font-bold uppercase tracking-[0.2em] opacity-80">Mọi chương mục đều đã sẵn sàng</p>
          </div>
          <Zap size={100} className="absolute right-[-20px] bottom-[-20px] text-white/10 group-hover:scale-125 transition-transform duration-700" />
       </div>

       <div className="space-y-4">
          {mission.roadmap.map((node, i) => {
             const isLoadingThis = loadingNodeId === node.id;

             return (
                <button 
                  key={node.id} 
                  disabled={loadingNodeId !== null}
                  onClick={() => loadExam(node.id, node.difficulty)}
                  className={`w-full text-left clean-card p-6 rounded-[2.5rem] flex items-center gap-6 border-2 transition-all relative overflow-hidden hover:border-indigo-300 hover:bg-indigo-50/10 shadow-lg group`}
                >
                   <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-white font-black shrink-0 shadow-xl transition-all bg-indigo-600 group-hover:scale-110 group-hover:rotate-3`}>
                      {isLoadingThis ? <Loader2 className="animate-spin" size={24}/> : i + 1}
                   </div>
                   <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1.5">
                         <span className="text-[9px] font-black px-2.5 py-1 rounded-full uppercase tracking-widest bg-slate-900 text-white">
                            {node.difficulty === 'theory' ? 'Kiến thức nền' : node.difficulty === 'practice' ? 'Luyện tập' : 'Vận dụng cao'}
                         </span>
                      </div>
                      <h5 className="font-black text-lg truncate tracking-tight text-slate-800">
                        {node.title}
                      </h5>
                   </div>
                   {!isLoadingThis && <ChevronRight size={24} className="text-indigo-600 opacity-30 group-hover:opacity-100 transition-opacity" />}
                </button>
             );
          })}
       </div>

       <div className="p-8 bg-slate-50 rounded-[3rem] border border-slate-100 text-center space-y-4">
          <Info size={32} className="mx-auto text-slate-300" />
          <p className="text-sm font-bold text-slate-500 italic leading-relaxed">
            "Số câu hỏi đã được thiết lập là {questionCount} câu. Điểm EXP sẽ được tính dựa trên số câu trả lời đúng thực tế."
          </p>
          <button onClick={() => onUpdate({...userData, currentMission: undefined})} className="text-indigo-600 font-black text-[10px] uppercase tracking-[0.3em] pt-4">
             Đổi cấu hình bài thi
          </button>
       </div>
    </div>
  );
};

