              {tools.find(t => t.id === activeTool)?.name}
              {activeTool === 'exam_bank' && <span className="bg-indigo-100 text-indigo-600 px-3 py-1 rounded-full text-[10px] animate-pulse">LIVE SEARCH</span>}
            </h3>

