                         <div className="mt-4 pt-4 border-t border-slate-100">
                             <p className="text-xs text-indigo-600 font-bold italic">Đáp án: {q.answer}</p>
                         </div>
                      </div>
                    ))}
                 </div>
               )}

               {activeTool === 'summary' && typeof result === 'string' && (
                 <div className="p-6 bg-white/50 rounded-3xl border border-indigo-100 italic font-bold text-slate-700 leading-relaxed">
                    {result}
                 </div>
               )}
            </div>
          )}
        </div>
      ) : (
        <>
          <div className="text-center py-6">
            <h2 className="text-4xl font-black text-slate-800 tracking-tighter mb-2">SUPREME TOOLS</h2>
            <p className="text-slate-400 font-black text-[10px] uppercase tracking-[0.4em]">Kho tri thức Sở GD chính thức</p>
          </div>
          <div className="grid grid-cols-1 gap-4">
            {tools.map(tool => (
              <button key={tool.id} onClick={() => setActiveTool(tool.id)} className="glass p-7 rounded-[3rem] border-white shadow-sm hover:shadow-2xl hover:translate-y-[-4px] transition-all flex items-center gap-6 group text-left border-2 bg-white/60">
                <div className={`w-16 h-16 ${tool.color} text-white rounded-[1.8rem] flex items-center justify-center shadow-lg group-hover:rotate-12 transition-transform`}>
                  <tool.icon size={32} />
                </div>
                <div className="flex-1">
                  <h3 className="font-black text-slate-800 text-lg mb-1">{tool.name}</h3>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">{tool.desc}</p>
                </div>
                <ChevronRight size={24} className="text-slate-200 group-hover:text-indigo-600" />
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
};

export default StudyTools;

import React, { useState, useEffect, memo } from 'react';
import { 
  Plus, Heart, Sparkles, MessageSquare, X, Send, 
  ShieldCheck, Share2
} from 'lucide-react';
import { Post, UserProfile, PostType } from '../types';
import { checkVibePost, suggestHashtags } from '../services/geminiService';
import MarkdownText from './MarkdownText';

const Feed: React.FC<{ userData: UserProfile; onExp: (n: number) => void }> = ({ userData, onExp }) => {
  const [posts, setPosts] = useState<Post[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<PostType | 'all'>('all');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  useEffect(() => {
    try {
      const saved = localStorage.getItem('studygram_posts');
      if (saved) {
        const parsed = JSON.parse(saved);
        const validatedPosts = parsed.map((p: any) => ({
          ...p,
          likes: Array.isArray(p.likes) ? p.likes : [],
          comments: Array.isArray(p.comments) ? p.comments : [],
          hashtags: Array.isArray(p.hashtags) ? p.hashtags : [],
          aiAnalysis: p.aiAnalysis || ''
        }));
        setPosts(validatedPosts);
      } else {
        const initial = [{
          id: 'p1', uid: 'admin', userName: 'Hệ thống StudyGram 🛡️', avatar: 'https://api.dicebear.com/7.x/notionists/svg?seed=Admin',
          content: 'Chào mừng các học giả tới phiên bản **StudyGram V6 Holographic**! Hãy chia sẻ kiến thức để nhận EXP nhé. Chúc bạn có một hành trình học tập tuyệt vời! 🔥', category: 'Thông báo', type: 'event' as PostType, mood: '🔥', createdAt: Date.now(), likes: [], comments: [], isPinned: true, aiAnalysis: 'Vibe cực cháy cho khởi đầu mới!'
        }];
        setPosts(initial);
        localStorage.setItem('studygram_posts', JSON.stringify(initial));
      }
    } catch (e) {
      console.error("Error loading posts:", e);
      setPosts([]);
    }
  }, []);

  const filteredPosts = posts.filter(p => activeTab === 'all' || p.type === activeTab);

  const handleAddPost = async (data: Partial<Post>) => {
    setIsAnalyzing(true);
    try {
      const hashtags = await suggestHashtags(data.content!);
      const vibeData = await checkVibePost(data.content!);

      const newPost: Post = {
        id: Date.now().toString(), uid: userData.uid, userName: userData.name, avatar: userData.avatar,
        content: data.content!, category: data.category!, type: data.type || 'knowledge', mood: data.mood || '📚',
        createdAt: Date.now(), likes: [], comments: [], hashtags, aiAnalysis: vibeData.comment
      };

      const updated = [newPost, ...posts];
      setPosts(updated);
      localStorage.setItem('studygram_posts', JSON.stringify(updated));
      onExp(25);
      setIsModalOpen(false);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleLike = (id: string) => {
    const updated = posts.map(p => p.id === id ? { ...p, likes: p.likes.includes(userData.uid) ? p.likes.filter(u => u !== userData.uid) : [...p.likes, userData.uid] } : p);
    setPosts(updated); 
    localStorage.setItem('studygram_posts', JSON.stringify(updated));
  };

  const handleComment = (id: string, text: string) => {
    if (!text.trim()) return;
    const updated = posts.map(p => p.id === id ? { ...p, comments: [...p.comments, { id: Date.now().toString(), userName: userData.name, avatar: userData.avatar, content: text, createdAt: Date.now(), isAuthor: true }] } : p);
    setPosts(updated); 
    localStorage.setItem('studygram_posts', JSON.stringify(updated));
    onExp(5);
  };

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] animate-slide-up max-w-2xl mx-auto w-full">
      {/* Sticky Header Section */}
      <div className="space-y-6 pb-6 px-1">
        {/* Create Post Trigger */}
        <div className="glass p-6 rounded-[3rem] shadow-xl flex items-center gap-6 cursor-pointer hover:shadow-2xl hover:translate-y-[-2px] transition-all border-white bg-white/40 group transform-gpu" onClick={() => setIsModalOpen(true)}>
          <div className="relative shrink-0">
            <img src={userData.avatar} className="w-14 h-14 rounded-[1.5rem] border-2 border-white shadow-xl group-hover:rotate-6 transition-transform" />
            <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 border-2 border-white rounded-full"></div>
          </div>
          <div className="flex-1 text-slate-400 font-bold text-lg tracking-tight">Chia sẻ tri thức mới...</div>
          <div className="w-12 h-12 bg-indigo-600 text-white rounded-[1.2rem] flex items-center justify-center shadow-xl shadow-indigo-100 group-hover:scale-110 transition-transform"><Plus size={24} strokeWidth={3}/></div>
        </div>

        {/* Filters */}
        <div className="flex gap-2 p-1.5 bg-white/40 backdrop-blur-xl rounded-full w-full overflow-x-auto no-scrollbar border border-white/50 shadow-sm transform-gpu">
          {['all', 'knowledge', 'meme', 'event'].map(t => (
            <button 
              key={t} 
              onClick={() => setActiveTab(t as any)} 
              className={`flex-1 px-4 py-3 rounded-full text-[10px] font-black uppercase tracking-[0.2em] transition-all duration-300 whitespace-nowrap ${activeTab === t ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-800 hover:bg-white/50'}`}
            >
              {t === 'all' ? 'Tất cả' : t}
            </button>
          ))}
        </div>
      </div>

      {/* Standard Scrollable List */}
      <div className="flex-1 overflow-y-auto no-scrollbar pb-32 space-y-8 px-1">
        {filteredPosts.map((post) => (
          <div key={post.id} className="transform-gpu">
             <PostCard 
                post={post} 
                userData={userData} 
                onLike={() => handleLike(post.id)} 
                onComment={(t: string) => handleComment(post.id, t)} 
              />
          </div>
        ))}
        {filteredPosts.length === 0 && (
          <div className="text-center py-20 opacity-50 font-bold">Chưa có bài viết nào...</div>
        )}
      </div>

      {isModalOpen && (
        <CreatePostModal onClose={() => setIsModalOpen(false)} onSubmit={handleAddPost} userData={userData} isAnalyzing={isAnalyzing} />
      )}
    </div>
  );
};

// Use memo to prevent re-renders of list items when parent state (like modal) changes
const PostCard = memo(({ post, userData, onLike, onComment }: any) => {
  const [showComments, setShowComments] = useState(false);
  const [input, setInput] = useState('');
  const [justShared, setJustShared] = useState(false);

  const likes = post.likes || [];
  const comments = post.comments || [];
  const hasLiked = likes.includes(userData.uid);

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const shareText = `${post.userName} trên StudyGram:\n\n${post.content}\n\n#StudyGram #V7`;

    if (navigator.share) {
      try {
        await navigator.share({
          title: `Bài viết của ${post.userName}`,
          text: shareText,
          url: window.location.href
        });
      } catch (err) {
        console.log('User cancelled share');
      }
    } else {
      try {
        await navigator.clipboard.writeText(shareText);
        setJustShared(true);
        setTimeout(() => setJustShared(false), 2000);
      } catch (err) {
        console.error('Copy failed');
      }
    }
  };

  return (
    // OPTIMIZATION: Removed 'glass' and 'bg-white/60' (transparent) and used 'bg-white' (solid).
    // Solid backgrounds scroll MUCH faster than blurred/transparent ones.
    <div className="bg-white rounded-[3.8rem] p-8 md:p-12 border border-slate-100 shadow-xl relative overflow-hidden group transition-all duration-300 hover:shadow-2xl">
      <div className="flex gap-5 mb-8">
        <div className="relative shrink-0">
          <img src={post.avatar} className="w-16 h-16 rounded-[2rem] border-2 border-white shadow-2xl transition-transform duration-500 group-hover:scale-105" loading="lazy" />
          <div className="absolute -bottom-2 -right-2 bg-white w-9 h-9 rounded-2xl flex items-center justify-center text-xl shadow-xl border border-slate-50">{post.mood}</div>
        </div>
        <div className="flex flex-col justify-center min-w-0">
          <h4 className="font-black text-slate-800 text-lg flex items-center gap-2 tracking-tighter leading-none truncate">
            {post.userName} 
            {post.type === 'event' && <ShieldCheck size={18} className="text-amber-500 shrink-0" fill="currentColor"/>}
          </h4>
          <div className="flex items-center gap-2 mt-2">
            <span className="text-[9px] px-2.5 py-1 rounded-full font-black uppercase tracking-widest bg-indigo-50 text-indigo-600 border border-indigo-100 shadow-sm shrink-0">#{post.category}</span>
            <span className="text-[9px] text-slate-400 font-bold uppercase tracking-widest truncate">{new Date(post.createdAt).toLocaleDateString('vi-VN')}</span>
          </div>
        </div>
      </div>

      <div className="text-xl leading-[1.5] mb-8 font-bold text-slate-700 whitespace-pre-wrap tracking-tight">
        <MarkdownText text={post.content} />
      </div>

      {post.aiAnalysis && (
        <div className="p-6 bg-indigo-50/50 rounded-[2.5rem] mb-8 border border-white/50 flex gap-5 items-start">
           <div className="w-10 h-10 bg-white rounded-[1rem] flex items-center justify-center text-indigo-600 shadow-md shrink-0"><Sparkles size={20} strokeWidth={2.5}/></div>
           <div className="text-sm font-bold text-indigo-900 italic leading-relaxed pt-0.5 flex-1">
             <span className="block text-[9px] uppercase tracking-[0.3em] text-indigo-400 not-italic mb-1 font-black">AI Vibe Insight:</span>
             <MarkdownText text={post.aiAnalysis} />
           </div>
        </div>
      )}

      <div className="flex items-center gap-8 pt-6 border-t border-slate-50">
        <button onClick={(e) => { e.stopPropagation(); onLike(); }} className={`flex items-center gap-2 text-sm font-black transition-all duration-300 ${hasLiked ? 'text-rose-500 scale-110' : 'text-slate-400 hover:text-rose-500'}`}>
          <Heart size={24} fill={hasLiked ? 'currentColor' : 'none'} strokeWidth={hasLiked ? 0 : 2.5} /> 
          <span className="mt-0.5">{likes.length}</span>
        </button>
        <button onClick={(e) => { e.stopPropagation(); setShowComments(!showComments); }} className={`flex items-center gap-2 text-sm font-black transition-all duration-300 ${showComments ? 'text-indigo-600' : 'text-slate-400 hover:text-indigo-600'}`}>
          <MessageSquare size={24} strokeWidth={2.5} /> 
          <span className="mt-0.5">{comments.length}</span>
        </button>
        <button onClick={handleShare} className={`flex items-center gap-2 text-sm font-black transition-all duration-300 ${justShared ? 'text-green-500' : 'text-slate-400 hover:text-cyan-500'}`}>
          <Share2 size={24} strokeWidth={2.5} /> 
          <span className="mt-0.5">{justShared ? 'Đã sao chép!' : 'Chia sẻ'}</span>
        </button>
      </div>

      {showComments && (
        <div className="mt-8 space-y-6" onClick={e => e.stopPropagation()}>
          <div className="bg-slate-50 p-6 rounded-[2.5rem] border border-slate-100 space-y-4 max-h-[300px] overflow-y-auto shadow-inner custom-scrollbar">
            {comments.map((c: any) => (
