             <h1 className="text-2xl font-black text-rose-500 mb-4">Ối! Đã xảy ra lỗi 😵</h1>
             <p className="text-slate-500 mb-6 font-bold">Ứng dụng gặp sự cố. Vui lòng tải lại trang.</p>
             <div className="bg-slate-100 p-4 rounded-xl text-left text-xs font-mono text-slate-600 overflow-auto max-h-40 mb-6">
                {this.state.error?.toString()}
