             <button onClick={() => window.location.reload()} className="w-full py-4 bg-indigo-600 text-white rounded-xl font-black shadow-lg hover:bg-indigo-700">TẢI LẠI TRANG</button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

