import { GoogleGenAI, Type } from "@google/genai";

const FLASH_MODEL = 'gemini-3-flash-preview';

// Safe access to API Key
const getAPIKey = () => {
  try {
    if (typeof process !== 'undefined' && process.env && process.env.API_KEY) {
      return process.env.API_KEY;
    }
  } catch (e) {
    console.warn("Could not access process.env");
  }
  return '';
};

const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: getAPIKey() });
};

// --- UTILITY: ROBUST JSON PARSER ---
// Hàm này cực kỳ quan trọng để sửa lỗi "Load mãi không ra"
// Nó sẽ lọc bỏ các ký tự thừa như ```json, ``` và tìm đúng đoạn JSON hợp lệ
const parseGeminiJSON = (text: string, defaultValue: any) => {
  try {
    if (!text) return defaultValue;
    // 1. Loại bỏ markdown code block
    let cleaned = text.replace(/```json/g, '').replace(/```/g, '').trim();

    // 2. Tìm điểm bắt đầu và kết thúc của JSON (Object {} hoặc Array [])
    const firstBrace = cleaned.indexOf('{');
    const firstBracket = cleaned.indexOf('[');

    let startIdx = -1;
    let endIdx = -1;

    // Xác định xem nó là Array hay Object dựa vào cái nào xuất hiện trước
    if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
      startIdx = firstBrace;
      endIdx = cleaned.lastIndexOf('}');
    } else if (firstBracket !== -1) {
      startIdx = firstBracket;
      endIdx = cleaned.lastIndexOf(']');
    }

    if (startIdx !== -1 && endIdx !== -1) {
      cleaned = cleaned.substring(startIdx, endIdx + 1);
      return JSON.parse(cleaned);
    }

    // Fallback: thử parse trực tiếp
    return JSON.parse(text);
  } catch (e) {
    console.error("JSON Parse Error:", e, "Raw Text:", text);
    return defaultValue;
  }
};

