export const generateExamRoadmap = async (grade: string, subject: string): Promise<any> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: `Tạo lộ trình 5 chương ôn tập môn ${subject} lớp ${grade}. 
      Output JSON ONLY: {roadmap: [{id: string, title: string, difficulty: 'theory'|'practice'|'hardcore', topics: string[]}]}`,
      config: {
        responseMimeType: "application/json"
      }
    });
    return parseGeminiJSON(response.text, { roadmap: [] });
  } catch (e) {
    return { roadmap: [] };
  }
};

export const generateExamPaper = async (subject: string, grade: string, difficulty: string, count: number = 20): Promise<any[]> => {
  const ai = getAIInstance();
  try {
    // Tối ưu prompt để gen nhanh hơn: Yêu cầu explanation ngắn gọn
    const prompt = `Tạo ${count} câu trắc nghiệm ${subject} lớp ${grade}, độ khó ${difficulty}.
    Output JSON Array ONLY: [{question: string, options: [string] (4 lựa chọn), answer: string (chỉ ghi nội dung đúng), explanation: string (ngắn gọn < 20 từ)}]`;

    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: prompt,
      config: {
        responseMimeType: "application/json"
      }
    });

    const data = parseGeminiJSON(response.text, []);
    return Array.isArray(data) ? data : [];
  } catch (e) {
    console.error("Gemini Error:", e);
    return [];
  }
};

