import React, { ReactNode } from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: any;
}

class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  state: ErrorBoundaryState = {
    hasError: false,
    error: null
  };

  static getDerivedStateFromError(error: any) {
    return { hasError: true, error };
  }

  componentDidCatch(error: any, errorInfo: any) {
    console.error("Uncaught error:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen flex items-center justify-center bg-slate-50 p-6 font-sans">
          <div className="bg-white p-8 rounded-[2rem] shadow-xl max-w-md w-full text-center border border-slate-100">
             <div className="w-16 h-16 bg-rose-100 text-rose-500 rounded-full flex items-center justify-center mx-auto mb-4 text-2xl">😵</div>
             <h1 className="text-xl font-black text-slate-800 mb-2">Ối! Có chút trục trặc</h1>
             <p className="text-slate-500 mb-6 text-sm font-medium">Hệ thống gặp sự cố nhỏ. Đừng lo, chỉ cần tải lại thôi.</p>
             <div className="bg-slate-50 p-4 rounded-xl text-left text-[10px] font-mono text-slate-400 overflow-auto max-h-32 mb-6 border border-slate-100">
                {this.state.error?.toString() || "Unknown Error"}
             </div>
             <button onClick={() => window.location.reload()} className="w-full py-4 bg-indigo-600 text-white rounded-xl font-black shadow-lg hover:bg-indigo-700 transition-all active:scale-95 text-xs uppercase tracking-widest">TẢI LẠI TRANG</button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <ErrorBoundary>
      <App />
    </ErrorBoundary>
  </React.StrictMode>
);

import { GoogleGenAI, Type } from "@google/genai";

const FLASH_MODEL = 'gemini-3-flash-preview';

// Safe access to API Key
const getAPIKey = () => {
  try {
    if (typeof process !== 'undefined' && process.env && process.env.API_KEY) {
      return process.env.API_KEY;
    }
  } catch (e) {
    console.warn("Could not access process.env");
  }
  return '';
};

const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: getAPIKey() });
};

// --- UTILITY: ROBUST JSON PARSER (FIXED & OPTIMIZED) ---
const parseGeminiJSON = (text: string, defaultValue: any) => {
  try {
    if (!text) return defaultValue;

    // 1. Clean markdown and "json" label
    let cleaned = text.replace(/```json/gi, '').replace(/```/g, '').trim();

    // 2. Locate JSON bounds
    const firstBrace = cleaned.indexOf('{');
    const firstBracket = cleaned.indexOf('[');

    let startIdx = -1;
    let endIdx = -1;

    // Detect if Object or Array appears first
    if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
      startIdx = firstBrace;
      endIdx = cleaned.lastIndexOf('}');
    } else if (firstBracket !== -1) {
      startIdx = firstBracket;
      endIdx = cleaned.lastIndexOf(']');
    }

    if (startIdx !== -1 && endIdx !== -1) {
      cleaned = cleaned.substring(startIdx, endIdx + 1);
      // Attempt parse
      return JSON.parse(cleaned);
    }

    // Fallback: Try strict parsing of original
    return JSON.parse(text);
  } catch (e) {
    console.error("JSON Parse Fail:", e);
    // Silent fail to default value to prevent app crash
    return defaultValue;
  }
};

// --- OPTIMIZED PROMPTS FOR SPEED ---
// Using strict JSON schemas and short prompts reduces token usage significantly

export const generateExamRoadmap = async (grade: string, subject: string): Promise<any> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: `Create a 5-step study roadmap for Grade ${grade} Subject ${subject} (Vietnam GDPT 2018).
      Response format JSON ONLY:
      {
        "roadmap": [
          {"id": "1", "title": "Chapter Name", "difficulty": "theory", "topics": ["topic1", "topic2"]}
        ]
      }`,
      config: { responseMimeType: "application/json" }
    });
    return parseGeminiJSON(response.text, { roadmap: [] });
  } catch (e) {
    return { roadmap: [] };
  }
};

export const generateExamPaper = async (subject: string, grade: string, difficulty: string, count: number = 10): Promise<any[]> => {
  const ai = getAIInstance();
  try {
    // Prompt optimized for token speed: "No preamble", "Short explanations"
    const prompt = `Create ${count} multiple-choice questions for Grade ${grade} ${subject}, difficulty: ${difficulty} (SGK 2018).
    Return JSON Array ONLY. No markdown.
    Format: [{"question": "...", "options": ["A", "B", "C", "D"], "answer": "Correct Answer Content", "explanation": "Short reason (<15 words)"}]`;

    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: prompt,
      config: { responseMimeType: "application/json" }
    });

    const data = parseGeminiJSON(response.text, []);
    return Array.isArray(data) ? data : [];
  } catch (e) {
    console.error("Gen Exam Error:", e);
    return [];
  }
};

export const getTutorResponse = async (msg: string) => {
  const ai = getAIInstance();
  try {
    const res = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: msg,
      config: { systemInstruction: "Bạn là gia sư vui tính. Trả lời cực ngắn gọn, súc tích (dưới 50 từ) trừ khi được hỏi chi tiết." }
    });
    return res.text || "AI đang bận, thử lại sau nhé!";
  } catch (e) {
    return "Mạng lag quá, fen hỏi lại đi.";
  }
};

export const analyzeStudyImage = async (base64Image: string, prompt: string) => {
  const ai = getAIInstance();
  try {
    const res = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: {
        parts: [
          { inlineData: { data: base64Image.split(',')[1], mimeType: 'image/jpeg' } },
          { text: prompt + " (Trả lời ngắn gọn)" }
        ]
      }
    });
    return res.text || "Không phân tích được ảnh.";
  } catch (e) {
    return "Lỗi xử lý ảnh.";
  }
};

