const MarkdownText = memo(({ text }: { text: string }) => {
  const lines = text.split('\n');
  return (
    <div className="leading-relaxed">
      {lines.map((line, i) => {
        let content: any = line;
        if (line.startsWith('### ')) content = <h3 className="text-lg font-black text-indigo-600 mt-2">{line.replace('### ', '')}</h3>;
        else if (line.startsWith('- ')) content = <div className="flex gap-2 ml-2"><div className="w-1.5 h-1.5 bg-indigo-400 rounded-full mt-2"></div>{line.substring(2)}</div>;
        else {
           const parts = line.split(/(\*\*.*?\*\*)/g);
           content = parts.map((p, idx) => p.startsWith('**') ? <strong key={idx} className="text-indigo-700">{p.slice(2,-2)}</strong> : p);
        }
        return <div key={i} className="mb-1">{content}</div>;
      })}
    </div>
  );
});

