interface ErrorBoundaryProps { children?: ReactNode; }
interface ErrorBoundaryState { hasError: boolean; error: any; }

class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) { super(props); this.state = { hasError: false, error: null }; }
  static getDerivedStateFromError(error: any) { return { hasError: true, error }; }
  render() {
    if (this.state.hasError) return (
      <div className="h-screen flex items-center justify-center p-6 text-center">
        <div className="max-w-md">
          <div className="text-6xl mb-4">😵</div>
          <h1 className="text-2xl font-black mb-2">Hệ thống quá tải!</h1>
          <p className="text-slate-500 mb-6 text-sm">{this.state.error?.toString()}</p>
          <button onClick={() => window.location.reload()} className="px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black">TẢI LẠI</button>
        </div>
      </div>
    );
    return this.props.children;
  }
}

