import React, { useState, useEffect, useRef } from 'react';
import { Bot, Send, Trash2, Camera, X, Zap, FastForward, UserCheck, GraduationCap, Sparkles, AlertCircle } from 'lucide-react';
import { Message, UserProfile } from '../types';
import { getTutorResponse, analyzeStudyImage } from '../services/geminiService';
import MarkdownText from './MarkdownText';

const AITutor: React.FC<{ userData: UserProfile; onExp: (amount: number) => void }> = ({ userData, onExp }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [tutorMode, setTutorMode] = useState<'teen' | 'academic'>('teen');
  const [isFastMode, setIsFastMode] = useState(true);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isTyping]);

  const handleSend = async () => {
    if ((!input.trim() && !selectedImage) || isTyping) return;

    const userText = input.trim();
    const imageToProcess = selectedImage;
    setInput('');
    setSelectedImage(null);

    setMessages(prev => [...prev, { role: 'user', text: imageToProcess ? `[Gửi ảnh] ${userText}` : userText, timestamp: Date.now() }]);
    setIsTyping(true);

    try {
      const promptSuffix = isFastMode ? " (Trả lời cực ngắn gọn)" : "";
      const replyText = imageToProcess 
        ? await analyzeStudyImage(imageToProcess, (userText || "Giải thích ảnh này") + promptSuffix)
        : await getTutorResponse(userText + promptSuffix, tutorMode);
      setMessages(prev => [...prev, { role: 'ai', text: replyText, timestamp: Date.now() }]);
      onExp(15);
    } catch (e) {
      setMessages(prev => [...prev, { role: 'ai', text: "Lỗi kết nối AI rồi fen!", timestamp: Date.now() }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#F4F7FF]/30 relative overflow-hidden">
      {/* Header Nâng Cấp */}
      <div className="bg-white/95 backdrop-blur-xl p-4 border-b flex flex-col gap-3 shadow-sm z-10 sticky top-0">
        <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg"><Bot size={22} /></div>
              <div>
                <h3 className="font-black text-slate-800 text-sm tracking-tight">AI Tutor Supreme</h3>
                <div className="flex items-center gap-1.5">
                    <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></span>
                    <span className="text-[8px] text-slate-400 font-bold uppercase tracking-widest">Sẵn sàng hỗ trợ</span>
                </div>
              </div>
            </div>
            <button onClick={() => setMessages([])} className="p-2 text-slate-300 hover:text-rose-500 transition-colors"><Trash2 size={20} /></button>
        </div>

        {/* Mode Selector */}
        <div className="flex gap-2">
            <button 
                onClick={() => setTutorMode('teen')}
                className={`flex-1 py-2 px-3 rounded-xl text-[9px] font-black uppercase tracking-widest flex items-center justify-center gap-2 transition-all border-2 ${
                    tutorMode === 'teen' ? 'bg-indigo-600 border-indigo-600 text-white shadow-md' : 'bg-white border-slate-100 text-slate-400 hover:border-indigo-100'
                }`}
            >
                <Sparkles size={12} /> Teen Mode
            </button>
            <button 
                onClick={() => setTutorMode('academic')}
                className={`flex-1 py-2 px-3 rounded-xl text-[9px] font-black uppercase tracking-widest flex items-center justify-center gap-2 transition-all border-2 ${
                    tutorMode === 'academic' ? 'bg-slate-800 border-slate-800 text-white shadow-md' : 'bg-white border-slate-100 text-slate-400 hover:border-slate-200'
                }`}
            >
                <GraduationCap size={12} /> Academic
            </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-6 no-scrollbar pb-32">
        {messages.length === 0 && (
            <div className="text-center py-10 opacity-40">
                <AlertCircle size={40} className="mx-auto mb-3" />
                <p className="text-xs font-black uppercase tracking-widest">Hỏi gì đi fen, tui đang rảnh...</p>
            </div>
        )}
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-5 rounded-[2rem] text-sm leading-relaxed shadow-sm font-bold ${
              m.role === 'user' ? 'bg-indigo-600 text-white rounded-tr-none' : 'bg-white text-slate-700 rounded-tl-none border-b-2 border-slate-100'
            }`}>
              {m.role === 'ai' ? <MarkdownText text={m.text} /> : m.text}
            </div>
          </div>
        ))}
        {isTyping && (
            <div className="flex justify-start">
                <div className="bg-white p-4 rounded-full shadow-sm flex gap-1.5 animate-pulse">
                    <div className="w-1.5 h-1.5 bg-indigo-300 rounded-full"></div>
                    <div className="w-1.5 h-1.5 bg-indigo-300 rounded-full"></div>
                    <div className="w-1.5 h-1.5 bg-indigo-300 rounded-full"></div>
                </div>
            </div>
        )}
        <div ref={chatEndRef} />
      </div>

      {/* Input Section */}
      <div className="p-4 bg-white/95 border-t backdrop-blur-xl sticky bottom-0 z-20">
        {selectedImage && (
          <div className="mb-3 relative inline-block animate-slide-up">
            <img src={selectedImage} className="w-16 h-16 rounded-xl border-2 border-white shadow-lg object-cover"/>
            <button onClick={() => setSelectedImage(null)} className="absolute -top-1.5 -right-1.5 bg-rose-500 text-white p-1 rounded-full shadow-md"><X size={10}/></button>
          </div>
        )}
        <div className="flex items-center gap-2 bg-slate-50 p-1.5 rounded-[2rem] border-2 border-slate-100 focus-within:bg-white focus-within:border-indigo-400 transition-all shadow-inner">
          <button onClick={() => fileInputRef.current?.click()} className="p-3 text-slate-400 hover:text-indigo-600 transition-colors"><Camera size={20}/></button>
          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={e => {
            const file = e.target.files?.[0];
            if(file) { const reader = new FileReader(); reader.onloadend = () => setSelectedImage(reader.result as string); reader.readAsDataURL(file); }
          }}/>
          <input 
            value={input} 
            onChange={e => setInput(e.target.value)} 
            onKeyDown={e => e.key === 'Enter' && handleSend()} 
            placeholder={tutorMode === 'teen' ? "Hỏi gì lẹ đi fen..." : "Vấn đề của bạn là gì?"} 
            className="flex-1 bg-transparent px-2 py-2.5 outline-none font-bold text-sm"
          />
          <button 
            onClick={handleSend} 
            disabled={(!input.trim() && !selectedImage) || isTyping} 
            className="w-10 h-10 bg-indigo-600 text-white rounded-2xl shadow-lg flex items-center justify-center active:scale-90 transition-all disabled:opacity-30"
          >
            <Send size={18}/>
          </button>
        </div>
      </div>
    </div>
  );
};

export default AITutor;

import React, { useState, useEffect, useCallback, memo } from 'react';
import { Plus, Heart, Sparkles, MessageSquare, X, Send, ShieldCheck, Share2 } from 'lucide-react';
import { Post, UserProfile, PostType } from '../types';
import { checkVibePost, suggestHashtags } from '../services/geminiService';
import MarkdownText from './MarkdownText';

const Feed: React.FC<{ userData: UserProfile; onExp: (n: number) => void }> = ({ userData, onExp }) => {
  const [posts, setPosts] = useState<Post[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<PostType | 'all'>('all');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('studygram_posts');
    if (saved) {
      setPosts(JSON.parse(saved));
    } else {
      setPosts([{
        id: 'p1', uid: 'admin', userName: 'Hệ thống StudyGram 🛡️', avatar: 'https://api.dicebear.com/7.x/notionists/svg?seed=Admin',
        content: 'Chào mừng các học giả tới **StudyGram V7 Supreme**! 🚀\n\nĐã tích hợp Gia sư đa chế độ và fix sạch lỗi cũ. Cùng học thôi!', category: 'Hệ thống', type: 'event', mood: '🚀', createdAt: Date.now(), likes: [], comments: [], isPinned: true, aiAnalysis: 'Hệ thống đang hoạt động với hiệu suất tối đa!'
      }]);
    }
  }, []);

  const handleAddPost = async (content: string) => {
    setIsAnalyzing(true);
    try {
      const vibe = await checkVibePost(content);
      const hashtags = await suggestHashtags(content);
      const newPost: Post = {
        id: Date.now().toString(), uid: userData.uid, userName: userData.name, avatar: userData.avatar,
        content, category: 'Kiến thức', type: 'knowledge', mood: '📚',
        createdAt: Date.now(), likes: [], comments: [], hashtags, aiAnalysis: vibe.comment
      };
      const updated = [newPost, ...posts];
      setPosts(updated);
      localStorage.setItem('studygram_posts', JSON.stringify(updated));
      onExp(25);
      setIsModalOpen(false);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleLike = useCallback((id: string) => {
    setPosts(prev => {
        const updated = prev.map(p => p.id === id ? { ...p, likes: p.likes.includes(userData.uid) ? p.likes.filter(u => u !== userData.uid) : [...p.likes, userData.uid] } : p);
        localStorage.setItem('studygram_posts', JSON.stringify(updated));
        return updated;
    });
  }, [userData.uid]);

  const handleComment = useCallback((id: string, text: string) => {
    setPosts(prev => {
        const updated = prev.map(p => p.id === id ? { ...p, comments: [...p.comments, { id: Date.now().toString(), userName: userData.name, avatar: userData.avatar, content: text, createdAt: Date.now() }] } : p);
        localStorage.setItem('studygram_posts', JSON.stringify(updated));
        return updated;
    });
  }, [userData]);

  const filteredPosts = posts.filter(p => activeTab === 'all' || p.type === activeTab);

  return (
    <div className="space-y-6 animate-slide-up max-w-2xl mx-auto pb-40 px-1">
      <div className="bg-white p-6 rounded-[3rem] shadow-sm flex items-center gap-4 cursor-pointer hover:shadow-md transition-all border border-slate-100" onClick={() => setIsModalOpen(true)}>
        <img src={userData.avatar} className="w-12 h-12 rounded-2xl border-2 border-white shadow-sm" />
        <span className="text-slate-400 font-bold">Hôm nay fen học được gì hay?...</span>
      </div>

      <div className="flex gap-2 p-1.5 bg-white/60 backdrop-blur-md rounded-full w-fit border border-white/50 shadow-sm">
        {['all', 'knowledge', 'meme', 'event'].map(t => (
          <button key={t} onClick={() => setActiveTab(t as any)} className={`px-4 py-2 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === t ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}>{t === 'all' ? 'Feed' : t}</button>
        ))}
      </div>

      <div className="space-y-6">
        {filteredPosts.map(post => (
          <PostCard key={post.id} post={post} userData={userData} onLike={handleLike} onComment={handleComment} />
        ))}
      </div>

      {isModalOpen && <CreatePostModal onClose={() => setIsModalOpen(false)} onSubmit={handleAddPost} isAnalyzing={isAnalyzing} />}
    </div>
  );
};

const PostCard = memo(({ post, userData, onLike, onComment }: any) => {
    const [commenting, setCommenting] = useState(false);
    const [txt, setTxt] = useState('');
    const hasLiked = post.likes.includes(userData.uid);

    return (
        <div className="bg-white rounded-[2.5rem] p-6 md:p-8 border border-slate-100 shadow-xl relative overflow-hidden group">
            <div className="flex gap-4 mb-4">
                <img src={post.avatar} className="w-12 h-12 rounded-2xl border-2 border-slate-50" />
                <div>
                    <h4 className="font-black text-slate-800 text-sm flex items-center gap-1">{post.userName} {post.type === 'event' && <ShieldCheck size={14} className="text-amber-500" />}</h4>
                    <span className="text-[9px] font-black uppercase text-indigo-500">#{post.category}</span>
                </div>
            </div>
            <div className="text-sm md:text-base leading-relaxed mb-4 font-bold text-slate-700 whitespace-pre-wrap"><MarkdownText text={post.content} /></div>

            {post.aiAnalysis && (
                <div className="p-4 bg-indigo-50/50 rounded-2xl mb-4 border border-indigo-100/50 flex gap-3 items-start">
                    <Sparkles size={16} className="text-indigo-600 shrink-0 mt-1" />
                    <p className="text-[10px] font-bold text-indigo-900 italic leading-relaxed">{post.aiAnalysis}</p>
                </div>
            )}

            <div className="flex items-center gap-6 pt-4 border-t border-slate-50">
                <button onClick={() => onLike(post.id)} className={`flex items-center gap-1.5 text-[10px] font-black ${hasLiked ? 'text-rose-500' : 'text-slate-400'}`}><Heart size={18} fill={hasLiked ? 'currentColor' : 'none'} /> {post.likes.length}</button>
                <button onClick={() => setCommenting(!commenting)} className="flex items-center gap-1.5 text-[10px] font-black text-slate-400"><MessageSquare size={18} /> {post.comments.length}</button>
                <button className="ml-auto text-slate-300"><Share2 size={16}/></button>
            </div>

            {commenting && (
                <div className="mt-4 animate-slide-up space-y-3">
                    <div className="max-h-40 overflow-y-auto space-y-2 p-2 bg-slate-50 rounded-2xl no-scrollbar">
                        {post.comments.map((c: any) => (
                            <div key={c.id} className="flex gap-2 text-[10px] font-bold text-slate-600"><span className="text-indigo-600">{c.userName}:</span> {c.content}</div>
                        ))}
                    </div>
                    <div className="flex gap-2">
                        <input value={txt} onChange={e => setTxt(e.target.value)} onKeyDown={e => e.key === 'Enter' && (onComment(post.id, txt), setTxt(''))} className="flex-1 bg-slate-100 px-4 py-2 rounded-xl text-[10px] font-bold outline-none" placeholder="Viết bình luận..." />
                        <button onClick={() => { onComment(post.id, txt); setTxt(''); }} className="p-2 bg-indigo-600 text-white rounded-xl"><Send size={14}/></button>
                    </div>
                </div>
            )}
        </div>
    );
});

const CreatePostModal = ({ onClose, onSubmit, isAnalyzing }: any) => {
    const [c, setC] = useState('');
    return (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[100] flex items-center justify-center p-6">
