import { GoogleGenAI, Type } from "@google/genai";

const FLASH_MODEL = 'gemini-3-flash-preview';

// Initialize Gemini AI client using process.env.API_KEY directly as required.
const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const parseGeminiJSON = (text: string, defaultValue: any) => {
  try {
    if (!text) return defaultValue;
    let cleaned = text.replace(/```json/gi, '').replace(/```/g, '').trim();
    const firstBrace = cleaned.indexOf('{');
    const firstBracket = cleaned.indexOf('[');
    let startIdx = -1;
    let endIdx = -1;

    if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
      startIdx = firstBrace;
      endIdx = cleaned.lastIndexOf('}');
    } else if (firstBracket !== -1) {
      startIdx = firstBracket;
      endIdx = cleaned.lastIndexOf(']');
    }

    if (startIdx !== -1 && endIdx !== -1) {
      return JSON.parse(cleaned.substring(startIdx, endIdx + 1));
    }
    return JSON.parse(text);
  } catch (e) {
    console.error("JSON Parse Fail:", e);
    return defaultValue;
  }
};

export const getTutorResponse = async (msg: string, mode: 'teen' | 'academic' = 'teen') => {
  const ai = getAIInstance();
  const instructions = {
    teen: "Bạn là một gia sư Gen Z cực kỳ vui tính, lầy lội, sử dụng ngôn ngữ 'teen code' một cách tinh tế nhưng vẫn đảm bảo kiến thức chính xác 100%. Trả lời cực ngắn gọn, súc tích, nhiều icon.",
    academic: "Bạn là một giáo sư chuyên gia giáo dục hàng đầu. Trả lời một cách chuyên sâu, học thuật, có cấu trúc rõ ràng (bullet points), sử dụng thuật ngữ chuẩn mực và cung cấp các ví dụ thực tế."
  };

  try {
    const res = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: msg,
      config: { 
        systemInstruction: instructions[mode],
        temperature: mode === 'teen' ? 0.9 : 0.4 
      }
    });
    // Access .text property directly as per guidelines
    return res.text || "AI đang bận, thử lại sau nhé!";
  } catch (e) {
    return "Mạng lag quá, fen hỏi lại đi.";
  }
};

