const Feed: React.FC<{ userData: UserProfile; onExp: (n: number) => void; showToast: (m: string, t: 'success' | 'error') => void }> = ({ userData, onExp, showToast }) => {
  const [posts, setPosts] = useState<Post[]>([]);
