  return [...LEVELS].reverse().find(l => exp >= l.min) || LEVELS[0];
};

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Home, Zap, Trophy, Send, Sparkles, Heart, MessageCircle, 
  Plus, Bot, Stars, Search, Menu, X, Flame, Share2, 
  Edit3, Layout, Calculator, User, Award, Users, Settings,
  CheckCircle2, Crown, Ghost, BookOpen, GraduationCap,
  LogOut, ArrowRight, Bell, Clock, BrainCircuit, Target, 
  ThumbsUp, Smile, MoreHorizontal, ThumbsDown, Scale,
  ChevronRight, Calendar, LayoutGrid, FireExtinguisher,
  ShieldCheck, Globe, Facebook, Key, MessageSquare, Compass, 
  Star, CheckCircle, BarChart3, ListTodo, Rocket, Shield,
  RefreshCw, AlertTriangle, Grid3X3, Gem
} from 'lucide-react';
import { UserProfile, AppTab, LoginMethod, DailyQuest, QuestType } from './types';
import { getLevelInfo, BADGES } from './constants';
import Feed from './components/Feed';
import AITutor from './components/AITutor';
import FocusZone from './components/FocusZone';
import QuizArena from './components/QuizArena';
import Leaderboard from './components/Leaderboard';
import Profile from './components/Profile';
import StudyTools from './components/StudyTools';
import MissionControl from './components/MissionControl';

const INITIAL_QUESTS: DailyQuest[] = [
  { id: 'q1', type: 'focus_time', text: 'Học tập trung 15 phút (Anh/Toán)', target: 15, current: 0, reward: 100, gems: 20, isClaimed: false },
  { id: 'q2', type: 'quiz_correct', text: 'Giải đúng 10 câu trắc nghiệm', target: 10, current: 0, reward: 150, gems: 30, isClaimed: false },
  { id: 'q3', type: 'ai_interaction', text: 'Hỏi Gia sư AI 3 câu hỏi', target: 3, current: 0, reward: 50, gems: 10, isClaimed: false }
];

const App: React.FC = () => {
  const [userData, setUserData] = useState<UserProfile | null>(null);
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.FEED);
  const [showMenu, setShowMenu] = useState(false);
  const [loading, setLoading] = useState(true);
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);
  const [levelUpModal, setLevelUpModal] = useState<string | null>(null); // Stores new title if leveled up

  // --- TOAST SYSTEM ---
  const showToast = useCallback((message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  }, []);

  // --- DATA PERSISTENCE ---
  useEffect(() => {
    const saved = localStorage.getItem('studygram_user');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        // Streak Logic Check
        const lastLogin = parsed.lastLogin ? new Date(parsed.lastLogin).toDateString() : '';
        const today = new Date().toDateString();
        if (lastLogin !== today) {
           const d1 = new Date(parsed.lastLogin || 0);
           const d2 = new Date();
           const diff = Math.floor((d2.getTime() - d1.getTime()) / (1000 * 3600 * 24));

           // New Day Reset Logic
           parsed.dailyQuests = INITIAL_QUESTS; 

           if (diff > 1 && diff < 30000) { // Lost streak
              parsed.streak = 1;
           } else if (diff === 1) { // Keep streak
              parsed.streak += 1;
           }
           parsed.lastLogin = Date.now();
        }
        setUserData(parsed);
      } catch (e) { console.error("Data error", e); }
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    if (userData) {
      localStorage.setItem('studygram_user', JSON.stringify(userData));
      checkBadges(userData);
    }
  }, [userData]);

  const handleAuth = (name: string) => {
    const newUser: UserProfile = {
      uid: 'u-' + Math.random().toString(36).slice(2, 7),
      name: name || 'Học giả Ẩn danh',
      avatar: `https://api.dicebear.com/7.x/notionists/svg?seed=${name}${Date.now()}`,
      exp: 0, 
      gems: 50, // Starting gems
      bio: 'Sẵn sàng chinh phục tri thức!', joinedAt: Date.now(),
      streak: 1, lives: 5, streakShields: 0, completedQuizzes: 0,
      dailyQuests: INITIAL_QUESTS,
      badges: [],
      skills: { criticalThinking: 10, focus: 10, creativity: 10, knowledge: 10, discipline: 10 },
      weakPoints: [],
      lastLogin: Date.now()
    };
    setUserData(newUser);
    showToast(`Chào mừng ${newUser.name}!`, 'success');
  };

  const checkLevelUp = (oldExp: number, newExp: number) => {
    const oldLevel = getLevelInfo(oldExp);
    const newLevel = getLevelInfo(newExp);
    if (newLevel.title !== oldLevel.title) {
      setLevelUpModal(newLevel.title);
      // Play sound or confetti here
      // @ts-ignore
      if (window.confetti) window.confetti({ particleCount: 200, spread: 120, origin: { y: 0.6 } });
    }
  };

  const addExp = (amount: number) => {
    if (userData) {
      const newExp = userData.exp + amount;
      checkLevelUp(userData.exp, newExp);
      setUserData(prev => prev ? { ...prev, exp: newExp } : null);
      if (amount > 0) showToast(`+${amount} EXP`, 'success');
    }
  };

  const handleQuestProgress = (type: QuestType, amount: number) => {
    if (!userData) return;
    setUserData(prev => {
      if (!prev) return null;
      const newQuests = prev.dailyQuests.map(q => {
        if (q.type === type && !q.isClaimed) {
          const newCurrent = Math.min(q.current + amount, q.target);
          if (newCurrent === q.target && q.current < q.target) {
            showToast("Nhiệm vụ hoàn thành! Nhận thưởng ngay!", "success");
          }
          return { ...q, current: newCurrent };
        }
        return q;
      });
      return { ...prev, dailyQuests: newQuests };
    });
  };

  const checkBadges = (u: UserProfile) => {
    const newBadges = [...u.badges];
    let added = false;
    BADGES.forEach(badge => {
      if (!newBadges.includes(badge.id) && badge.condition(u)) {
        newBadges.push(badge.id);
        added = true;
        showToast(`Mở khóa huy hiệu: ${badge.name}`, 'success');
      }
    });
    if (added) {
      setUserData(prev => prev ? { ...prev, badges: newBadges } : null);
    }
  };

  // --- RENDER LOADING / AUTH ---
  if (loading) return (
    <div className="h-screen flex items-center justify-center bg-[#FDFCF8]">
       <div className="flex flex-col items-center gap-4 animate-pulse">
          <div className="w-16 h-16 bg-indigo-600 rounded-2xl"></div>
          <div className="text-xl font-black text-slate-300 tracking-widest uppercase">StudyGram Loading...</div>
       </div>
    </div>
  );

  if (!userData) return (
    <div className="min-h-screen bg-[#FDFCF8] flex items-center justify-center p-6 relative overflow-hidden">
      <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-5"></div>
      <div className="absolute top-[-20%] right-[-10%] w-[500px] h-[500px] bg-indigo-500/20 rounded-full blur-[100px] animate-pulse"></div>

      <div className="glass p-10 rounded-[3.5rem] w-full max-w-md text-center relative z-10 border-2 border-white/50 shadow-2xl animate-slide-up">
        <div className="w-24 h-24 bg-gradient-to-br from-indigo-600 to-purple-700 rounded-[2rem] mx-auto mb-8 flex items-center justify-center text-white shadow-xl shadow-indigo-200">
           <Rocket size={40} />
        </div>
        <h1 className="text-4xl font-black text-slate-800 mb-2 tracking-tighter">StudyGram</h1>
        <p className="text-slate-500 font-bold mb-8 text-sm uppercase tracking-widest">Kỷ nguyên học tập sinh tồn</p>

        <input id="name-input" placeholder="Nhập biệt danh..." className="w-full p-6 bg-slate-50 rounded-[1.5rem] mb-4 font-black text-center text-lg outline-none border-2 border-transparent focus:border-indigo-200 transition-all placeholder:text-slate-300" />

        <button onClick={() => {
          const input = document.getElementById('name-input') as HTMLInputElement;
          if (input.value.trim()) handleAuth(input.value);
          else showToast("Hãy nhập tên để bắt đầu!", "error");
        }} className="w-full py-6 bg-slate-900 text-white rounded-[1.5rem] font-black text-lg shadow-2xl hover:scale-105 active:scale-95 transition-all">
          BẮT ĐẦU NGAY 🚀
        </button>
      </div>
    </div>
  );

  // --- MAIN APP RENDER ---
  return (
    <div className="min-h-screen bg-[#FDFCF8] text-slate-800 font-sans selection:bg-indigo-100 pb-20">
      {/* HEADER */}
      <header className="fixed top-0 inset-x-0 h-24 bg-white/80 backdrop-blur-xl z-40 flex items-center justify-between px-6 border-b border-slate-100">
         <div className="flex items-center gap-3" onClick={() => setActiveTab(AppTab.FEED)}>
            <div className="w-11 h-11 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-200 cursor-pointer">
               <Bot size={22} />
            </div>
            <div>
               <h1 className="font-black text-xl tracking-tighter text-slate-800 leading-none">STUDYGRAM</h1>
               <div className="flex items-center gap-2">
                 <span className="text-[9px] font-black uppercase tracking-[0.2em] text-indigo-500">Supreme Edition</span>
                 <div className="bg-amber-100 px-2 py-0.5 rounded-full flex items-center gap-1 border border-amber-200">
                    <Gem size={8} className="text-amber-600" />
                    <span className="text-[9px] font-black text-amber-700">{userData.gems}</span>
                 </div>
               </div>
            </div>
         </div>

         <div className="flex items-center gap-2" onClick={() => setActiveTab(AppTab.PROFILE)}>
             <div className="text-right hidden md:block">
                <div className="text-xs font-black text-slate-800">{userData.name}</div>
                <div className="flex items-center justify-end gap-1">
                  <div className="text-[9px] font-black text-slate-400 uppercase">LV.{Math.floor(userData.exp/100)}</div>
                  <div className="flex items-center text-[9px] font-black text-orange-500"><Flame size={10} fill="currentColor"/> {userData.streak}</div>
                </div>
             </div>
             <img src={userData.avatar} className="w-11 h-11 rounded-[1rem] bg-slate-100 border-2 border-white shadow-md cursor-pointer hover:scale-105 transition-transform" />
         </div>
      </header>

      {/* BODY CONTENT */}
      <main className="pt-28 px-4 max-w-2xl mx-auto w-full min-h-screen">
         {activeTab === AppTab.FEED && <Feed userData={userData} onExp={addExp} showToast={showToast} />}
         {activeTab === AppTab.TUTOR && <AITutor userData={userData} onExp={addExp} onQuestProgress={handleQuestProgress} />}
         {activeTab === AppTab.MISSION && <MissionControl userData={userData} onUpdate={setUserData} onQuestProgress={handleQuestProgress} onExp={addExp} />}
         {activeTab === AppTab.RANK && <Leaderboard currentUid={userData.uid} userData={userData} />}
         {activeTab === AppTab.PROFILE && <Profile userData={userData} onUpdate={setUserData} onToast={showToast} />}
         {activeTab === AppTab.TOOLS && <StudyTools onExp={addExp} />}
         {activeTab === AppTab.QUIZ && <QuizArena onExp={addExp} showToast={showToast} onQuestProgress={handleQuestProgress} />}
         {activeTab === AppTab.FOCUS && <FocusZone onExp={addExp} showToast={showToast} onQuestProgress={handleQuestProgress} />}
      </main>

      {/* TOAST NOTIFICATION */}
      {toast && (
        <div className={`fixed top-28 left-1/2 -translate-x-1/2 px-6 py-3 rounded-full shadow-2xl z-[100] font-black text-xs uppercase tracking-widest flex items-center gap-3 animate-bounce ${toast.type === 'success' ? 'bg-slate-900 text-white' : 'bg-rose-500 text-white'}`}>
           {toast.type === 'success' ? <CheckCircle2 size={16}/> : <AlertTriangle size={16}/>}
           {toast.message}
        </div>
      )}

      {/* LEVEL UP MODAL */}
      {levelUpModal && (
        <div className="fixed inset-0 z-[150] bg-slate-900/80 backdrop-blur-md flex items-center justify-center p-6" onClick={() => setLevelUpModal(null)}>
          <div className="bg-white w-full max-w-sm rounded-[3rem] p-8 text-center animate-slide-up relative overflow-hidden">
             <div className="absolute inset-0 bg-gradient-to-br from-indigo-500/20 to-purple-500/20 animate-pulse"></div>
             <div className="relative z-10">
                <Crown size={64} className="mx-auto text-amber-500 mb-4 animate-bounce drop-shadow-lg" fill="currentColor"/>
                <h2 className="text-3xl font-black text-slate-800 mb-2">LEVEL UP!</h2>
                <p className="text-slate-500 font-bold mb-6">Bạn đã đạt danh hiệu:</p>
                <div className="inline-block px-8 py-3 bg-gradient-to-r from-indigo-600 to-purple-600 text-white font-black text-xl rounded-2xl shadow-xl shadow-indigo-200 mb-8 uppercase tracking-widest">
                   {levelUpModal}
                </div>
                <button onClick={() => setLevelUpModal(null)} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black shadow-lg hover:scale-105 transition-all">TIẾP TỤC</button>
             </div>
          </div>
        </div>
      )}

      {/* SUPER MENU OVERLAY */}
      {showMenu && (
        <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-md flex flex-col justify-end" onClick={() => setShowMenu(false)}>
           <div className="bg-[#FDFCF8] rounded-t-[3rem] p-8 pb-32 animate-slide-up shadow-2xl" onClick={e => e.stopPropagation()}>
              <div className="flex justify-between items-center mb-8 px-2">
                 <h3 className="text-2xl font-black text-slate-800 tracking-tight">Menu Mở Rộng</h3>
                 <button onClick={() => setShowMenu(false)} className="p-2 bg-slate-100 rounded-full text-slate-400 hover:bg-rose-100 hover:text-rose-500 transition-colors"><X size={24}/></button>
              </div>

              <div className="grid grid-cols-4 gap-4">
                 {[
                    { id: AppTab.TOOLS, icon: LayoutGrid, label: 'Công cụ', color: 'bg-emerald-500' },
                    { id: AppTab.QUIZ, icon: BrainCircuit, label: 'Đấu trường', color: 'bg-rose-500' },
                    { id: AppTab.FOCUS, icon: Clock, label: 'Tập trung', color: 'bg-amber-500' },
                    { id: AppTab.PROFILE, icon: User, label: 'Hồ sơ', color: 'bg-indigo-500' },
                 ].map(item => (
                    <button key={item.id} onClick={() => { setActiveTab(item.id); setShowMenu(false); }} className="flex flex-col items-center gap-3 group">
                       <div className={`w-16 h-16 ${item.color} rounded-[1.5rem] flex items-center justify-center text-white shadow-xl transition-transform group-active:scale-90 group-hover:scale-110`}>
                          <item.icon size={28} />
                       </div>
                       <span className="text-[10px] font-black uppercase text-slate-500 tracking-wider">{item.label}</span>
                    </button>
                 ))}
              </div>
           </div>
        </div>
      )}

      {/* BOTTOM NAVIGATION */}
      <nav className="fixed bottom-6 left-1/2 -translate-x-1/2 w-[92%] max-w-md z-40">
        <div className="bg-white/90 backdrop-blur-xl rounded-[2.5rem] p-2 flex justify-between shadow-[0_10px_40px_-10px_rgba(0,0,0,0.1)] border border-white/50 ring-1 ring-slate-900/5">
          {[
            { id: AppTab.FEED, icon: Home },
            { id: AppTab.MISSION, icon: Target },
            { id: AppTab.TUTOR, icon: Bot },
            { id: AppTab.RANK, icon: Trophy },
          ].map(t => (
            <button 
               key={t.id} 
               onClick={() => setActiveTab(t.id)} 
               className={`w-14 h-14 rounded-[1.8rem] flex items-center justify-center transition-all duration-300 ${
                  activeTab === t.id 
                  ? 'bg-slate-900 text-white shadow-lg scale-110 -translate-y-2' 
                  : 'text-slate-400 hover:bg-slate-100'
               }`}
            >
              <t.icon size={24} strokeWidth={activeTab === t.id ? 3 : 2} />
            </button>
          ))}

          <button 
             onClick={() => setShowMenu(true)} 
             className={`w-14 h-14 rounded-[1.8rem] flex items-center justify-center transition-all duration-300 ${
                showMenu || ![AppTab.FEED, AppTab.MISSION, AppTab.TUTOR, AppTab.RANK].includes(activeTab)
                ? 'bg-indigo-600 text-white shadow-lg scale-110 -translate-y-2' 
                : 'text-slate-400 hover:bg-slate-100'
             }`}
          >
             <Grid3X3 size={24} strokeWidth={2.5} />
          </button>
        </div>
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Rocket, ChevronRight, CheckCircle, Loader2, 
  ArrowLeft, GraduationCap, Zap, Info, HelpCircle,
  XCircle, Award, ListOrdered, BarChart, Timer, AlertTriangle, RefreshCw,
  Gift, Gem, CheckCircle2
} from 'lucide-react';
import { UserProfile, StudyMission, Grade, ExamDifficulty, QuestType } from '../types';
import { generateExamRoadmap, generateExamPaper } from '../services/geminiService';

interface MissionControlProps {
  userData: UserProfile;
  onUpdate: (u: UserProfile) => void;
  onQuestProgress: (type: QuestType, amount: number) => void;
  onExp: (amount: number) => void;
}

const MissionControl: React.FC<MissionControlProps> = ({ userData, onUpdate, onQuestProgress, onExp }) => {
  const [loading, setLoading] = useState(false);
  const [loadingNodeId, setLoadingNodeId] = useState<string | null>(null);
  const [grade, setGrade] = useState<Grade>(userData.currentMission?.grade || '12');
  const [subject, setSubject] = useState(userData.currentMission?.subject || 'Toán học');
  const [questionCount, setQuestionCount] = useState<number>(10);
  const [activeExam, setActiveExam] = useState<any[] | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);

  const [userAnswers, setUserAnswers] = useState<Record<number, string>>({});
  const [isReviewed, setIsReviewed] = useState(false);

  // CLAIM QUEST LOGIC
  const claimQuest = (questId: string) => {
    const quest = userData.dailyQuests.find(q => q.id === questId);
    if (!quest || quest.isClaimed || quest.current < quest.target) return;

    onExp(quest.reward);
    const updatedQuests = userData.dailyQuests.map(q => 
        q.id === questId ? { ...q, isClaimed: true } : q
    );
    const updatedUser = { 
        ...userData, 
        dailyQuests: updatedQuests,
        gems: userData.gems + quest.gems 
    };
    onUpdate(updatedUser);
  };

  // --- LOGIC CHẤM ĐIỂM THÔNG MINH ---
  const checkAnswer = (userSelectedText: string, question: any) => {
    if (!userSelectedText || !question || !question.answer) return false;
    const correctRaw = question.answer.toString().trim();
    const userRaw = userSelectedText.toString().trim();
    if (correctRaw === userRaw) return true;
    const selectedIndex = question.options.indexOf(userRaw);
    if (selectedIndex !== -1) {
      const selectedLetter = String.fromCharCode(65 + selectedIndex);
      if (correctRaw.toUpperCase() === selectedLetter) return true;
      if (correctRaw.startsWith(selectedLetter + ".") || correctRaw.startsWith(selectedLetter + ":")) return true;
    }
    return false;
  };

  const startMission = async () => {
    setLoading(true);
    setLoadError(null);
    try {
      const roadmapData = await generateExamRoadmap(grade, subject);
      if (!roadmapData || !roadmapData.roadmap || roadmapData.roadmap.length === 0) {
          throw new Error("Empty Roadmap");
      }
      const newMission: StudyMission = {
        goal: 'THPTQG',
        grade: grade,
        targetDate: Date.now() + 60 * 24 * 60 * 60 * 1000,
        subject: subject,
        roadmap: roadmapData.roadmap.map((n: any) => ({
          ...n,
          status: 'current'
        }))
      };
      onUpdate({ ...userData, currentMission: newMission });
    } catch (e) {
      setLoadError("Không thể tạo lộ trình lúc này. Hãy thử lại!");
    } finally {
      setLoading(false);
    }
  };

  const loadExam = async (nodeId: string, difficulty: ExamDifficulty) => {
    setLoadingNodeId(nodeId);
    setLoadError(null);
    setUserAnswers({});
    setIsReviewed(false);
    try {
      const exam = await generateExamPaper(subject, grade, difficulty, questionCount);
      if (exam && exam.length > 0) {
        setActiveExam(exam);
      } else {
        setLoadError("Không tải được câu hỏi. AI đang quá tải.");
      }
    } catch (e) {
      setLoadError("Lỗi kết nối mạng.");
    } finally {
      setLoadingNodeId(null);
    }
  };

  const scoreInfo = useMemo(() => {
    if (!activeExam) return { correct: 0, total: 0, exp: 0 };
    let correct = 0;
    activeExam.forEach((q, i) => {
      if (checkAnswer(userAnswers[i], q)) correct++;
    });
    return {
      correct,
      total: activeExam.length,
      exp: correct * 30 
    };
  }, [activeExam, userAnswers]);

  const finishExam = () => {
    if (!isReviewed) {
      setIsReviewed(true);
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }

    // UPDATE PROGRESS
    onUpdate({
      ...userData,
      exp: userData.exp + scoreInfo.exp,
      completedQuizzes: userData.completedQuizzes + 1
    });

    // QUEST UPDATE
    if (scoreInfo.correct > 0) {
        onQuestProgress('quiz_correct', scoreInfo.correct);
    }

    setActiveExam(null);
    if (scoreInfo.correct / scoreInfo.total > 0.5) {
      // @ts-ignore
      if (window.confetti) window.confetti({ particleCount: 150, spread: 100, origin: { y: 0.6 } });
    }
  };

  const handleSelect = (qIdx: number, option: string) => {
    if (isReviewed) return;
    setUserAnswers(prev => ({ ...prev, [qIdx]: option }));
  };

  // GIAO DIỆN LÀM BÀI
  if (activeExam) {
    return (
      <div className="content-container animate-in space-y-4 px-4 pb-40">
        <div className="bg-white/95 backdrop-blur-md p-4 sticky top-0 z-30 -mx-4 mb-4 border-b border-slate-100 flex items-center justify-between shadow-sm">
          <button onClick={() => setActiveExam(null)} className="flex items-center gap-2 text-slate-500 font-bold text-sm">
            <ArrowLeft size={16} /> THOÁT
          </button>
          <div className="flex gap-2">
            <div className="bg-slate-100 px-3 py-1.5 rounded-full text-[10px] font-black text-slate-500 uppercase">
              {Object.keys(userAnswers).length}/{activeExam.length} CÂU
            </div>
            {isReviewed && (
              <div className="bg-indigo-600 text-white px-3 py-1.5 rounded-full text-[10px] font-black uppercase">
                ĐÚNG {scoreInfo.correct}/{scoreInfo.total}
              </div>
            )}
          </div>
        </div>

        {isReviewed && (
          <div className="bg-gradient-to-br from-indigo-600 to-purple-700 p-8 rounded-[2.5rem] text-white shadow-xl animate-slide-up mb-8">
            <div className="flex justify-between items-center mb-4">
              <Award size={48} className="opacity-50" />
              <div className="text-right">
                <p className="text-[10px] font-black uppercase tracking-widest opacity-70">Kết quả</p>
                <h4 className="text-4xl font-black">{Math.round((scoreInfo.correct / scoreInfo.total) * 100)}%</h4>
              </div>
            </div>
            <p className="font-bold text-sm mb-4 opacity-90 italic">
              {scoreInfo.correct === scoreInfo.total ? "Tuyệt vời! Fen là thiên tài! 🚀" : 
               scoreInfo.correct > scoreInfo.total / 2 ? "Khá tốt! Xem lại lỗi sai nhé. ✨" : 
               "Cố gắng lên, đọc kỹ giải thích bên dưới."}
            </p>
            <div className="bg-white/20 p-4 rounded-2xl flex items-center justify-between border border-white/10">
              <span className="text-xs font-black uppercase tracking-widest">Thưởng:</span>
              <span className="text-xl font-black">+{scoreInfo.exp} EXP</span>
            </div>
          </div>
        )}

        <div className="space-y-8">
          {activeExam.map((q, i) => {
            const isCorrect = checkAnswer(userAnswers[i], q);
            const isSelected = userAnswers[i] !== undefined;

            return (
              <div key={i} className={`bg-white rounded-[2.5rem] p-8 border-2 shadow-sm transition-all ${
                isReviewed ? (isCorrect ? 'border-green-200' : 'border-rose-100') : 'border-slate-50'
              }`}>
                <div className="flex items-start gap-4 mb-6">
                  <span className={`shrink-0 w-10 h-10 rounded-2xl flex items-center justify-center font-black text-sm ${
                    isReviewed ? (isCorrect ? 'bg-green-500 text-white' : 'bg-rose-500 text-white') : 'bg-slate-900 text-white'
                  }`}>
                    {i+1}
                  </span>
                  <p className="font-bold text-slate-800 leading-snug text-lg pt-1">{q.question}</p>
                </div>

                <div className="grid grid-cols-1 gap-3">
                  {q.options.map((opt: string, idx: number) => {
                    const optionChar = String.fromCharCode(65 + idx);
                    const isThisSelected = userAnswers[i] === opt;
                    const isRightAnswer = checkAnswer(opt, q);

                    let btnStyle = "bg-slate-50 border-transparent text-slate-600";
                    if (isReviewed) {
                       if (isRightAnswer) btnStyle = "bg-green-500 border-green-500 text-white shadow-lg";
                       else if (isThisSelected) btnStyle = "bg-rose-500 border-rose-500 text-white";
                       else btnStyle = "bg-slate-50 border-transparent text-slate-300";
                    } else if (isThisSelected) {
                       btnStyle = "bg-indigo-50 border-indigo-600 text-indigo-700 scale-[1.02] shadow-md";
                    }

                    return (
                      <button 
                        key={idx} 
                        disabled={isReviewed}
                        onClick={() => handleSelect(i, opt)}
                        className={`group p-5 text-left text-sm rounded-2xl border-2 transition-all flex items-center gap-4 ${btnStyle}`}
                      >
                        <span className={`w-8 h-8 rounded-lg flex items-center justify-center font-black text-xs shrink-0 ${
                          isReviewed ? 'bg-white/20' : (isThisSelected ? 'bg-indigo-600 text-white' : 'bg-white border-slate-200 text-slate-400')
                        }`}>
                          {optionChar}
                        </span>
                        <span className="flex-1 font-semibold">{opt}</span>
                      </button>
                    );
                  })}
                </div>

                {isReviewed && (
                  <div className={`mt-6 p-6 rounded-3xl border ${isCorrect ? 'bg-green-50 border-green-100' : 'bg-slate-50 border-slate-100'}`}>
                    <div className="flex items-center gap-2 mb-2">
                       <HelpCircle size={16} className="text-indigo-600" />
                       <span className="text-[10px] font-black uppercase tracking-widest text-indigo-700">Giải thích AI</span>
                    </div>
                    <p className="text-sm font-bold text-slate-600 leading-relaxed italic">
                      {q.explanation || "Đang cập nhật..."}
                    </p>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        <div className="mt-12">
           <button 
             onClick={finishExam} 
             disabled={!isReviewed && Object.keys(userAnswers).length < activeExam.length}
             className={`w-full py-6 rounded-3xl font-black shadow-2xl transition-all text-lg flex items-center justify-center gap-3 ${
               isReviewed ? 'bg-slate-900 text-white' : 'bg-indigo-600 text-white disabled:opacity-50'
             }`}
           >
              {isReviewed ? <ArrowLeft size={24}/> : <Rocket size={24}/>}
              {isReviewed ? 'XONG' : 'NỘP BÀI'}
           </button>
        </div>
      </div>
    );
  }

  // --- DAILY QUESTS SECTION (LUÔN HIỂN THỊ TRƯỚC SETUP) ---
  const DailyQuestsSection = () => (
    <div className="mb-8 animate-slide-up">
       <div className="flex items-center gap-3 mb-4 px-2">
          <div className="w-10 h-10 bg-gradient-to-br from-amber-400 to-orange-500 rounded-xl flex items-center justify-center text-white shadow-lg">
             <Target size={22} />
          </div>
          <div>
             <h3 className="text-lg font-black text-slate-800">Nhiệm Vụ Hàng Ngày</h3>
             <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Làm mới sau 24h</p>
          </div>
       </div>

       <div className="space-y-3">
          {userData.dailyQuests.map(q => {
             const progress = Math.min(100, (q.current / q.target) * 100);
             const canClaim = q.current >= q.target && !q.isClaimed;
             return (
               <div key={q.id} className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm relative overflow-hidden group">
                  <div className="flex justify-between items-start relative z-10 mb-3">
                     <div>
                        <p className="text-sm font-bold text-slate-700 mb-1">{q.text}</p>
                        <div className="flex items-center gap-2">
                           <span className="text-[10px] bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded-lg font-black uppercase tracking-wider">+{q.reward} EXP</span>
                           <span className="text-[10px] bg-amber-50 text-amber-600 px-2 py-0.5 rounded-lg font-black uppercase tracking-wider flex items-center gap-1"><Gem size={8}/> +{q.gems}</span>
                        </div>
                     </div>
                     {canClaim ? (
                        <button onClick={() => claimQuest(q.id)} className="bg-gradient-to-r from-amber-400 to-orange-500 text-white px-4 py-2 rounded-xl font-black text-[10px] uppercase shadow-lg animate-bounce hover:scale-110 transition-transform">
                           Nhận!
                        </button>
                     ) : q.isClaimed ? (
                        <div className="text-green-500 font-black text-[10px] uppercase flex items-center gap-1 bg-green-50 px-3 py-1 rounded-xl">
                           <CheckCircle2 size={12}/> Xong
                        </div>
                     ) : (
                        <div className="text-slate-300 font-black text-xs">
                           {q.current}/{q.target}
                        </div>
                     )}
                  </div>
                  {/* Progress Bar */}
                  <div className="h-2 bg-slate-100 rounded-full overflow-hidden">
                     <div className={`h-full rounded-full transition-all duration-1000 ${q.isClaimed ? 'bg-green-500' : 'bg-indigo-500'}`} style={{ width: `${progress}%` }}></div>
                  </div>
               </div>
             );
          })}
       </div>
    </div>
  );

  // GIAO DIỆN CHỌN MÔN (Setup)
  if (!userData.currentMission) {
    return (
      <div className="content-container animate-in space-y-8 px-4 py-6">
        {/* DAILY QUESTS FIRST */}
        <DailyQuestsSection />

        <div className="text-center space-y-2 border-t border-slate-100 pt-8">
          <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center text-white mx-auto shadow-2xl mb-6">
             <GraduationCap size={40} />
          </div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Cấu hình Ôn thi</h2>
          <p className="text-slate-500 text-sm font-bold opacity-70 italic">SGK mới 2018 - Chuẩn Sở GD</p>
        </div>

        {loadError && (
          <div className="p-4 bg-rose-50 text-rose-600 rounded-2xl text-xs font-bold text-center border border-rose-100 animate-pulse flex items-center justify-center gap-2">
            <AlertTriangle size={16}/> {loadError}
          </div>
        )}

        <div className="space-y-6">
          <div className="flex gap-2 p-1.5 bg-slate-100 rounded-[2rem]">
            {['10', '11', '12'].map(g => (
              <button key={g} onClick={() => setGrade(g as Grade)} className={`flex-1 py-4 rounded-[1.5rem] font-black text-xs transition-all ${grade === g ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>LỚP {g}</button>
            ))}
          </div>

          <div className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-4">
            <div className="flex items-center gap-2 mb-2">
               <ListOrdered size={16} className="text-indigo-600"/>
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Quy mô đề</label>
            </div>
            <div className="grid grid-cols-4 gap-2">
              {[10, 20, 30, 40].map(c => (
                <button key={c} onClick={() => setQuestionCount(c)} className={`py-3 rounded-xl text-xs font-black transition-all border-2 ${questionCount === c ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg' : 'bg-slate-50 border-transparent text-slate-500'}`}>{c} CÂU</button>
              ))}
            </div>
          </div>

          <div className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm">
            <div className="flex items-center gap-2 mb-4">
               <BarChart size={16} className="text-indigo-600"/>
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Môn học</label>
            </div>
            <div className="grid grid-cols-2 gap-2">
              {['Toán học', 'Ngữ văn', 'Tiếng Anh', 'Vật lý', 'Hóa học', 'Sinh học', 'Lịch sử', 'Địa lý'].map(s => (
                <button key={s} onClick={() => setSubject(s)} className={`p-4 rounded-2xl text-xs font-bold border-2 transition-all ${subject === s ? 'bg-indigo-50 border-indigo-500 text-indigo-700' : 'bg-slate-50 border-transparent text-slate-500'}`}>{s}</button>
              ))}
            </div>
          </div>

          <button onClick={startMission} disabled={loading} className="w-full py-6 bg-slate-900 text-white rounded-3xl font-black shadow-2xl flex items-center justify-center gap-3 disabled:opacity-50 active:scale-95 transition-all text-lg">
            {loading ? <Loader2 className="animate-spin" /> : <Rocket size={24}/>}
            {loading ? 'ĐANG TẠO...' : 'KÍCH HOẠT LỘ TRÌNH'}
          </button>
        </div>
      </div>
    );
  }

  // GIAO DIỆN LỘ TRÌNH
  const mission = userData.currentMission;
  return (
    <div className="content-container animate-in space-y-8 px-4 py-2 pb-40">
       <DailyQuestsSection />

       <div className="bg-gradient-to-br from-indigo-700 via-indigo-600 to-purple-800 p-8 rounded-[3rem] text-white shadow-2xl relative overflow-hidden group">
          <div className="relative z-10">
             <div className="flex gap-2 mb-4">
                <span className="bg-white/20 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest border border-white/10 backdrop-blur-md">LỚP {mission.grade}</span>
                <span className="bg-white/20 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest border border-white/10 backdrop-blur-md">{mission.subject}</span>
             </div>
             <h3 className="text-3xl font-black tracking-tight leading-none mb-2">Chiến Dịch 2025</h3>
             <p className="text-indigo-100 text-[11px] font-bold uppercase tracking-[0.2em] opacity-80">Mở khóa toàn bộ chương mục</p>
          </div>
          <Zap size={100} className="absolute right-[-20px] bottom-[-20px] text-white/10 group-hover:scale-125 transition-transform duration-700" />
       </div>

       <div className="space-y-4">
          <div className="flex items-center justify-between px-2">
             <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Danh sách chương</h4>
             <span className="text-[10px] font-black text-indigo-600 bg-indigo-50 px-3 py-1 rounded-full border border-indigo-100 flex items-center gap-2"><Timer size={12}/> Đề {questionCount} câu</span>
          </div>

          {loadError && (
             <div className="p-4 bg-rose-50 border border-rose-100 rounded-3xl flex flex-col items-center gap-2 text-rose-600 text-center animate-shake">
               <div className="flex items-center gap-2 font-bold"><AlertTriangle size={20} /> <p className="text-xs">{loadError}</p></div>
               <button onClick={() => setLoadingNodeId(null)} className="text-[10px] uppercase font-black bg-white px-4 py-2 rounded-xl shadow-sm border border-rose-100 hover:bg-rose-50">Thử lại sau</button>
             </div>
          )}

          {mission.roadmap.map((node, i) => {
             const isLoadingThis = loadingNodeId === node.id;
             return (
                <button 
                  key={node.id} 
                  disabled={loadingNodeId !== null}
                  onClick={() => loadExam(node.id, node.difficulty)}
                  className={`w-full text-left clean-card p-6 rounded-[2.5rem] flex items-center gap-6 border-2 transition-all relative overflow-hidden hover:border-indigo-300 hover:bg-indigo-50/10 shadow-lg group ${isLoadingThis ? 'border-indigo-300 bg-indigo-50 pointer-events-none' : 'border-transparent'}`}
                >
                   <div className={`w-12 h-12 rounded-xl flex items-center justify-center text-white font-black shrink-0 shadow-lg transition-all bg-indigo-600 group-hover:scale-110`}>
                      {isLoadingThis ? <Loader2 className="animate-spin" size={20}/> : i + 1}
                   </div>
                   <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                         <span className="text-[8px] font-black px-2 py-0.5 rounded-full uppercase tracking-widest bg-slate-900 text-white">
                            {node.difficulty === 'theory' ? 'CƠ BẢN' : node.difficulty === 'practice' ? 'LUYỆN TẬP' : 'VẬN DỤNG'}
                         </span>
                      </div>
                      <h5 className="font-black text-base truncate tracking-tight text-slate-800">{node.title}</h5>
                   </div>
                   {!isLoadingThis && <ChevronRight size={20} className="text-indigo-400 group-hover:translate-x-1 transition-transform" />}
                </button>
             );
          })}
       </div>

       <div className="p-8 bg-slate-50 rounded-[3rem] border border-slate-100 text-center space-y-4">
          <Info size={32} className="mx-auto text-slate-300" />
          <p className="text-sm font-bold text-slate-500 italic leading-relaxed px-4">
            "Tip: Chọn '10 câu' để tải đề nhanh nhất."
          </p>
          <button onClick={() => onUpdate({...userData, currentMission: undefined})} className="text-indigo-600 font-black text-[10px] uppercase tracking-[0.3em] pt-4 hover:text-indigo-800">
             ĐỔI MÔN HỌC
          </button>
       </div>
    </div>
  );
};

export default MissionControl;

import React, { useState } from 'react';
import { UserProfile } from '../types';
import { getLevelInfo, BADGES } from '../constants';
import { Flame, BrainCircuit, ShieldCheck, Crown, Key, X, CheckCircle2, Share2, BarChart3, Sparkles, Medal, Gem } from 'lucide-react';
import { roastOrToast } from '../services/geminiService';

