                              ))}
                           </ul>
                        </div>
                    </div>

                    <div className="bg-orange-50/50 p-6 rounded-3xl border border-orange-100">
                        <h5 className="font-black text-orange-800 text-xs uppercase mb-2">Lời khuyên của AI</h5>
