               )}

               {/* HIỂN THỊ SƠ ĐỒ TƯ DUY / KẾ HOẠCH */}
               {(activeTool === 'mindmap' || activeTool === 'scheduler' || activeTool === 'summary') && typeof result === 'string' && (
                 <div className="space-y-6">
