import { GoogleGenAI, Type } from "@google/genai";

const FLASH_MODEL = 'gemini-3-flash-preview';

// Initialize Gemini AI client safely
const getAIInstance = () => {
  let apiKey = '';
  try {
    // Safely access process.env to avoid ReferenceError in browser environments
    if (typeof process !== 'undefined' && process.env) {
      apiKey = process.env.API_KEY || '';
    }
  } catch (e) {
    console.error("Failed to access API key from process.env", e);
  }
  return new GoogleGenAI({ apiKey });
};

const parseGeminiJSON = (text: string, defaultValue: any) => {
  try {
    if (!text) return defaultValue;
    // Remove markdown code blocks
    let cleaned = text.replace(/```json/gi, '').replace(/```/g, '').trim();

    // Find the first '{' or '[' and the last '}' or ']'
    const firstBrace = cleaned.indexOf('{');
    const firstBracket = cleaned.indexOf('[');
    let startIdx = -1;
    let endIdx = -1;

    // Determine if we are looking for an object or an array
    if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
      startIdx = firstBrace;
      endIdx = cleaned.lastIndexOf('}');
    } else if (firstBracket !== -1) {
      startIdx = firstBracket;
      endIdx = cleaned.lastIndexOf(']');
    }

    if (startIdx !== -1 && endIdx !== -1) {
      cleaned = cleaned.substring(startIdx, endIdx + 1);
    }

    return JSON.parse(cleaned);
  } catch (e) {
    console.error("JSON Parse Fail:", e, text);
    return defaultValue;
  }
};

