import { GoogleGenAI, Type } from "@google/genai";

const FLASH_MODEL = 'gemini-3-flash-preview';
const PRO_MODEL = 'gemini-3-pro-preview';

/**
 * Khởi tạo Gemini AI client theo đúng quy định.
 * Sử dụng trực tiếp process.env.API_KEY.
 */
const getAIInstance = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API key must be set when using the Gemini API.");
  }
  return new GoogleGenAI({ apiKey: apiKey });
};

const parseGeminiJSON = (text: string, defaultValue: any) => {
  if (!text) return defaultValue;
  try {
    return JSON.parse(text);
  } catch (e1) {
    try {
      let cleaned = text.replace(/```json/gi, '').replace(/```/g, '').trim();
      return JSON.parse(cleaned);
    } catch (e2) {
      try {
        const firstOpen = text.indexOf('{');
        const firstArray = text.indexOf('[');
        let startIdx = -1;
        let endIdx = -1;

        if (firstOpen !== -1 && (firstArray === -1 || firstOpen < firstArray)) {
           startIdx = firstOpen;
           endIdx = text.lastIndexOf('}');
        } else if (firstArray !== -1) {
           startIdx = firstArray;
           endIdx = text.lastIndexOf(']');
        }

        if (startIdx !== -1 && endIdx !== -1) {
            const jsonStr = text.substring(startIdx, endIdx + 1);
            return JSON.parse(jsonStr);
        }
        return defaultValue;
      } catch (e3) {
        return defaultValue;
      }
    }
  }
};

export const checkConnection = async () => {
  try {
    const ai = getAIInstance();
    await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: "Ping",
    });
    return true;
  } catch (e: any) {
    console.error("❌ [GeminiService] Connection Failed:", e);
    return false;
  }
};

/**
