      color: 'bg-indigo-600',
      gradient: 'from-indigo-500 to-blue-600',
      placeholder: 'Tìm kiếm đề thi (VD: Đề Toán 2024 Hà Nội)...'
    },
    { 
      id: 'quiz_creator', 
      name: 'AI Quiz Gen', 
      desc: 'Tự động tạo bộ đề trắc nghiệm theo chuẩn Sở GD.', 
      icon: GraduationCap, 
      color: 'bg-rose-500',
      gradient: 'from-rose-500 to-pink-600',
      placeholder: 'Chủ đề ôn thi...'
