import { GoogleGenAI, Type } from "@google/genai";

const FLASH_MODEL = 'gemini-3-flash-preview';
const PRO_MODEL = 'gemini-3-pro-preview';

const getAIInstance = () => {
  // API Key retrieval strictly from process.env.API_KEY as per guidelines.
  // We include a safe check for 'process' to prevent runtime errors in browsers without polyfills.
  let apiKey = '';
  try {
    if (typeof process !== 'undefined' && process.env) {
      apiKey = process.env.API_KEY || '';
    }
  } catch (e) {
    // process is not defined
  }

  if (!apiKey) {
    throw new Error("Chưa cấu hình API_KEY. Vui lòng thêm API_KEY vào file .env của bạn.");
  }

  return new GoogleGenAI({ apiKey });
};

const parseGeminiJSON = (text: string, defaultValue: any) => {
  if (!text) return defaultValue;
  try {
    return JSON.parse(text);
  } catch (e1) {
    try {
      let cleaned = text.replace(/```json/gi, '').replace(/```/g, '').trim();
      return JSON.parse(cleaned);
    } catch (e2) {
      try {
        const firstOpen = text.indexOf('{');
        const firstArray = text.indexOf('[');
        let startIdx = -1;
        let endIdx = -1;

        if (firstOpen !== -1 && (firstArray === -1 || firstOpen < firstArray)) {
           startIdx = firstOpen;
           endIdx = text.lastIndexOf('}');
        } else if (firstArray !== -1) {
           startIdx = firstArray;
           endIdx = text.lastIndexOf(']');
        }

        if (startIdx !== -1 && endIdx !== -1) {
            const jsonStr = text.substring(startIdx, endIdx + 1);
            return JSON.parse(jsonStr);
        }
        return defaultValue;
      } catch (e3) {
        return defaultValue;
      }
    }
  }
};

